window.DK_TERIM_DIZIN=window.DK_TERIM_DIZIN||{};DK_TERIM_DIZIN["mto302e"]={"v":"9c52725c10","terim":[{"id":"unit-celsius","tr":"Santigrat derece","en":"Celsius","kisa":"°C","tur":"birim","es":["santigrat","centigrade","derece santigrat","Degree Celsius","°C","derece selsiyus"],"tanim":["Standart atmosfer ve meteorolojik yüzey gözlemlerinde hava sıcaklığını belirtmek için kullanılan sıcaklık birimi.","SYNOP kodunda 1snTTT ve 2snTdTdTd gruplarında onda bir derece duyarlıkla kodlanır; istasyon modelinde tamsayı olarak yer alır.","Sinoptik analizde izotermlerin çiziminde ve adveksiyon hesaplarında temel termodinamik değişken olarak kullanılır."],"tanim_en":"Unit of temperature used in surface meteorological observations and synoptic charts, defined with the symbol °C.","bag":{"kavram":["adveksiyon","synop"],"soru":["S5","S6","S7","S8","S9"],"hesap":["kalinlik","sicaklik-kodu"]}},{"id":"cold-trough","tr":"Soğuk oluk","en":"Cold trough","kisa":"","tur":"kavram","es":["termal oluk","thermal trough","cold thermal trough"],"tanim":["Üst seviye ve kalınlık haritalarında soğuk havanın ekvatora doğru dil biçiminde sokulduğu alçak sıcaklık veya kalınlık oluğu.","İzotermlerin ekvatora doğru büküldüğü hat boyunca uzanır; arkasında kuvvetli soğuk adveksiyon görülür.","Sinoptik analizde sistemin baroklinikliğini, düşey eksen eğimini ve üst seviye trofunun gelişimini izlemekte yararlanılır."],"tanim_en":"An elongated region of relatively low atmospheric temperature or thickness extending towards lower latitudes on an upper-air chart.","bag":{"kavram":["adveksiyon","trof-sirt"],"soru":[],"hesap":[]}},{"id":"isotherm","tr":"İzoterm","en":"Isotherm","kisa":"T","tur":"kavram","es":["eş sıcaklık çizgisi","isothermal line"],"tanim":["Harita veya diyagram üzerinde eşit sıcaklığa sahip noktaları birleştiren eğri.","Sinoptik kartlarda genellikle kesikli çizgilerle gösterilir; çizgilerin sıklaştığı alanlar güçlü sıcaklık gradyanına işaret eder.","Üst seviye analizinde konturlarla kesiştiği bölgeler baroklinik yapıyı ve sıcaklık adveksiyonunu saptamada kullanılır."],"tanim_en":"A line on a meteorological chart connecting points of equal temperature.","bag":{"kavram":["adveksiyon","izoterm-tasima","merkez"],"soru":["S6","S7","S8","S9"],"hesap":["adveksiyon","izoterm-tasima"]}},{"id":"warm-tongue","tr":"Sıcak dil","en":"Warm tongue","kisa":"","tur":"kavram","es":["sıcak hava dili","termal sırt","Sıcak hava dili","warm isotherm tongue","sıcak izoterm dili","warm thermal ridge"],"tanim":["Sıcak hava alanının kutup yönünde belirgin biçimde uzanmasıyla oluşan termal yapı.","850 hPa seviyesinde izotermlerin kutba doğru çıkıntı yapmasıyla tanınır; ekseni boyunca yüksek sıcaklık değerleri izlenir.","Gelişen orta enlem siklonlarında sıcak sektörü gösterir ve 850 hPa haritasında oklüzyon cephesinin ekseni bu sıcak dilin merkezinden geçirilir."],"tanim_en":"A marked poleward extension of an area of warm air on a synoptic chart.","bag":{"kavram":["adveksiyon","trof-sirt","cekirdek"],"soru":[],"hesap":[]}},{"id":"zero-advection","tr":"Sıfır adveksiyon","en":"Zero advection","kisa":"0","tur":"kavram","es":["adveksiyon yokluğu","nötr adveksiyon","neutral advection","no advection"],"tanim":["Rüzgârın izotermlere paralel esmesi veya sıcaklık gradyanının bulunmaması sonucu yerel advektif sıcaklık değişiminin olmaması durumu.","Konturlar ile izotermlerin birbirine paralel uzandığı alanlarda kesme açısı sıfır olduğundan adveksiyon değeri 0 °C/s bulunur.","Eşdeğer barotropik atmosfer durumunu belirtir; bu alanlarda adveksiyona bağlı gelişme ya da sıcaklık değişimi beklenmez."],"tanim_en":"The condition where horizontal temperature advection is zero because wind blows parallel to isotherms or temperature gradient is absent.","bag":{"kavram":["adveksiyon"],"soru":["S7","S9"],"hesap":[]}},{"id":"crossing-angle","tr":"Kesme açısı","en":"Crossing angle","kisa":"α","tur":"olcu","es":["kesişme açısı","kontur-izoterm kesişme açısı","angle of intersection","cross-isobar angle"],"tanim":["Harita analizinde rüzgâr vektörü ile izoterm veya izobar çizgisi arasında oluşan geometrik kesişme açısı.","Yerde sürtünme nedeniyle rüzgâr izobarı deniz üzerinde 10–20°, kara üzerinde 25–40° açıyla alçak basınca doğru keser.","Üst seviyede konturların izotermleri kesme açısı 90°'ye yaklaştıkça adveksiyon şiddetlenir; açı sıfır olduğunda adveksiyon sıfırlanır."],"tanim_en":"The angle at which wind vectors or contours intersect isobars or isotherms on a weather map.","bag":{"kavram":["adveksiyon","barotropik"],"soru":["S2","S7","S9"],"hesap":["adveksiyon"]}},{"id":"rate-of-temperature-change","tr":"Sıcaklık değişim hızı","en":"Rate of temperature change","kisa":"","tur":"olcu","es":["advektif sıcaklık değişimi","local temperature tendency","sıcaklık eğilimi","termal değişim hızı"],"tanim":["Belirli bir noktadaki hava sıcaklığının birim zamandaki yerel artış veya azalış miktarı.","Sinoptik hesaplarda genellikle °C/s veya °C/6 sa birimleriyle ifade edilir.","Harita analizinde adveksiyon şiddetini ve yaklaşan hava kütlesinin getireceği termal değişimi ölçmede temel büyüklüktür."],"tanim_en":"The time rate of local temperature variation at a fixed point, expressed in units such as °C/s.","bag":{"kavram":["adveksiyon"],"soru":["S6"],"hesap":["adveksiyon"]}},{"id":"temperature-gradient","tr":"Sıcaklık gradyanı","en":"Temperature gradient","kisa":"∇T","tur":"olcu","es":["yatay sıcaklık gradyanı","thermal gradient","sıcaklık gradiyenti","ΔT/Δx","Yatay sıcaklık gradyanı","İzoterm gradyanı"],"tanim":["Sıcaklığın uzayda en hızlı arttığı yönü gösteren ve büyüklüğü birim mesafedeki sıcaklık farkına eşit olan vektörel büyüklük.","Birimi °C m⁻¹ veya K m⁻¹ olup izotermlere dik ve sıcak havaya doğru yönelir; izotermlerin sıklaştığı cephe kuşaklarında tipik değeri 2×10⁻⁵ °C m⁻¹ (4 °C / 200 km) mertebesinde bulunur.","Termal rüzgâr ilişkisi ve sıcaklık adveksiyonu hesaplarında yatay baroklinikliğin ana göstergesidir."],"tanim_en":"A vector quantity directed normal to isotherms toward higher temperature, with a magnitude equal to the rate of temperature change per unit distance.","bag":{"kavram":["adveksiyon","gradyan","termal-ruzgar"],"soru":["S6"],"hesap":["adveksiyon"]}},{"id":"cold-advection","tr":"Soğuk adveksiyon","en":"Cold advection","kisa":"CAA","tur":"surec","es":["soğuk hava adveksiyonu","cold air advection","C","CAA","Soğuk hava adveksiyonu","Soğuk taşınım"],"tanim":["Rüzgârın daha soğuk bir hava bölgesinden daha sıcak bir bölgeye doğru esmesiyle gerçekleşen yatay sıcaklık taşınımı süreci.","Harita analizinde C veya CAA simgesiyle gösterilir; yerel sıcaklık eğilimini düşürücü yönde etkiler.","Üst seviye trofunun arkasında ve soğuk cephe gerisinde kuvvetlenir; kalınlık değerlerini azaltarak siklonun derinleşmesine katkı sağlar."],"tanim_en":"The horizontal transport of colder air into a region by the wind field, resulting in local temperature fall.","bag":{"kavram":["adveksiyon"],"soru":["S6","S7","S8","S9"],"hesap":[]}},{"id":"warm-advection","tr":"Sıcak adveksiyon","en":"Warm advection","kisa":"WAA","tur":"surec","es":["sıcak hava adveksiyonu","warm air advection","W","WAA","Sıcak hava adveksiyonu","Sıcak taşınım"],"tanim":["Rüzgârın daha sıcak bir hava bölgesinden daha soğuk bir bölgeye doğru esmesiyle gerçekleşen yatay sıcaklık taşınımı süreci.","Harita analizinde W veya WAA kısaltmasıyla belirtilir; yerel sıcaklık eğilimini yükseltici yönde etkiler.","Sıcak cephe önünde ve üst seviye sırtının batısında belirginleşir; kalınlık değerlerini artırarak düşey yükselme hareketini destekler."],"tanim_en":"The horizontal transport of warmer air into a region by the wind field, resulting in local temperature rise.","bag":{"kavram":["adveksiyon"],"soru":["S6","S7","S8","S9"],"hesap":["adveksiyon"]}},{"id":"izoterm-araligi","tr":"İzoterm aralığı","en":"isotherm interval","kisa":"ΔT","tur":"yontem","es":["eşsıcaklık çizgisi aralığı","isotherm spacing","isotherm difference","izoterm farkı"],"tanim":["Sabit basınç ya da yer haritalarında ardışık iki izoterm arasındaki sıcaklık farkıdır.","Standart analiz haritalarında genellikle 4 °C aralıkla çizilir; birimi santigrat derecedir (°C).","Harita analizinde sıcaklık gradyanını ve termal adveksiyon şiddetini belirlemede kullanılır."],"tanim_en":"The fixed temperature difference between consecutive isotherms on a constant-pressure chart or surface map.","bag":{"kavram":["adveksiyon"],"soru":["S6","S8"],"hesap":["adveksiyon","izoterm-tasima"]}},{"id":"available-potential-energy","tr":"Kullanılabilir potansiyel enerji","en":"available potential energy","kisa":"APE","tur":"kavram","es":["APE","kullanılabilir potansiyel enerji miktarı"],"tanim":["Atmosferdeki toplam potansiyel enerjinin adyabatik süreçle kinetik enerjiye dönüşebilen kısmıdır.","Yatay sıcaklık gradyanlarının ve baroklinik yapının bulunduğu hava kütlelerinde depolanır; birimi J kg⁻¹ olarak verilir.","Orta enlem siklonlarının gelişiminde fırtınaların kinetik enerjisini besleyen ana kaynaktır."],"tanim_en":"The portion of total potential energy in the atmosphere that can be converted into kinetic energy through adiabatic redistribution.","bag":{"kavram":["barotropik"],"soru":[],"hesap":[]}},{"id":"closed-contour","tr":"Kapalı kontur","en":"Closed contour","kisa":"","tur":"kavram","es":["kapalı izohips","kapalı eş yükseklik çizgisi","closed height contour"],"tanim":["Sabit basınç haritasında jeopotansiyel yükseklik değerini gösteren ve bir merkez etrafında tamamen kapanan eğridir.","Üst seviye haritalarında genellikle 6 dam aralıkla çizilir; birimi dekametredir (dam).","Açık trof ve sırt yapılarından farklı olarak bağımsız, kapalı bir siklonik ya da antisiklonik dolaşımın varlığını gösterir."],"tanim_en":"A contour line of geopotential height that completely encircles a local high or low centre on a constant-pressure chart.","bag":{"kavram":["barotropik","jeopotansiyel","merkez"],"soru":[],"hesap":[]}},{"id":"mid-latitude-cyclone","tr":"Orta enlem siklonu","en":"Mid-latitude cyclone","kisa":"","tur":"kavram","es":["ekstratropikal siklon","extratropical cyclone","Ekstratropikal siklon","Orta enlem depresyonu","Mid-latitude depression","orta enlem depresyonu"],"tanim":["Tropikler dışındaki enlemlerde sıcak ve soğuk hava kütleleri arasındaki sınır boyunca gelişen alçak basınç sistemidir.","Yerde kapalı izobarlar, cephe hatları ve siklonik dolaşımla (Kuzey Yarımküre'de saat yönünün tersine) karakterize edilir.","Enerjisini baroklinik kararsızlıktan alır; orta enlemlerde geniş çaplı hava değişimlerinin ana nedenidir."],"tanim_en":"A synoptic-scale low-pressure system that forms along frontal zones in extratropical latitudes through baroclinic instability.","bag":{"kavram":["barotropik","merkez"],"soru":[],"hesap":[]}},{"id":"baroclinic-instability","tr":"Baroklinik kararsızlık","en":"Baroclinic instability","kisa":"","tur":"surec","es":["baroklinik instabilite","baroclinic wave","baroklinik dalga"],"tanim":["Güçlü yatay sıcaklık gradyanı ve düşey rüzgâr kesmesi barındıran akışlarda sinoptik ölçekli dalgaların büyümesini sağlayan dinamik dengesizliktir.","Kullanılabilir potansiyel enerjiyi gelişen siklon ve antisiklon dalgalarının kinetik enerjisine dönüştürür.","Harita analizinde üst seviye troflarının batıya eğimi ve konturları kesen izoterm desenleriyle tanınır."],"tanim_en":"A hydrodynamic instability associated with strong horizontal temperature gradients that drives the development of mid-latitude storms.","bag":{"kavram":["barotropik"],"soru":[],"hesap":[]}},{"id":"basra-trough","tr":"Basra trofu","en":"Basra Trough","kisa":"","tur":"kavram","es":["Basra alçağı","Basra termal oluğu","Basra low","Basra thermal low"],"tanim":["Yaz aylarında Basra Körfezi ve çevresindeki yoğun kara ısınmasıyla oluşan yarı-kalıcı termal alçak basınç oluğudur.","Sıcak çekirdekli sığ bir sistemdir; yer seviyesinde alçak basınç oluştururken üst seviyede (500 hPa) sırt yapısına dönüşür.","Türkiye güneydoğusuna sokularak yaz mevsiminde yüksek sıcaklık dalgaları ve kurak koşullar yaratır."],"tanim_en":"A semi-permanent warm-core thermal trough centered over the Persian Gulf region that dominates summer weather in the eastern Mediterranean.","bag":{"kavram":["cekirdek","trof-sirt"],"soru":["S5"],"hesap":[]}},{"id":"cold-core-high","tr":"Soğuk çekirdekli yüksek","en":"Cold-core high","kisa":"C","tur":"kavram","es":["cold-core anticyclone","soğuk yüksek","termik yüksek","soğuk çekirdekli antisiklon","soğuk antisiklon","Soğuk çekirdekli antisiklon"],"tanim":["Yeryüzünün aşırı ışınımsal soğumasıyla oluşan, merkezinde soğuk ve yoğun hava barındıran yüksek basınç sistemidir.","Merkezdeki ince kalınlık tabakası nedeniyle sığ bir yapıdır; yer seviyesinde antisiklon iken 500 hPa seviyesinde alçak basınca döner.","Kış mevsiminde karla kaplı geniş kıtasal alanlarda gelişir ve kararlı, ayazlı hava koşulları oluşturur."],"tanim_en":"A shallow anticyclone characterized by colder air at its centre that weakens with elevation and turns into a low in the upper troposphere.","bag":{"kavram":["cekirdek","merkez"],"soru":["S5"],"hesap":[]}},{"id":"cold-core-low","tr":"Soğuk çekirdekli alçak","en":"Cold-core low","kisa":"C","tur":"kavram","es":["cold-core cyclone","soğuk alçak","soğuk çekirdekli siklon","soğuk siklon"],"tanim":["Merkezindeki hava çevresine göre daha soğuk olan ve hidrostatik denge uyarınca yükseklikle güçlenen alçak basınç sistemidir.","Merkezde 1000–500 hPa tabaka kalınlığı düşük olup üst seviyelerde derin bir jeopotansiyel trof ya da kapalı alçak olarak belirginleşir.","İzlanda alçağı ve kesik alçaklar bu gruba girer; troposfer boyunca uzanan derin sistemlerdir."],"tanim_en":"A cyclonic system characterized by a core of colder air that intensifies with height into the middle and upper troposphere.","bag":{"kavram":["cekirdek","merkez","kalinlik"],"soru":["S5","S9"],"hesap":[]}},{"id":"shallow-system","tr":"Sığ sistem","en":"Shallow system","kisa":"","tur":"kavram","es":["sığ basınç sistemi","shallow pressure system","Shallow weather system","sığ hava sistemi","shallow weather system"],"tanim":["Düşey kalınlığı alt troposferle sınırlı olan ve üst seviyelere doğru zayıflayıp ters işaretli sisteme dönüşen basınç merkezidir.","Termal yapısı gereği sıcak çekirdekli alçaklar ve soğuk çekirdekli yüksekler 500 hPa seviyesinde yerini karşıt sisteme bırakır.","Sinoptik harita analizinde yer haritasındaki kapalı merkezin 500 hPa kartında kaybolmasıyla tanınır."],"tanim_en":"A pressure system confined to the lower troposphere that rapidly diminishes with altitude due to its thermal structure.","bag":{"kavram":["cekirdek","eksen-egim"],"soru":["S5"],"hesap":[]}},{"id":"subtropical-ridge","tr":"Subtropikal sırt","en":"Subtropical ridge","kisa":"","tur":"kavram","es":["subtropikal yüksek","subtropical anticyclone","Azor sırtı"],"tanim":["Subtropikal enlemlerde Hadley hücresinin alçalan kolu boyunca yer alan geniş ve sıcak çekirdekli yüksek basınç kuşağıdır.","Sıcak troposfer sütunu sayesinde yükseklikle güçlenen derin bir sistemdir; 500 hPa seviyesinde belirgin sırt ekseni oluşturur.","Orta enlem fırtına yollarını kuzeye öteler ve etkilediği bölgelerde geniş çaplı çökmeyle açık hava oluşturur."],"tanim_en":"A broad belt of high pressure in subtropical latitudes associated with the descending branch of the Hadley cell.","bag":{"kavram":["cekirdek"],"soru":[],"hesap":[]}},{"id":"thermal-low","tr":"Termik alçak","en":"Thermal low","kisa":"","tur":"kavram","es":["termal alçak","heat low","ısıl alçak","termal siklon"],"tanim":["Yeryüzünün güneş ışınımıyla aşırı ısınması sonucu yüzey katmanlarında oluşan sığ siklonik merkezdir.","Hipsometrik bağıntı uyarınca merkezdeki sıcak hava tabakayı kalınlaştırır; bu nedenle alçak basınç düşeyde birkaç kilometre içinde zayıflayarak yüksek basınca dönüşür.","Sinoptik yer haritasında belirgin kapalı izobarlarla görülen bu sistemler cephe içermez ve yaz aylarında karasal alanlar üzerinde sıkça gelişir."],"tanim_en":"A shallow depression resulting from high surface temperature due to intense solar heating of the Earth's surface.","bag":{"kavram":["cekirdek"],"soru":[],"hesap":[]}},{"id":"warm-core-high","tr":"Sıcak çekirdekli yüksek","en":"Warm-core high","kisa":"W","tur":"kavram","es":["warm-core anticyclone","sıcak yüksek","sıcak çekirdekli antisiklon","sıcak antisiklon"],"tanim":["Merkezindeki hava tabakasının ortalama sıcaklığı çevre havadan daha yüksek olan antisiklonik sistemdir.","Hipsometrik bağıntıya göre merkezdeki sıcak hava sütunu jeopotansiyel kalınlığı artırır; bu sayede yüksek basınç karakteri troposferin üst katmanlarına doğru daha da kuvvetlenir.","Sinoptik haritalarda subtropikal sırt ve dinamik antisiklon kuşağında geniş yer kaplayan derin bir sistemdir."],"tanim_en":"An anticyclone with a central warm temperature anomaly that strengthens with increasing altitude throughout the troposphere.","bag":{"kavram":["cekirdek","merkez"],"soru":["S5"],"hesap":[]}},{"id":"warm-core-low","tr":"Sıcak çekirdekli alçak","en":"Warm-core low","kisa":"W","tur":"kavram","es":["warm-core cyclone","sıcak çekirdekli siklon","sıcak siklon"],"tanim":["Merkezindeki hava sütununun ortalama sıcaklığı çevresine göre daha yüksek olan alçak basınç sistemidir.","Hipsometrik denklem uyarınca merkezdeki kalınlık kenarlardan fazla olduğu için yerdeki siklonik dolaşım yukarı çıktıkça hızla zayıflar.","Yüzey ısınmasıyla oluşan sığ termik alçaklar (yazın Basra alçağı) bu yapıyı sergiler ve 500 hPa seviyesinde çoğunlukla sırt ya da yüksek basınca döner; tropikal siklonlar da sıcak çekirdeklidir ama derindir, siklonik dolaşımları ancak üst troposferde antisiklonik dışa akışa döner."],"tanim_en":"A cyclone characterized by a warm central column that rapidly weakens with height to transition into an anticyclonic ridge aloft.","bag":{"kavram":["cekirdek","merkez"],"soru":["S5"],"hesap":[]}},{"id":"analysis-chart","tr":"Analiz haritası","en":"analysis chart","kisa":"","tur":"cihaz","es":["analiz kartı","weather analysis chart","sinoptik analiz haritası","hava analiz haritası"],"tanim":["Belirli bir sinoptik gözlem saatinde yeryüzünden veya üst atmosferden toplanan meteorolojik verilerin işlenip analiz edildiği coğrafi haritadır.","Yer haritasında 1000 hPa tabanlı 4 hPa aralıklı izobarlar ve cepheler, standart izobarik yüzeylerde ise kontur, izoterm ve izotaklar çizilir.","Mevcut atmosfer durumunu tanılamak, hava kütlelerini izlemek ve sayısal tahmin modellerine başlangıç koşulu sağlamak amacıyla kullanılır."],"tanim_en":"A geographical chart displaying plotted weather observations alongside analyzed patterns of isobars, contours, isotherms, and fronts for a given synoptic hour.","bag":{"kavram":["cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"equatorial-air-mass","tr":"Ekvatoral hava kütlesi","en":"Equatorial air mass","kisa":"E","tur":"kavram","es":["ekvator havası","ekvator hava kütlesi","equatorial air"],"tanim":["Ekvator kuşağında, tropikal okyanuslar ile nemli karalar üzerinde gelişen, yüksek sıcaklık ve yüksek nem içeriğine sahip hava kütlesi.","Meteoroloji haritalarında ve hava kütlesi sınıflamasında E simgesiyle gösterilir; dikey kararsızlığı yüksektir ve güçlü konveksiyona yatkındır.","Sinoptik analizde intertropikal konverjans zonu boyunca hava hareketlerini belirler ve ekvatoral yağış rejimini oluşturur."],"tanim_en":"A warm, very humid air mass that forms over the equatorial belt and is prone to deep convection.","bag":{"kavram":["cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"front","tr":"Cephe","en":"Front","kisa":"","tur":"kavram","es":["cephe yüzeyi","cephe hattı","meteorological front","hava cephesi","frontal surface"],"tanim":["Farklı yoğunluk ve sıcaklıktaki iki hava kütlesini birbirinden ayıran dar geçiş kuşağı veya bu kuşağın yeryüzüyle yaptığı arakesit çizgisidir.","Yer haritasında belirgin yatay sıcaklık gradyanı, izobarlarda V biçimli kırılma (kink), basınç oluğu ve karakteristik bulut ile yağış kuşaklarıyla tanınır.","Orta enlem siklonlarının gelişiminde temel baroklinik yapıyı oluşturur ve hava koşullarında ani değişimlere yol açar."],"tanim_en":"The interface or transition zone between two air-mass systems of different density, or the line where this boundary meets the Earth's surface or another surface.","bag":{"kavram":["cephe-olcutleri","barotropik"],"soru":["S9"],"hesap":[]}},{"id":"frontal-zone","tr":"Cephe zonu (kuşağı)","en":"Frontal zone","kisa":"","tur":"kavram","es":["cephe kuşağı","frontal bölge","Cephe kuşağı","Cephesel zon","Cephe zonu","cephesel bölge"],"tanim":["İki farklı hava kütlesi arasında yer alan, meteorolojik özelliklerin bir kütleden diğerine kademeli olarak değiştiği atmosferik geçiş tabakasıdır.","Yatay sıcaklık ve yoğunluk gradyanının en yüksek değerlere ulaştığı, izotermlerin sıklaştığı dar bir baroklinik banttır.","Üst seviye polar cephe jetinin hemen altında yer alarak siklonların derinleşmesi için gerekli baroklinik enerjiyi sağlar."],"tanim_en":"A sloping transition layer between two air-mass systems in which temperature, density and other properties change sharply.","bag":{"kavram":["cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"wind-shift","tr":"Rüzgâr dönmesi (kink)","en":"wind shift","kisa":"","tur":"kavram","es":["rüzgâr kırılması","wind kink","rüzgâr yönü sıçraması","rüzgâr yönü değişimi"],"tanim":["Rüzgâr yönünde kısa zaman veya mesafe aralığında meydana gelen ani ve belirgin yön değişimidir.","Yer haritasında izobarların oluşturduğu oluk hattında veya cephe boyunca izobarlarda V biçimli kırılma (kink) olarak yansır.","Cephe çizgisinin geçtiği konumu belirlemede en güvenilir analiz ölçütüdür; soğuk cephe geçişinde rüzgâr genellikle saat yönünde döner (veering)."],"tanim_en":"A sudden and marked change in wind direction commonly observed during the passage of a front or a trough line.","bag":{"kavram":["cephe-olcutleri","ruzgar-yonu","trof-sirt"],"soru":[],"hesap":[]}},{"id":"extrapolation-method","tr":"Katlama yöntemi","en":"extrapolation method","kisa":"","tur":"yontem","es":["öteleme yöntemi","linear extrapolation","doğrusal öteleme","katlama kuralı"],"tanim":["Sinoptik sistemlerin ve cephelerin geçmiş haritalardaki hız ile yönünü koruyacağı varsayımına dayanan basit doğrusal öteleme tekniğidir.","Ardışık iki analiz haritası (örneğin 00 ve 06 UTC) arasındaki cephe konumlarından hız hesaplanır ve bu yol ileriye doğru (12, 18, 24 UTC) ötelenir.","Kısa vadeli hava tahmininde cephenin hedef istasyona tahmini varış anını belirlemek için pratik bir kestirim sağlar."],"tanim_en":"A forecasting technique projecting the future position and arrival time of a frontal boundary by assuming constant velocity derived from consecutive synoptic charts.","bag":{"kavram":["cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"warm-sector","tr":"Sıcak sektör","en":"warm sector","kisa":"","tur":"kavram","es":["sıcak hava dilimi","sıcak dilim","Sıcak kesim","Sıcak dilim","warm air sector"],"tanim":["Gelişen bir orta enlem siklonunda öndeki sıcak cephe ile arkadaki soğuk cephe arasında kalan sıcak hava kütlesi alanıdır.","Yer haritasında genellikle güneybatılı ılık rüzgârlar, Stratus veya Stratocumulus bulutları, pus ve hafif çisenti ile tanımlanır.","Oklüzyon sürecinde daha hızlı ilerleyen soğuk cephe tarafından yerden yukarı doğru kaldırılarak zeminle teması son bulur."],"tanim_en":"The warm air region within a cyclone enclosed between the advancing warm front ahead and the following cold front behind.","bag":{"kavram":["cephe-sicak","cephe-soguk","okluzyon"],"soru":[],"hesap":[]}},{"id":"backing","tr":"Sola dönme (saat yönünün tersine dönme)","en":"backing","kisa":"backing","tur":"surec","es":["saat yönü tersine rüzgâr dönmesi","backing wind","sola dönme","saat yönünün tersine rüzgâr dönüşü","Backing (sola dönme)","Saatin tersi yönde dönme"],"tanim":["Rüzgâr yönünün zamanla veya troposferde yükseklikle saat yönünün tersine dönmesidir.","Termal rüzgâr bağıntısına göre, Kuzey Yarımküre'de rüzgârın yükseklikle sola dönmesi ilgili atmosfer tabakasında soğuk hava adveksiyonu bulunduğunu gösterir.","Sinoptik harita analizinde ve radyosonde profilinde soğuk cephe gerisindeki soğuk hava taşınımını belirlemede temel bir tanı aracıdır."],"tanim_en":"A counter-clockwise change of wind direction with time or height, which indicates cold advection in the Northern Hemisphere.","bag":{"kavram":["cephe-sicak","ruzgar-yonu","termal-ruzgar"],"soru":[],"hesap":[]}},{"id":"air-mass","tr":"Hava kütlesi","en":"air mass","kisa":"","tur":"kavram","es":["hava kütleleri","hava kitlesi","Hava kitlesi","airmass"],"tanim":["Yatay yönde sıcaklık ve nem gibi fiziksel özellikleri geniş alanlar boyunca küçük ve sürekli değişim gösteren büyük atmosfer parçası.","Milyonlarca kilometrekarelik alana ve birkaç kilometrelik düşey derinliğe yayılabilir.","Farklı hava kütlelerinin karşılaşma sınırları yer haritalarında cepheleri oluşturur."],"tanim_en":"An extensive body of air whose temperature and humidity show small horizontal variation over a wide region.","bag":{"kavram":["cephe-soguk","cephe-sicak","cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"cold-wedge","tr":"Soğuk kama","en":"cold wedge","kisa":"","tur":"kavram","es":["soğuk hava kaması","wedge of cold air"],"tanim":["Cephe sistemlerinde daha yoğun ve ağır olan soğuk havanın, sıcak havanın altına kama biçiminde sokulan alt troposfer dilimi.","Soğuk cephede öne doğru ilerleyerek sıcak havayı dik bir eğimle yukarı kaldırır; sıcak cephede geriye çekilirken sıcak hava kamanın üstüne tırmanır.","Düşey kesit analizinde yatay ile yaptığı küçük eğim açısı cephenin yapısını belirler."],"tanim_en":"A wedge-shaped layer of cold and dense air undercutting warm air along a frontal zone.","bag":{"kavram":["cephe-soguk"],"soru":[],"hesap":[]}},{"id":"squall-line","tr":"Sağanak hattı","en":"squall line","kisa":"","tur":"kavram","es":["oraj hattı","instability line"],"tanim":["Genellikle hızlı ilerleyen soğuk cephelerin önünde uzanan, konvektif fırtınaların oluşturduğu dar çizgisel hat.","Şiddetli rüzgâr hamleleri, yoğun sağanak, dolu ve gök gürültülü fırtınalarla birlikte ani hava basıncı yükselişine yol açar.","Radar görüntülerinde yay ya da çizgi biçiminde eko verir; sinoptik haritalarda cepheden ayrı bir kararsızlık hattı olarak izlenir."],"tanim_en":"A narrow band of severe thunderstorms developing ahead of a cold front and producing strong gusty wind.","bag":{"kavram":["cephe-soguk"],"soru":[],"hesap":[]}},{"id":"code-frontal-symbols","tr":"Cephe sembolleri","en":"frontal symbols","kisa":"","tur":"kod","es":["cephe işaretleri","frontal signs"],"tanim":["Sinoptik yer haritalarında cephe türünü ve hareket yönünü göstermek için cephe çizgisi üzerine yerleştirilen standart işaretler.","Soğuk cephe için üçgenler, sıcak cephe için yarım daireler, oklüzyon cephesi için ise ardışık üçgen ve yarım daireler kullanılır.","Sembollerin sivri uçları ya da kavisleri daima cephenin ilerlediği yönü gösterir."],"tanim_en":"Standard graphical symbols placed on frontal lines on weather charts to indicate front type and movement direction.","bag":{"kavram":["cephe-soguk","cephe-sicak","okluzyon"],"soru":[],"hesap":[]}},{"id":"frontal-slope","tr":"Cephe eğimi","en":"Frontal slope","kisa":"α","tur":"olcu","es":["cephe yüzeyi eğimi","Cephe yüzeyi eğimi","frontal surface slope","cephe yüzeyinin eğim açısı alpha","frontal slope angle alpha"],"tanim":["İki farklı hava kütlesini ayıran cephe yüzeyinin yatay düzlemle yaptığı eğim açısı.","Birimsiz bir oran olan tan α ile ifade edilir; soğuk cephede yaklaşık 1/50 ile 1/100 arasında iken sıcak cephede yaklaşık 1/150 ile 1/300 arasındadır.","Eğim dikleştikçe düşey hava hareketi kuvvetlenir; yatık eğimlerde ise geniş alana yayılan stratiform bulutlar oluşur."],"tanim_en":"The inclination of a frontal surface relative to the horizontal, expressed as the tangent of the slope angle.","bag":{"kavram":["cephe-soguk","cephe-sicak","cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"veering","tr":"Sağa dönme (saat yönünde dönme)","en":"veering","kisa":"veering","tur":"surec","es":["saat yönünde rüzgâr dönmesi","veering wind","sağa dönme","saat yönünde rüzgâr dönüşü","Veering (sağa dönme)","Saat yönünde dönme"],"tanim":["Rüzgâr yönünün zamanla ya da yükseklikle saat yönünde değişmesi.","Kuzey Yarımküre'de yükseklikle rüzgârın saat yönünde dönmesi termal rüzgâr bağıntısına göre tabakada sıcak adveksiyon olduğunu gösterir.","Yer seviyesinde soğuk cephe geçişi sırasında rüzgârın güneybatıdan kuzeybatıya dönmesi tipik bir örnektir."],"tanim_en":"A clockwise change in wind direction with time or height, indicating warm advection in the Northern Hemisphere.","bag":{"kavram":["cephe-soguk","ruzgar-yonu","termal-ruzgar"],"soru":[],"hesap":[]}},{"id":"synoptic-scale","tr":"Sinoptik ölçek","en":"Synoptic scale","kisa":"","tur":"kavram","es":["büyük ölçek","cyclonic scale","sinoptik ölçekli süreçler"],"tanim":["Yatay uzunluk ölçeği yaklaşık 1000 km, zaman ölçeği ise birkaç gün olan atmosferik hareket boyutu.","Orta enlem (ekstratropikal) siklonları, antisiklonlar, kısa dalga trof ve sırtlar bu ölçekte incelenir.","Rossby sayısının birden çok küçük olması nedeniyle serbest atmosferde Coriolis kuvveti ile basınç gradyanı dengelenir."],"tanim_en":"A characteristic horizontal scale of atmospheric motion with dimensions of roughly one thousand kilometres and lifetimes of several days.","bag":{"kavram":["coriolis","jeostrofik","merkez"],"soru":["S6"],"hesap":[]}},{"id":"coriolis-parameter","tr":"Coriolis parametresi","en":"Coriolis parameter","kisa":"f","tur":"olcu","es":["f parametresi","Coriolis faktörü","f Coriolis sembolü","Coriolis katsayısı"],"tanim":["Dünya'nın açısal hızının yerel düşey bileşeninin iki katı olan büyüklük (gezegensel vortisite); f = 2Ω sin φ bağıntısıyla tanımlanır.","Birimi s⁻¹ olup ekvatorda 0 iken kutuplarda en büyüktür; 45° enlemde yaklaşık 1,03×10⁻⁴ s⁻¹, İstanbul'da yaklaşık 9,6×10⁻⁵ s⁻¹ değerini alır.","Jeostrofik ve termal rüzgâr hesaplarında dönme etkisini belirler; f küçüldükçe aynı gradyan daha hızlı rüzgâr verir."],"tanim_en":"The parameter defined as twice the vertical component of the Earth's angular velocity (the planetary vorticity), given by f = 2Ω sin φ.","bag":{"kavram":["coriolis","termal-ruzgar","jet-streak"],"soru":[],"hesap":[]}},{"id":"rossby-number","tr":"Rossby sayısı","en":"Rossby number","kisa":"Ro","tur":"olcu","es":["Ro sayısı","Rossby parametresi"],"tanim":["Akışkan hareketinde eylemsizlik kuvvetlerinin Coriolis kuvvetine oranını temsil eden boyutsuz sayı.","Sinoptik ölçekli sistemlerde tipik değeri yaklaşık 0,1 olup 1'den çok küçüktür (Ro ≪ 1).","Değerinin 1'den çok küçük olması ivme terimlerinin ihmal edilebileceğini ve jeostrofik dengenin geçerli olduğunu gösterir."],"tanim_en":"A non-dimensional parameter defined as the ratio of inertial force to Coriolis force in geophysical fluid flow.","bag":{"kavram":["coriolis","jeostrofik"],"soru":[],"hesap":[]}},{"id":"sym-earth-angular-velocity-omega","tr":"Dünya'nın açısal hızı","en":"Earth angular velocity","kisa":"Ω","tur":"olcu","es":["açısal hız Omega"],"tanim":["Dünya'nın kendi dönme ekseni etrafındaki açısal hızı; bir yıldız gününde 2π radyanlık dönüşle tanımlanır.","Değeri yaklaşık 7,292×10⁻⁵ s⁻¹ olan sabit bir büyüklüktür.","Dinamik meteorolojide Coriolis ivmesini ve f parametresini hesaplamakta kullanılan temel gezegensel sabittir."],"tanim_en":"The rotational angular velocity of planet Earth around its polar axis, with a constant magnitude of 7.292×10⁻⁵ s⁻¹.","bag":{"kavram":["coriolis"],"soru":[],"hesap":[]}},{"id":"sym-latitude-phi","tr":"Coğrafi enlem","en":"Latitude","kisa":"φ","tur":"olcu","es":["enlem açısı phi","enlem açısı","phi","geographic latitude"],"tanim":["Yeryüzündeki bir noktanın ekvator düzlemine olan açısal uzaklığı.","Derece (°) cinsinden ölçülür; ekvatorda 0°, kutuplarda 90° değerini alır.","Sinoptik analizde Coriolis parametresini ve güneşlenme açısını doğrudan belirler."],"tanim_en":"Angular distance of a point on Earth north or south of the equator.","bag":{"kavram":["coriolis"],"soru":[],"hesap":[]}},{"id":"developing-low","tr":"Gelişen alçak","en":"Developing low","kisa":"","tur":"kavram","es":["gelişen siklon","developing cyclone","gelişen baroklinik siklon"],"tanim":["Merkez basıncı zamanla düşen, yatay sıcaklık gradyanı ve baroklinik kararsızlık ile kuvvetlenen alçak basınç sistemi.","Düşey ekseni yükseklikle batıya doğru eğimlidir; batısında soğuk, doğusunda sıcak adveksiyon görülür.","Yer haritasında belirgin cephe sistemleri taşır ve derinleşerek fırtına evresine ilerler."],"tanim_en":"A low pressure system that intensifies through baroclinic instability with its vertical axis tilting westward with height.","bag":{"kavram":["eksen-egim","merkez","barotropik"],"soru":["S9"],"hesap":[]}},{"id":"mature-system","tr":"Olgun sistem","en":"Mature system","kisa":"","tur":"kavram","es":["olgun evre","mature cyclone stage","olgun siklon","mature cyclone","Olgun alçak","Mature low"],"tanim":["Siklon yaşam döngüsünde en düşük merkez basıncına ulaştığı ve oklüzyon sürecinin tamamlandığı evredeki fırtına sistemi.","Yatay sıcaklık zıtlığı zayıflar, sistemin düşey ekseni dikleşir ve yer merkezi üst seviye trofu ile neredeyse aynı konuma gelir.","İzotermler konturlara paralelleşir, sıcaklık adveksiyonu durur ve sistem yavaşlayarak dolma sürecine hazırlanır."],"tanim_en":"A cyclone at its maximum intensity where occlusion has occurred and the vertical axis becomes nearly upright.","bag":{"kavram":["eksen-egim","merkez","barotropik"],"soru":["S10"],"hesap":[]}},{"id":"vertically-stacked-system","tr":"Düşey eksenli sistem","en":"Vertically stacked system","kisa":"","tur":"kavram","es":["dik eksenli sistem","vertically stacked low","düşey eksen","üst üste merkezler","Düşey eksenli sistem (üst üste merkezler)","merkezleri üst üste alçak"],"tanim":["Yer seviyesindeki basınç merkezi ile üst seviyedeki jeopotansiyel alçak merkezinin düşey doğrultuda tam üst üste geldiği atmosferik sistem.","İzotermler konturlara paraleldir; sıcaklık adveksiyonu sıfırdır ve sistem eşdeğer barotropik yapı sergiler.","Gelişimi tamamlanmış, yavaş hareket eden ya da yerinde sayan kesik alçak gibi sistemlerde görülür."],"tanim_en":"A low-pressure system in which the surface centre lies directly beneath the upper-level closed circulation, so that its axis is vertical.","bag":{"kavram":["eksen-egim","barotropik"],"soru":["S9","S10"],"hesap":[]}},{"id":"density","tr":"Yoğunluk","en":"Density","kisa":"ρ","tur":"olcu","es":["hava yoğunluğu","air density","hava yoğunluğu sembolü","rho","kütle yoğunluğu"],"tanim":["Birim hacimdeki havanın kütlesi.","Birim olarak kg m⁻³ kullanılır; standart atmosferde yer seviyesinde yaklaşık 1,2 kg m⁻³, 500 hPa seviyesinde ise yaklaşık 0,7 kg m⁻³ değerini alır.","Basınç gradyan kuvvetini ivmeye çevirir; aynı basınç gradyanı yüksekteki daha seyrek havayı daha çok hızlandırır."],"tanim_en":"Mass of air per unit volume.","bag":{"kavram":["gradyan","jeopotansiyel"],"soru":[],"hesap":["izobar-yeri"]}},{"id":"sym-normal-isobar-spacing-delta-n","tr":"İzobarlar arası dik uzaklık","en":"Normal distance between isobars","kisa":"Δn","tur":"olcu","es":["izobar dik aralığı","normal spacing Δn","normal spacing","izobar dik mesafesi"],"tanim":["Sinoptik haritada komşu iki izobar arasında dik doğrultuda ölçülen en kısa gerçek uzaklık.","Metre (m) cinsinden kullanılır; sinoptik haritalarda tipik değerleri 100 ile 500 km arasında değişir.","Basınç gradyan kuvveti ve jeostrofik rüzgâr hızı ile ters orantılıdır; izobarlar sıklaştıkça bu uzaklık daralır ve rüzgâr kuvvetlenir."],"tanim_en":"The shortest perpendicular distance measured between two consecutive isobars on a weather chart.","bag":{"kavram":["gradyan","jeostrofik"],"soru":[],"hesap":["izobar-yeri"]}},{"id":"anticyclonic-curvature","tr":"Antisiklonik eğrilik","en":"Anticyclonic curvature","kisa":"R < 0","tur":"kavram","es":["yüksek basınç eğriliği","anticyclonic trajectory curvature","antisiklonik akış eğriliği"],"tanim":["Kuzey yarıkürede saat yönünde, yüksek basınç merkezi ya da sırt ekseni çevresinde bükülen akış yörüngesi eğriliği.","Yörünge eğrilik yarıçapı kural olarak negatif (R < 0) kabul edilir; tipik yarıçap mutlak değerce 500 ile 3000 km arasında yer alır.","Merkezkaç kuvveti basınç gradyan kuvvetiyle aynı yönde etkiyerek rüzgârın üst-jeostrofik hız kazanmasına yol açar."],"tanim_en":"Curvature of an air trajectory that turns clockwise around high pressure in the Northern Hemisphere.","bag":{"kavram":["gradyan-ruzgar","trof-onu"],"soru":[],"hesap":[]}},{"id":"cyclonic-curvature","tr":"Siklonik eğrilik","en":"Cyclonic curvature","kisa":"R > 0","tur":"kavram","es":["alçak basınç eğriliği","cyclonic trajectory curvature","siklonik akış eğriliği"],"tanim":["Kuzey yarıkürede saatin tersi yönünde, alçak basınç merkezi ya da trof ekseni çevresinde dönen hava akışının yörünge eğriliği.","Yörünge eğrilik yarıçapı pozitif (R > 0) olarak tanımlanır; tipik değerleri 500 ile 3000 km arasında değişir.","Dışa doğru etkiyen merkezkaç kuvveti basınç gradyan kuvvetini zayıflatarak rüzgârın alt-jeostrofik hızda kalmasına neden olur."],"tanim_en":"Curvature of an air trajectory that turns counterclockwise around low pressure in the Northern Hemisphere.","bag":{"kavram":["gradyan-ruzgar","trof-onu"],"soru":[],"hesap":[]}},{"id":"subgeostrophic-wind","tr":"Alt-jeostrofik rüzgâr","en":"Subgeostrophic wind","kisa":"V < V_g","tur":"olcu","es":["sub-geostrophic wind","jeostrofik altı rüzgâr"],"tanim":["Gerçek ya da gradyan rüzgâr hızının, aynı basınç gradyanındaki teorik jeostrofik rüzgâr hızından daha düşük olması durumu.","Birim olarak m/s ya da knot kullanılır; siklonik eğriliğe sahip trof eksenlerinde ve sürtünmeli yüzey sınır tabakasında görülür.","Siklonik akışta dışa savuran merkezkaç kuvveti basınç gradyanını dengelemek için gereken Coriolis kuvvetini azaltarak rüzgârı yavaşlatır."],"tanim_en":"A wind with a speed less than the corresponding geostrophic wind speed for the same pressure gradient.","bag":{"kavram":["gradyan-ruzgar"],"soru":[],"hesap":[]}},{"id":"unit-okta","tr":"Okta","en":"Okta","kisa":"okta","tur":"birim","es":["sekizde bir","eighth","oktas","sekizde bir bulutluluk","sekizde bir kapalılık","eighth of sky"],"tanim":["Gökyüzünün bulutlarla kaplı alan oranını sekizde bir kesirlerle belirten meteorolojik ölçü birimi.","WMO kod tablosu 2700 uyarınca 0 (tamamen açık) ile 8 (tamamen kapalı) arasında değer alır; 9 gökyüzünün sis gibi nedenlerle görülemediğini belirtir.","SYNOP iletisinde Nddff ve 8NhCLCMCH gruplarında kodlanır; istasyon modelinde merkezdeki dairenin dilimleri taranarak çizilir."],"tanim_en":"A unit of measurement equal to one eighth of the celestial dome used to describe the amount of cloud cover.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"sounding","tr":"Atmosferik sondaj","en":"Sounding","kisa":"sondaj","tur":"cihaz","es":["Radyosonde gözlemi","Düşey sondaj","radyosonde","aerolojik sondaj","upper-air sounding","atmosfer sondajı"],"tanim":["Atmosferin düşey sütunu boyunca sıcaklık, basınç, nem ve rüzgâr gibi değişkenlerin aletli olarak ölçülmesi işlemi.","Radyosonde balonu veya uzaktan algılama sistemleriyle elde edilir; veriler Skew-T log-P termodinamik diyagramına işlenir.","Sinoptik analizde üst seviye kartlarındaki (850, 700, 500 hPa) kontur, sıcaklık ve rüzgâr değerlerini kontrol edip doğrulamada kullanılır."],"tanim_en":"An upper-air measurement of meteorological elements such as temperature, pressure, humidity, and wind along a vertical profile in the atmosphere.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"altocumulus","tr":"Altocumulus","en":"altocumulus","kisa":"Ac","tur":"kavram","es":["altokümülüs","altokümülüs bulutu","altocumulus cloud","Altocumulus translucidus","Ac lenticularis","Altokümülüs"],"tanim":["Orta seviyede yer alan, beyaz veya gri renkte, laminalar veya yuvarlak kütleler içeren tabaka ya da yama biçimli bulut cinsi.","Öğelerinin görünür genişliği bir ile beş derece arasındadır; gölgeli yapısıyla Cirrocumulus bulutundan ayrılır.","SYNOP raporlarında orta bulut türü tablosunda (CM, WMO tablo 0515) CM = 3–9 kodlarıyla, istasyon modelinde orta kat bulut simgesiyle gösterilir."],"tanim_en":"A middle-level cloud genus appearing as white or grey patches or sheets composed of laminae, rolls, or rounded elements with an apparent width between one and five degrees.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"altostratus","tr":"Altostratus","en":"altostratus","kisa":"As","tur":"kavram","es":["altostratus bulutu","altostratus cloud","Altostratus translucidus","Altostratus opacus","orta seviye tabaka bulutu","middle cloud As"],"tanim":["Orta seviyede gökyüzünü kısmen veya tamamen kaplayan, grimsi veya mavimsi renkte, çizgili, lifli ya da tekdüze görünümlü tabaka bulutu.","Güneş'i buzlu cam arkasından görünür gibi donuk gösterir ve hale (halo) olayı oluşturmaz.","Sıcak cephe yaklaşırken Ci ve Cs bulutlarının ardından kalınlaşarak gelir; sürekli yağmur öncesi Ns bulutuna geçişi gösterir."],"tanim_en":"A greyish or bluish middle-level sheet cloud of fibrous or uniform appearance through which the Sun appears dimly without halo phenomena.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"cirrocumulus","tr":"Cirrocumulus","en":"cirrocumulus","kisa":"Cc","tur":"kavram","es":["sirrokümülüs","sirrokümülüs bulutu","cirrocumulus cloud","Cc","Sirrokümülüs","sirrokumulus"],"tanim":["Yüksek seviyede yer alan, gölgesi bulunmayan, ince ve beyaz tabaka ya da yama biçimli bulut cinsi.","Tanecik veya dalgacık biçimindeki çok küçük öğelerden oluşur; bu öğelerin görünür açısal genişliği bir dereceden küçüktür.","SYNOP raporlarında CH kod tablosunda CH = 9 koduyla tek başına ya da baskın yüksek bulut olarak kodlanır."],"tanim_en":"A thin white high cloud layer without shading, composed of very small granular or rippled elements with an apparent width under one degree.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"cirrostratus","tr":"Cirrostratus","en":"cirrostratus","kisa":"Cs","tur":"kavram","es":["sirrostratus","sirrostratus bulutu","cirrostratus cloud","Cs","sirrostratus tülü","Sirrostratus"],"tanim":["Yüksek seviyede bulunan, gökyüzünü kısmen ya da tamamen kaplayan, lifli veya düzgün görünümlü, şeffaf ve beyazımsı bulut tülü.","Güneş ve Ay çevresinde belirgin optik hale (halo) olayları üretir; yerdeki cisimlerin gölgelerini ortadan kaldırmaz.","Sıcak cephenin yüzlerce kilometre önünde Ci bulutlarının ardından gelerek cephesel yaklaşımın önemli bir göstergesi olur."],"tanim_en":"A transparent whitish high cloud veil of fibrous or smooth appearance creating optical halo phenomena around the Sun or Moon.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"cirrus","tr":"Cirrus","en":"cirrus","kisa":"Ci","tur":"kavram","es":["sirrüs","lif bulut","Ci","yüksek bulut","sirrus","cirrus cloud"],"tanim":["Yüksek seviyede yer alan, tamamen buz kristallerinden oluşan, beyaz, ince ve narin lifler veya ipeksi demetler biçimindeki bulut cinsi.","Tipik olarak 6 km yüksekliğin üzerinde bulunur; gölge oluşturmaz ve ipliksi kuyruklar içerebilir.","Sıcak cephenin yüzlerce kilometre önünde ilk beliren buluttur; jet akımı ekseni ve üst seviye nem alanlarının izlenmesinde kullanılır."],"tanim_en":"A high-level cloud genus composed of detached white ice-crystal filaments with a delicate, fibrous, or silky appearance.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"cumulonimbus","tr":"Cumulonimbus","en":"cumulonimbus","kisa":"Cb","tur":"kavram","es":["kümülonimbüs","fırtına bulutu","kümülonimbüs bulutu","oraj bulutu","Cumulonimbus capillatus","Kümülonimbüs"],"tanim":["Düşey gelişimi çok kuvvetli, dağ veya kule şeklinde yükselen, üst kısmı lifli veya düzleşip örs biçimini alan fırtına bulutu cinsi.","Tabanı genellikle alçak seviyede başlar ve tavanı tropopoza kadar uzanabilir; şimşek, gök gürültüsü, sağanak ve dolu üretir.","Sinoptik analizde soğuk cephe boyunca ve sağanak hattında şiddetli konvektif hadiselerin başlıca kaynağıdır; SYNOP'ta CL = 3 veya 9 ile rapor edilir."],"tanim_en":"A heavy and dense cloud of considerable vertical development in the form of a mountain or huge tower, often with an anvil-shaped fibrous upper part.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"cumulus","tr":"Cumulus","en":"cumulus","kisa":"Cu","tur":"kavram","es":["kümülüs","yığın bulut","kümülüs bulutu","küme bulut","Cumulus humilis","Cumulus congestus"],"tanim":["Belirgin dikey gelişme gösteren, keskin sınırlı, ayrık, kubbe veya karnabahar biçimli üst kısımlara sahip yığın bulut cinsi.","Güneş alan kısımları parlak beyaz, tabanı ise hemen hemen yatay ve nispeten koyu renktedir.","Gündüz termik konveksiyonuyla oluşur; soğuk cephe geçişi ardından serin havada parçalı Cu olarak görülür ve SYNOP'ta CL grubunda kodlanır."],"tanim_en":"A detached cloud with sharp outlines that develops vertically in the form of rising domes or towers with a nearly horizontal dark base.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"nimbostratus","tr":"Nimbostratus","en":"nimbostratus","kisa":"Ns","tur":"kavram","es":["nimbostratus bulutu","nimbostratus cloud","yağmur bulutu","Ns","middle cloud Ns"],"tanim":["Yere ulaşan sürekli yağmur veya kar yağışıyla görünümü belirsizleşen, koyu gri renkli ve çok kalın tabaka bulutu.","Güneş ışığını tamamen engelleyecek kadar kalındır; tabanının altında sık sık parçalı ve dağınık alçak bulutlar yer alır.","Sıcak cephenin hemen önünde yer alarak geniş bir alana yayılan sürekli cephesel yağışın (ww = 61, 63, 65) kaynağını oluşturur."],"tanim_en":"A dark grey cloud layer rendered diffuse by continuously falling rain or snow thick enough to blot out the Sun.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"stratocumulus","tr":"Stratocumulus","en":"stratocumulus","kisa":"Sc","tur":"kavram","es":["stratokümülüs","stratokümülüs bulutu","stratocumulus cloud","Stratocumulus cumulogenitus","Sc","Stratokümülüs"],"tanim":["Alçak seviyede bulunan, gri ya da beyazımsı tabaka, bant veya yuvar dizilerinden oluşan, hemen hemen her zaman koyu bölümleri olan bulut cinsi.","Öğelerinin görünür açısal genişliği beş dereceden büyüktür; zayıf çisenti veya kar serpintisi dışında genellikle yağış bırakmaz.","Sıcak sektörde ve soğuk cephe sonrasında geniş alanları kaplar; SYNOP CL tablosunda CL = 4 ve 5 (Cu ile farklı seviyelerde birlikteyse 8) olarak kodlanır."],"tanim_en":"A low-level cloud sheet or layer composed of grey or whitish rolls, rounded elements, or tessellated patches with an apparent width exceeding five degrees.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"stratus","tr":"Stratus","en":"stratus","kisa":"St","tur":"kavram","es":["katman bulut","stratus bulutu","Stratus nebulosus","Stratus fractus","alçak tabaka bulutu","low cloud St"],"tanim":["Tabanı tekdüze ve gri olan, alçak seviyede yer alan tabaka bulutu cinsidir.","Çisenti, kar grenleri ya da buz prizmaları üretebilir; Güneş görüldüğünde dış hatları açıkça seçilir.","SYNOP raporlarında CL kod tablosu içinde CL = 6 ya da CL = 7 olarak bildirilir; sıcak cephe yaklaşırken ve sıcak sektör içinde gözlenir."],"tanim_en":"Generally grey cloud layer with a fairly uniform base, which may give drizzle, ice prisms or snow grains.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"code-a-tendency-characteristic","tr":"Basınç eğiliminin karakteristiği","en":"characteristic of pressure tendency","kisa":"a","tur":"kod","es":["pressure tendency trace","barometre eğrisi","basınç eğilim karakteristiği","tendency characteristic","a","barometrik eğilim eğrisi"],"tanim":["SYNOP iletisinde 5appp grubunda yer alan ve son 3 saatteki basınç değişiminin eğri biçimini belirten tek haneli kod rakamıdır.","WMO KOD 0200 tablosuna göre 0 ile 8 arasında değer alır; 0–3 basıncın 3 saat öncesine göre yüksek veya eşit, 4 sabit, 5–8 ise düşük veya eşit olduğunu gösterir.","İstasyon modelinde ppp değerinin sağına barograf eğrisinin şeklini simgeleyen bir işaret olarak çizilir."],"tanim_en":"Single-digit code figure describing the curve shape of atmospheric pressure change during the last three hours according to WMO Code table 0200.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"code-n-total-cloud-cover","tr":"Toplam bulut kapalılığı","en":"total cloud cover","kisa":"N","tur":"kod","es":["Bulut kapalılık işareti","bulut miktarı","cloud cover code","N","WMO tablo 2700","bulut kapalılığı"],"tanim":["SYNOP Kısım 1 içindeki Nddff grubunda yer alan ve gökyüzünün bulutlarla kaplı toplam oranını belirten tek haneli kod harfidir.","WMO Tablo 2700 uyarınca sekizde bir (okta) birimiyle 0 ile 8 arasında rapor edilir; 9 gökyüzünün sis gibi nedenlerle görülemediğini, eğik çizgi (/) ise belirlenemediğini gösterir.","İstasyon modelinde istasyon dairesinin içine taranarak veya sembolle işlenir ve yer haritasında hava kapalılığını doğrudan yansıtır."],"tanim_en":"Single-digit code figure reporting the fraction of the celestial dome covered by all clouds in oktas according to WMO Code table 2700.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"wind-barb","tr":"Rüzgâr çubuğu (rüzgâr oku)","en":"Wind barb","kisa":"","tur":"kod","es":["tüy","feather","hız tüyü","rüzgâr oku","rüzgâr çubuğu","wind shaft"],"tanim":["Sinoptik haritada ve istasyon modelinde rüzgârın yönünü ve hızını göstermek amacıyla kullanılan çubuk ve tüy simgesidir.","Çubuk istasyon dairesinden rüzgârın geldiği yöne doğru uzanır; ucundaki uzun tüy 10 kt, kısa tüy 5 kt, flama ise 50 kt hıza karşılık gelir.","Yer ve üst seviye analizlerinde hava akışının yönünü, adveksiyon alanlarını ve cephe hatlarındaki rüzgâr dönmelerini belirlemede kullanılır."],"tanim_en":"Symbolic shaft and attached barbs (feathers) and pennants drawn on a synoptic chart extending towards the direction from which the wind blows to indicate wind direction and speed.","bag":{"kavram":["istasyon-modeli","ruzgar-yonu"],"soru":["S2","S3","S7","S9"],"hesap":["ruzgar-tuyu"]}},{"id":"wind-pennant","tr":"Rüzgâr flaması","en":"Wind pennant","kisa":"▲","tur":"kod","es":["flama","pennant","50 knot bayrağı","Rüzgâr oku flaması","50 knot pennant","rüzgâr bayrağı"],"tanim":["İstasyon modelinde veya üst seviye rüzgâr çubuğunda 50 knot rüzgâr hızını belirtmek için kullanılan üçgen biçimli semboldür.","Çubuğun ucuna alçak basınca bakacak biçimde çizilir ve her tam üçgen 50 kt hız değerini temsil eder.","Özellikle 300 hPa ve 250 hPa üst seviye kartlarında jet akımı çekirdeklerinin ve kuvvetli rüzgâr alanlarının hızlıca ayırt edilmesini sağlar."],"tanim_en":"Triangular symbol on the wind shaft representing a wind speed of 50 knots.","bag":{"kavram":["istasyon-modeli","ruzgar-yonu"],"soru":[],"hesap":[]}},{"id":"relative-humidity","tr":"Bağıl nem","en":"Relative humidity","kisa":"% RH","tur":"olcu","es":["nispi nem","oransal nem","nisbi nem","nem yüzdesi","RH"],"tanim":["Belirli bir sıcaklık ve basınçta havadaki su buharı basıncının, aynı koşullardaki doymuş buhar basıncına oranının yüzde olarak ifadesidir.","Yüzde (% RH) birimiyle gösterilir; çiy noktası sıcaklığı hava sıcaklığına yaklaştıkça bağıl nem % 100 değerine yaklaşır.","Sinoptik analizde özellikle 700 hPa nem haritalarında bulut oluşumu, yağış alanları ve cephesel yükselme kuşaklarını belirlemede kullanılır."],"tanim_en":"Ratio of the actual water vapour pressure of the air to the saturation vapour pressure at the same temperature and pressure, expressed as a percentage.","bag":{"kavram":["istasyon-modeli"],"soru":[],"hesap":["basinc-kodu"]}},{"id":"sleet","tr":"Karla karışık yağmur","en":"Sleet","kisa":"RASN","tur":"surec","es":["sulu sepken","yağmur ve kar","rain and snow mixed","RASN"],"tanim":["Yağmur damlaları ile eriyen kar tanelerinin veya buz taneciklerinin aynı anda yere ulaştığı karma yağış türüdür.","SYNOP şimdiki hava kodunda ww = 68 (hafif) ve ww = 69 (orta veya kuvvetli), geçmiş havada ise W = 7 koduyla bildirilir.","Kış mevsiminde sıcak cephe yaklaşırken yukarıdan düşen kar tanelerinin yere yakın, sıcaklığı 0 °C'nin biraz üstündeki tabakada kısmen erimesiyle gözlenir."],"tanim_en":"Precipitation of rain (or drizzle) and snow falling together, reported in SYNOP as ww 68–69 and in METAR as RASN; in US usage 'sleet' denotes ice pellets.","bag":{"kavram":["istasyon-modeli","synop"],"soru":[],"hesap":[]}},{"id":"unit-hectopascal","tr":"Hektopaskal","en":"Hectopascal","kisa":"hPa","tur":"birim","es":["hektopaskal basınç birimi","100 Pa","milibar","mb","Hektopascal","basınç birimi"],"tanim":["Uluslararası Birimler Sisteminde (SI) 100 Paskala eşit olan ve meteorolojide atmosfer basıncını ifade etmede kullanılan standart basınç birimidir.","Eski basınç birimi milibara tam olarak eşittir (1 hPa = 1 mb = 100 Pa); standart deniz seviyesi basıncı 1013,25 hPa olarak kabul edilir.","Yer haritalarında izobarların değerini ve 850, 700, 500, 300, 200 hPa gibi standart üst seviye izobarik yüzeylerini tanımlamada kullanılır."],"tanim_en":"Standard unit of atmospheric pressure in the International System of Units, equal to 100 pascals and equivalent to one millibar.","bag":{"kavram":["izobar","merkez","trof-sirt"],"soru":["S1","S2","S3","S5","S6","S7"],"hesap":["kalinlik","cekirdek","basinc-kodu"]}},{"id":"surface-pressure-chart","tr":"Yer basınç haritası","en":"Surface pressure chart","kisa":"yer kartı","tur":"cihaz","es":["deniz seviyesi basınç haritası","surface synoptic chart","surface analysis chart","Yer kartı","Yer sinoptik kartı","Surface chart"],"tanim":["İstasyonların deniz seviyesine indirgenmiş basınç değerleri, istasyon modelleri ve cephe hatlarının gösterildiği temel sinoptik analiz haritasıdır.","İzobarlar genellikle 1000 hPa referans alınarak 4 hPa aralıkla çizilir; yüksek (H/Y) ve alçak (L/A) basınç merkezleri kapalı izobarlarla belirlenir.","Hava kütlelerini, sıcak ve soğuk cephe sınırlarını, yer rüzgârı alanlarını ve yüzey fırtına sistemlerini izlemede kullanılır."],"tanim_en":"Synoptic weather chart displaying sea-level pressure patterns, isobars, station models and surface fronts.","bag":{"kavram":["izobar","merkez","cephe-olcutleri"],"soru":["S1"],"hesap":[]}},{"id":"closed-isobar","tr":"Kapalı izobar","en":"Closed isobar","kisa":"","tur":"kavram","es":["kapalı eş basınç eğrisi","closed isobaric contour","kapalı eşbasınç eğrisi","kapalı izobar çizgisi","Kapalı izobarlar","Closed isobars"],"tanim":["Yer basınç haritasında kendi üzerine kapanarak bir alçak veya yüksek basınç merkezini bütünüyle çevreleyen izobardır.","İçeriye doğru değerler artıyorsa yüksek basınç (H/Y) merkezini, içeriye doğru azalıyorsa alçak basınç (L/A) merkezini sınırlandırır.","Merkez etrafındaki jeostrofik rüzgâr dolaşımının yönünü, gradyan kuvvetini ve siklonik veya antisiklonik akış alanını ortaya koyar."],"tanim_en":"Isobar on a surface chart that forms a complete loop enclosing a high or low pressure centre.","bag":{"kavram":["izobar","merkez"],"soru":["S2"],"hesap":[]}},{"id":"atmospheric-pressure","tr":"Atmosfer basıncı","en":"Atmospheric pressure","kisa":"p","tur":"olcu","es":["hava basıncı","barometrik basınç","barometric pressure","air pressure"],"tanim":["Atmosferin ağırlığından doğan, birim yüzeye etkiyen kuvvettir; hidrostatik yaklaşımda o noktanın üstündeki birim kesitli hava sütununun ağırlığına eşittir.","Birim olarak hektopaskal (hPa) kullanılır; standart deniz seviyesi basıncı 1013,25 hPa kabul edilir.","Yer haritasında izobarlarla, üst seviye kartlarında ise sabit izobarik yüzeylerin jeopotansiyel yüksekliğiyle analiz edilir."],"tanim_en":"Pressure exerted by the atmosphere on any surface by virtue of its weight, equivalent to the weight of a vertical column of air extending above a unit area.","bag":{"kavram":["izobar","merkez","synop"],"soru":[],"hesap":["izobar-yeri"]}},{"id":"sea-level-pressure","tr":"Deniz seviyesi basıncı","en":"Sea-level pressure","kisa":"MSLP","tur":"olcu","es":["deniz seviyesine indirgenmiş basınç","mean sea level pressure","indirgenmiş basınç","MSL pressure","QFF"],"tanim":["İstasyon seviyesinde ölçülen hava basıncının, sıcaklık ve yükseklik düzeltmeleri yapılarak ortalama deniz seviyesine indirgenmiş değeridir.","SYNOP iletisinde Kısım 1 içindeki 4PPPP grubunda onda bir hPa duyarlığında verilir; binler hanesi atılarak iletilir.","Yer haritasında topoğrafya farklarını ortadan kaldırarak yatay basınç gradyanını ve hava sistemlerini izobarlarla göstermek için kullanılır."],"tanim_en":"Atmospheric pressure at mean sea level obtained by reducing the measured station pressure according to standard atmospheric temperature and height corrections.","bag":{"kavram":["izobar","merkez","istasyon-modeli"],"soru":[],"hesap":["izobar-yeri"]}},{"id":"sym-station-pressure-p1","tr":"Komşu istasyon basınçları","en":"pressures at neighbouring stations","kisa":"p₁, p₂","tur":"olcu","es":["birinci istasyon basıncı","ikinci istasyon basıncı","Komşu istasyonun basıncı","Pressure at second neighbouring station","komşu istasyonun basıncı","p₁"],"tanim":["Yer haritasında izobar analizinde doğrusal interpolasyon yapılan iki komşu istasyonda ölçülen indirgenmiş basınç değerleridir.","İki istasyon arasındaki p₂ - p₁ farkı büyüdükçe basınç gradyanı artar ve izobarlar daha sık geçer.","Hesaplamada p₁ ölçümün başladığı istasyonun basıncını, p₂ ise aralığın öbür ucundaki komşu istasyonun basıncını temsil eder."],"tanim_en":"Observed pressure values at two adjacent stations used to determine the exact location of an intermediate isobar through linear interpolation.","bag":{"kavram":["izobar"],"soru":["S1"],"hesap":["izobar-yeri"]}},{"id":"sym-station-spacing-delta-x","tr":"İki istasyon arası uzaklık","en":"Distance between neighbouring stations","kisa":"Δx","tur":"olcu","es":["istasyon aralığı","mesh spacing Δx","istasyonlar arası uzaklık","istasyon mesafesi","mesh spacing","Δx"],"tanim":["Harita üzerinde veya analiz ızgarasında seçilen iki komşu gözlem istasyonu arasındaki yatay geometrik mesafedir.","Analiz alıştırmalarında birim aralık (1 aralık) olarak alınırken gerçek haritalarda kilometre cinsinden ölçeklenir.","İki istasyon arasındaki izobar kesişme noktasının (x) başlangıç istasyonuna olan mesafesini orantılamak için ölçek katsayısı görevi görür."],"tanim_en":"Horizontal distance between two adjacent observation stations used as the geometric scale for interpolating isobar positions.","bag":{"kavram":["izobar"],"soru":["S1","S6"],"hesap":["izobar-yeri","adveksiyon"]}},{"id":"rule-isobar-interval","tr":"4 hPa izobar aralığı kuralı","en":"4 hPa isobar interval rule","kisa":"4 hPa","tur":"yontem","es":["izobar çizim kuralı","standart izobar aralığı","izobar çizim aralığı","isobar spacing interval","izobar aralığı","isobaric interval"],"tanim":["Sinoptik yer haritalarında deniz seviyesi basınç alanını göstermek için izobarların 4 hPa farkla çizilmesini öngören standart analiz kuralıdır.","İzobarlar referans olarak 1000 hPa tabanından başlanarak dörder hektopaskal artırılıp azaltılarak (996, 1000, 1004 hPa) belirlenir.","Basınç alanının eğimini standartlaştırarak farklı haritalar arasında basınç gradyanı ve jeostrofik rüzgâr şiddetinin doğrudan kıyaslanmasını sağlar."],"tanim_en":"Standard synoptic convention of drawing surface isobars at 4 hPa intervals referenced to 1000 hPa to represent horizontal pressure gradients consistently.","bag":{"kavram":["izobar"],"soru":[],"hesap":["izobar-yeri"]}},{"id":"chart-300-hpa","tr":"300 hPa kartı","en":"300 hPa chart","kisa":"300 hPa","tur":"cihaz","es":["300 hPa izotak haritası","300 hPa seviyesi","300 hPa haritası","300 hPa jet chart","300 mb haritası","üst seviye rüzgâr kartı"],"tanim":["Troposferin üst katmanında yaklaşık 900 dam (9 km) jeopotansiyel yüksekliğe karşılık gelen standart izobarik analiz haritasıdır.","Üzerine jeopotansiyel yükseklik konturları ile 60 kt'tan başlayıp 20 kt aralıkla artan izotaklar çizilir.","Özellikle polar cephe jet akımının eksenini, jet çekirdeklerini ve yatay rüzgâr kesmesini belirlemede temel başvuru kartıdır."],"tanim_en":"Upper-level constant-pressure chart at the 300 hPa level used to determine the polar-front jet stream core and wind distribution.","bag":{"kavram":["izotak","jet-akimi","jeopotansiyel"],"soru":[],"hesap":[]}},{"id":"horizontal-wind-shear","tr":"Yatay rüzgâr kesmesi","en":"horizontal wind shear","kisa":"","tur":"olcu","es":["yatay kesme","horizontal shear"],"tanim":["Yatay bir düzlem boyunca rüzgâr vektörünün yönünde veya hızında mesafeye bağlı olarak meydana gelen değişimdir.","Jet akımı çevresinde izotakların sıklaştığı bölgelerde, özellikle jet ekseninin soğuk (kuzey) tarafında en yüksek değerine ulaşır.","Üst seviye analizinde göreli vortisite üretimini, türbülansı ve dinamik dengesizlik bölgelerini saptamakta değerlendirilir."],"tanim_en":"Change in horizontal wind direction or speed with distance along a horizontal surface.","bag":{"kavram":["izotak","jet-akimi"],"soru":[],"hesap":[]}},{"id":"standard-isotach-interval","tr":"Standart izotak aralığı","en":"Standard isotach interval","kisa":"20 kt","tur":"yontem","es":["izotak aralığı","20 kt aralık","standard isotach spacing","isotach step"],"tanim":["Üst seviye rüzgâr ve jet haritalarında eşit rüzgâr hızı çizgilerini kademelendirmek için kullanılan standart hız farkıdır.","200 ve 300 hPa kartlarında 60 kt eşiğinden başlayarak her halkada yirmişer knot (60, 80, 100, 120 kt) artacak biçimde uygulanır.","Eksik izotak değerlerinin doldurulmasını ve rüzgâr hızının jet çekirdeğine doğru düzenli artışının takip edilmesini sağlar."],"tanim_en":"Standard increment of 20 kt starting from 60 kt used to contour isotachs on upper-level charts.","bag":{"kavram":["izotak"],"soru":["S6"],"hesap":[]}},{"id":"numerical-weather-prediction-model","tr":"Sayısal hava tahmin modeli","en":"Numerical weather prediction model","kisa":"NWP","tur":"cihaz","es":["sayısal model","sayısal hava tahmini","NWP model","sayısal tahmin modeli"],"tanim":["Atmosferin hidrodinamik ve termodinamik korunum denklemlerini ızgara ağları üzerinde zaman adımlarıyla sayısal çözen bilgisayar modelidir.","Gözlem verilerini başlangıç alanı olarak alır; yarı-Lagrange gibi adveksiyon algoritmalarıyla değişkenleri geleceğe doğru taşır.","Sinoptik hava analizi ve tahmininde gelecekteki basınç, sıcaklık ve rüzgâr alanlarının öngörülmesini sağlar."],"tanim_en":"Computer model that integrates the mathematical equations of atmospheric hydrodynamics and thermodynamics forward in time on a computational grid.","bag":{"kavram":["izoterm-tasima"],"soru":[],"hesap":[]}},{"id":"downstream","tr":"Akış yönünde (akış aşağı)","en":"downstream","kisa":"","tur":"kavram","es":["akış aşağı","downstream transport","akış yönünde","akıntı yönü"],"tanim":["Atmosferdeki hava akımının veya rüzgâr vektörünün ilerlediği yönü belirten sinoptik doğrultudur.","Üst seviye dalgalarında trof ekseninin önü (doğusu) akış aşağı yönü oluşturur; burada ıraksama ve yükselme hareketi gelişir.","Yarı-Lagrange adveksiyonunda hava parseli gerideki kaynak noktasından akış yönündeki hedef ızgara noktasına doğru taşınır."],"tanim_en":"Direction toward which the wind or fluid is moving in the atmosphere.","bag":{"kavram":["izoterm-tasima","adveksiyon"],"soru":["S8"],"hesap":[]}},{"id":"upstream-point","tr":"S noktası (akışın geldiği taraf)","en":"Upstream point","kisa":"S","tur":"kavram","es":["akış yukarı noktası","S noktası","okun kuyruğu","akış yukarı noktası S","upstream departure point","ayak noktası"],"tanim":["Yarı-Lagrange adveksiyon yaklaşımında, belirli bir zaman aralığı (Δt) sonra tahmin noktasına (P) varacak hava parselinin başlangıç konumunu belirtir.","Rüzgâr vektörünün tersi yönünde gidilerek okun kuyruğunda bulunur; harita üzerinde parselin kalkış yerini gösterir.","Sıcaklık adveksiyonu analizinde bu noktadaki şimdiki sıcaklık değeri, tahmin noktasının Δt sonraki sıcaklığı kabul edilir."],"tanim_en":"An upstream point is the departure position of an air parcel that will reach a given forecast point after a specified time interval in a semi-Lagrangian scheme.","bag":{"kavram":["izoterm-tasima","ruzgar-yonu","adveksiyon"],"soru":["S6","S7","S8"],"hesap":["izoterm-tasima"]}},{"id":"sym-delta-t","tr":"Zaman aralığı","en":"Time interval","kisa":"Δt","tur":"olcu","es":["zaman adımı","time step","zaman farkı","time increment"],"tanim":["İki an arasındaki süreyi ya da adveksiyon hesabındaki öngörü zaman adımını gösteren skaler büyüklüktür.","Birim olarak saniye (s) veya saat kullanılır; yarı-Lagrange hesaplarında geriye doğru gidilecek mesafe bu aralık ile rüzgâr hızının çarpımıdır.","İzotermlerin rüzgârla taşınmasında başlangıç anı (t) ile tahmin anı (t+Δt) arasındaki zaman farkını temsil eder."],"tanim_en":"The duration between two instants; in advection calculations, the time step over which air is carried by the wind.","bag":{"kavram":["izoterm-tasima"],"soru":["S8"],"hesap":["adveksiyon","izoterm-tasima"]}},{"id":"backward-trajectory","tr":"Geri yörünge","en":"Backward trajectory","kisa":"","tur":"yontem","es":["ters yörünge","back-trajectory","geriye doğru yörünge","backward parcel trajectory"],"tanim":["Belirli bir noktaya ve zamana varan bir hava parselinin geçmişte izlediği yolu zamanda geriye doğru belirleme yöntemidir.","Düzgün ve sabit rüzgâr kabulü altında, rüzgâr vektörünün tersi yönünde zaman adımı kadar geriye gidilerek doğrusal hesaplanır.","Yarı-Lagrange sayısal hava tahmin şemalarında her ızgara noktası için kalkış noktasını bulup özellik taşımada temel alınır."],"tanim_en":"A backward trajectory is a path traced backward in time to determine the origin and history of an air parcel arriving at a specific location.","bag":{"kavram":["izoterm-tasima"],"soru":[],"hesap":["izoterm-tasima"]}},{"id":"unit-decametre","tr":"Dekametre","en":"Decametre","kisa":"dam","tur":"birim","es":["10 metre","dekametre yükseklik birimi","decameter","10 gpm","dam","jeopotansiyel dekametre"],"tanim":["10 metreye (10 gpm) eşit uzunluk ve jeopotansiyel yükseklik birimidir; sinoptik meteorolojide kontur ve kalınlık değerleri bu birimle yazılır.","Üst seviye sabit basınç haritalarında kontur değerleri ve tabaka kalınlığı dekametre (dam) cinsinden ifade edilir (ör. 500 hPa'da 6 dam aralık = 60 m).","Harita analizinde kontur etiketlerini sadeleştirmek için kullanılır (ör. 5520 gpm yerine 552 dam yazılır)."],"tanim_en":"A decametre is a unit of length equal to ten metres (ten geopotential metres), widely used on upper-level synoptic charts to express geopotential height and thickness.","bag":{"kavram":["jeopotansiyel","jeostrofik","trof-sirt"],"soru":["S3","S7","S9","S10"],"hesap":[]}},{"id":"unit-geopotential-metre","tr":"Jeopotansiyel metre","en":"Geopotential metre","kisa":"gpm","tur":"birim","es":["geopotential meter","gpm","jeopotansiyel yükseklik birimi"],"tanim":["Yerçekimi potansiyeli temel alınarak tanımlanan ve standart yerçekimi ivmesine (g₀ = 9,80665 m/s²) bölünen meteorolojik yükseklik birimidir.","Troposfer içinde geometrik metreden farkı binde birkaç düzeyinde; üst seviye kartlarında 500 hPa yüzeyi tipik olarak 5520–5640 gpm arasındadır.","Basınç yüzeylerinin yüksekliğini ve tabakalar arası kalınlığı yerçekimi ivmesindeki enlem ve yükseklik değişimlerinden bağımsız kılmak için kullanılır."],"tanim_en":"A geopotential metre is a standard unit of height related to Earth's gravity field, used to define the elevation of constant-pressure surfaces independent of local variations in gravitational acceleration.","bag":{"kavram":["jeopotansiyel","kalinlik"],"soru":[],"hesap":[]}},{"id":"chart-500-hpa","tr":"500 hPa haritası","en":"500 hPa chart","kisa":"500 hPa","tur":"cihaz","es":["500 hPa seviyesi kartı","500 hPa constant pressure chart","500 hPa kartı","500 hPa seviyesi","500 hPa contour chart","500 mb haritası"],"tanim":["Orta troposferde yaklaşık 5,5 km yüksekliğe karşılık gelen 500 hPa standart izobarik yüzeyindeki jeopotansiyel yükseklik ve sıcaklık alanlarını gösteren üst seviye analiz haritasıdır.","Haritada konturlar genellikle 6 dam (60 m) aralıkla çizilir; rüzgâr sürtünmesiz serbest atmosfer koşullarında konturlara paralel kabul edilir.","Büyük ölçekli trof ve sırt sistemlerini belirlemede, yönlendirici akışı izlemede ve düşey hareket tahmininde temel referans seviyesidir."],"tanim_en":"A 500 hPa chart is a constant-pressure upper-air map representing geopotential height and temperature fields in the middle troposphere around 5.5 km.","bag":{"kavram":["jeopotansiyel","jeostrofik","trof-sirt"],"soru":["S2","S3","S5","S7","S9","S10"],"hesap":["kalinlik","cekirdek"]}},{"id":"chart-700-hpa","tr":"700 hPa haritası","en":"700 hPa chart","kisa":"700 hPa","tur":"cihaz","es":["700 hPa kartı","700 hPa seviyesi","700 mb haritası","700 hPa synoptic chart","700 hPa analiz kartı","700 hPa analysis chart"],"tanim":["Alt-orta troposferde yaklaşık 3 km (tipik olarak 300 dam) yüksekliğe denk gelen 700 hPa standart izobarik yüzeyindeki akış ve nem alanlarını gösteren üst seviye haritasıdır.","İstasyon yüksekliği 2300–3700 m olan dağ istasyonlarında SYNOP raporlarında a₃ = 7 göstericisiyle bu seviyenin yüksekliği bildirilir.","Hava tahmininde ve analizlerde özellikle nem taşınımını, orta seviye troflarını ve bulut oluşumuna uygun nemli katmanları incelemede kullanılır."],"tanim_en":"A 700 hPa chart is a constant-pressure upper-air map at approximately 3 km altitude, used primarily to evaluate moisture distribution and mid-tropospheric flow patterns.","bag":{"kavram":["jeopotansiyel","trof-sirt"],"soru":[],"hesap":[]}},{"id":"constant-pressure-chart","tr":"Sabit basınç haritası","en":"Constant-pressure chart","kisa":"","tur":"cihaz","es":["izobarik harita","isobaric chart","üst seviye kartı","izobarik kart","üst seviye haritası","Sabit basınç kartı"],"tanim":["Belirli bir izobarik yüzeyin konturlarının (mutlak topoğrafyasının) ve diğer meteorolojik elemanların sinoptik dağılımının çizildiği hava haritasıdır.","Basıncın sabit tutulduğu bu haritalarda (850, 700, 500, 300 hPa) temel değişken jeopotansiyel yüksekliktir (dam veya gpm).","Alçak ve yüksek merkezler yükseklik değerlerine göre belirlenir; en küçük kontur değeri alçak merkezi gösterir."],"tanim_en":"A constant-pressure chart is a weather map showing contours of geopotential height and other meteorological elements on a specific isobaric surface.","bag":{"kavram":["jeopotansiyel"],"soru":["S10"],"hesap":[]}},{"id":"contour-height","tr":"Kontur","en":"Contour","kisa":"Z","tur":"kavram","es":["eş yükseklik çizgisi","geopotential contour","izohips","height contour","Z sembolü","geopotential height symbol"],"tanim":["Sabit basınç yüzeyinde eşit jeopotansiyel yükseklik değerine sahip noktaları birleştiren eş yükseklik çizgisidir (izohips).","Üst seviye haritalarında genellikle dekametre (dam) birimiyle etiketlenir; 500 hPa seviyesinde standart çizim aralığı 6 dam'dır.","Üst seviyede jeostrofik rüzgâr konturlara paralel eser; konturların sıklaştığı alanlarda basınç gradyan kuvveti ve rüzgâr hızı artar."],"tanim_en":"A contour is a line on a constant-pressure chart connecting points of equal geopotential height.","bag":{"kavram":["jeopotansiyel","jeostrofik"],"soru":["S2","S3","S7","S9"],"hesap":[]}},{"id":"standard-isobaric-surface","tr":"Standart izobarik yüzey","en":"Standard isobaric surface","kisa":"p = sabit","tur":"kavram","es":["Standart basınç seviyesi","Sabit basınç seviyesi","eş basınç yüzeyi","constant pressure surface","sabit basınç yüzeyi","isobaric surface"],"tanim":["Her noktasında atmosfer basıncının aynı değere sahip olduğu yüzeydir.","Sinoptik meteorolojide uluslararası mutabakatla belirlenen ana standart seviyelerdir (1000, 850, 700, 500, 300, 250, 200 hPa).","SYNOP kodunda istasyon yüksekliği 1000 m üzerinde olan istasyonlar 4a₃hhh grubu ile bu seviyedeki jeopotansiyel yüksekliği bildirir."],"tanim_en":"A standard isobaric surface is an atmospheric surface of constant pressure specified by international agreement for meteorological observation and upper-level charting.","bag":{"kavram":["jeopotansiyel","izobar"],"soru":[],"hesap":[]}},{"id":"geopotential","tr":"Jeopotansiyel","en":"Geopotential","kisa":"Φ","tur":"olcu","es":["yerçekimi potansiyeli","geopotential energy","Phi","geopotential symbol","yerçekimi potansiyel enerjisi"],"tanim":["Yerçekimi alanında birim kütleyi deniz seviyesinden belirli bir geometrik yüksekliğe çıkarmak için yerçekimine karşı yapılan iştir.","Birimi m² s⁻² ya da J kg⁻¹ olup 500 hPa seviyesinde tipik değeri yaklaşık 5,5×10⁴ m² s⁻² civarındadır.","Standart yerçekimi ivmesine bölünerek jeopotansiyel yükseklik elde edilir ve üst seviye basınç yüzeylerinin haritalanmasında temel oluşturur."],"tanim_en":"The potential energy of a unit mass relative to mean sea level, equal to the work done against gravity to lift the mass to a given geometric height.","bag":{"kavram":["jeopotansiyel"],"soru":[],"hesap":[]}},{"id":"ideal-gas-law","tr":"İdeal gaz yasası","en":"Ideal gas law","kisa":"p = ρ R_d T","tur":"yontem","es":["gaz denklemi","equation of state","durum denklemi","ideal gaz denklemi"],"tanim":["Gazların basıncı, yoğunluğu ve sıcaklığı arasındaki ilişkiyi kuru hava gaz sabiti ile bağlayan durum denklemidir.","Sinoptik meteorolojide kuru hava için p = ρ R_d T biçiminde ifade edilir; R_d kuru hava için 287 J kg⁻¹ K⁻¹ değerini alır.","Hidrostatik denge ile birleştirilerek hipsometrik denklem ve kalınlık bağıntılarının türetilmesini sağlar."],"tanim_en":"The equation of state relating pressure, density, and temperature of air through the specific gas constant.","bag":{"kavram":["jeopotansiyel","kalinlik"],"soru":[],"hesap":["kalinlik"]}},{"id":"rule-contour-interval","tr":"6 dam kontur aralığı kuralı","en":"6 dam contour interval rule","kisa":"6 dam","tur":"yontem","es":["kontur çizim kuralı","standart kontur aralığı","60 gpm aralık","6 dam kontur aralığı","6 dam contour interval","eşyükseklik çizgisi aralığı"],"tanim":["500 hPa haritasında jeopotansiyel yükseklik konturlarının 6 dekametre (60 gpm) aralıkla çizilmesi kuralıdır; öbür seviyelerde aralık değişebilir (alt seviyelerde daha sık, üst seviyelerde daha seyrek).","500 hPa haritasında standart çıpa değeri olarak 552 dam alınır ve konturlar 546, 552, 558, 564 dam biçiminde devam eder.","Konturlar arasındaki sıklık jeostrofik rüzgâr hızını doğrudan yansıtır; konturlar sıklaştıkça jeostrofik rüzgâr hızı artar."],"tanim_en":"The convention of drawing geopotential height contours at intervals of 6 decametres on the 500 hPa chart.","bag":{"kavram":["jeopotansiyel","jeostrofik"],"soru":[],"hesap":[]}},{"id":"unit-metre-per-second","tr":"Metre bölü saniye","en":"Metres per second","kisa":"m/s","tur":"birim","es":["m s⁻¹","SI hız birimi","rüzgâr hızı birimi","Metre per second","m/s","meter per second"],"tanim":["Uluslararası Birimler Sisteminde (SI) hız için kullanılan temel türetilmiş birimdir.","Meteorolojide rüzgâr hızı ve hız bileşenlerinin sayısal hesaplamalarında kullanılır; 1 knot yaklaşık 0,514 m/s değerine karşılık gelir.","Sinoptik haritalarda rüzgâr çubuğunda çoğunlukla knot kullanılırken, formüllerde ve dinamik bağıntılarda m/s birimi esas alınır."],"tanim_en":"The International System of Units derived unit of speed, representing the distance in metres travelled per second.","bag":{"kavram":["jeostrofik","ruzgar-yonu","trof-onu"],"soru":["S6"],"hesap":["adveksiyon","ruzgar"]}},{"id":"sym-gravitational-acceleration-g","tr":"Yerçekimi ivmesi","en":"Gravitational acceleration","kisa":"g","tur":"olcu","es":["yerçekimi sabiti g","yerçekimi sabiti","acceleration of gravity symbol","yerçekimi","standard gravity","yer çekimi ivmesi"],"tanim":["Dünya'nın kütleçekim kuvveti ile dönmesinden kaynaklanan merkezkaç kuvvetinin bileşkesinden doğan ivmedir.","Standart değeri g₀ = 9,80665 m s⁻² (yaklaşık 9,81 m/s²) olup kutuplara ve ekvatora göre enlemle küçük değişim gösterir.","Hidrostatik dengede düşey basınç kuvvetini dengeler ve jeopotansiyeli jeopotansiyel yüksekliğe dönüştürmek için kullanılır."],"tanim_en":"The acceleration imparted to bodies by the attractive force of the Earth combined with the centrifugal force of its rotation.","bag":{"kavram":["jeostrofik","kalinlik","jeopotansiyel"],"soru":["S5"],"hesap":["kalinlik"]}},{"id":"hydrostatic-balance","tr":"Hidrostatik denge","en":"Hydrostatic balance","kisa":"dp/dz = −ρg","tur":"yontem","es":["hidrostatik eşitlik","hydrostatic equilibrium","hidrostatik denklem","Hidrostatik denge denklemi","hidrostatik denge denklemi"],"tanim":["Düşey basınç gradyanı kuvveti ile yerçekimi kuvvetinin tam olarak dengede olduğu durumdur.","Atmosferde dp/dz = −ρg biçiminde ifade edilir; sinoptik ölçekte düşey ivmeler çok küçük olduğundan geçerli bir yaklaşıklıktır.","İzobarik koordinat sistemine geçişi sağlar ve basınç yüzeylerindeki eğim ile jeostrofik rüzgâr arasındaki bağıntıyı kurar."],"tanim_en":"The vertical balance between the upward pressure gradient force and the downward force of gravity.","bag":{"kavram":["jeostrofik","kalinlik","jeopotansiyel"],"soru":[],"hesap":["kalinlik"]}},{"id":"hadley-cell","tr":"Hadley hücresi","en":"Hadley cell","kisa":"","tur":"kavram","es":["Hadley dolaşımı","Hadley dolaşım hücresi","Hadley circulation","tropikal hücre"],"tanim":["Ekvator ile yaklaşık 30° enlemleri arasında uzanan, doğrudan termal kökenli meridyonel atmosfer dolaşımı hücresidir.","Ekvatorda ısınarak yükselen hava üst seviyede kutba doğru yönelir; yaklaşık 30° enlem civarında çökerek subtropikal yüksek basınç kuşağını oluşturur.","Hücrenin kutup kenarında (yaklaşık 200 hPa seviyesinde) açısal momentum korunumu sonucu subtropikal jet akımı meydana gelir."],"tanim_en":"A direct, thermally driven meridional circulation cell with rising motion near the equator and descending motion in the subtropics.","bag":{"kavram":["jet-akimi"],"soru":[],"hesap":[]}},{"id":"polar-front-jet","tr":"Polar cephe jeti","en":"polar-front jet","kisa":"PFJ","tur":"kavram","es":["kutup cephesi jeti","polar jet","polar-front jet stream"],"tanim":["Soğuk kutup havası ile ılık orta enlem havası arasındaki güçlü baroklinik kuşak üzerinde oluşan dar ve hızlı üst seviye rüzgâr bandıdır.","Standart izobarik haritalarda yaklaşık 250–300 hPa seviyesinde bulunur; hızı en az 30 m/s (yaklaşık 60 kt) olup çekirdeğinde 100 kt üzerine çıkabilir.","Polar cepheye ve 500 hPa troflarına eşlik eder; konumu, şiddeti ve kıvrımları günden güne belirgin değişim gösterir."],"tanim_en":"A jet stream formed in the upper troposphere above the polar front where the strongest horizontal temperature contrast occurs.","bag":{"kavram":["jet-akimi"],"soru":[],"hesap":[]}},{"id":"subtropical-jet","tr":"Subtropikal jet","en":"subtropical jet","kisa":"STJ","tur":"kavram","es":["subtropikal jet akımı","yarı tropikal jet","subtropical jet stream","alt tropikal jet","subtropik jet"],"tanim":["Yaklaşık 25–35° enlemleri arasında, Hadley hücresinin kutup kenarında açısal momentum korunumu sonucu oluşan üst seviye batı rüzgârı bandıdır.","Genellikle yaklaşık 200 hPa seviyesinde yer alır; kış mevsiminde yaz mevsimine göre belirgin şekilde daha güçlü ve süreklidir.","Polar jet gibi yer cepheleriyle doğrudan bağlantılı değildir; subtropikal sırtın kutba bakan tarafında akar."],"tanim_en":"A persistent upper-tropospheric jet stream located at about 200 hPa along the poleward boundary of the Hadley cell.","bag":{"kavram":["jet-akimi"],"soru":[],"hesap":[]}},{"id":"entrance-region","tr":"Giriş bölgesi","en":"entrance region","kisa":"","tur":"kavram","es":["akışın yukarısı","jet streak entrance","jet girişi","Jet streak giriş bölgesi","Jet streak entrance region"],"tanim":["Bir jet çekirdeğinin (jet streak) akış yönünde rüzgâr hızının arttığı, akış yukarısında kalan giriş bölgesidir.","Dört kadran modelinde giriş bölgesinin sağ kesimi üst seviye diverjansı ve yükselici hareket alanı iken, sol kesimi konverjans alanıdır.","Havanın hızlanması sırasında Coriolis kuvveti basınç gradyanının gerisinde kaldığından alçak basınca doğru ageostrofik rüzgâr bileşeni doğar."],"tanim_en":"The upstream sector of a jet streak in which air accelerates into the jet core.","bag":{"kavram":["jet-streak"],"soru":[],"hesap":[]}},{"id":"exit-region","tr":"Çıkış bölgesi","en":"exit region","kisa":"","tur":"kavram","es":["akışın aşağısı","jet streak exit","jet streak çıkışı","jet akımı çıkışı","jet diffluence zone","jet çıkış bölgesi"],"tanim":["Jet akımının veya jet çekirdeğinin akış aşağı ucundaki yön ıraksaması (dağılma) bölgesidir.","Rüzgâr hızının akış boyunca yavaşladığı bu alanda sol ve sağ kadranlar zıt düşey hareket özellikleri sergiler.","Üst seviye analizinde sol çıkış ıraksama ve yükselme, sağ çıkış ise yakınsama ve çökme sahası olarak değerlendirilir."],"tanim_en":"Region of diffluence at the downwind end of a jet stream.","bag":{"kavram":["jet-streak","yakinsama"],"soru":[],"hesap":[]}},{"id":"left-exit-region","tr":"Sol çıkış bölgesi","en":"left-exit region","kisa":"","tur":"kavram","es":["sol çıkış","jet streak sol çıkışı","Sol çıkış bölgesi (jet streak)","sol çıkış kadranı"],"tanim":["Jet çekirdeğinin akış yönüne göre çıkış bölgesinin solunda kalan kadrandır.","Bu kadranda üst seviye rüzgârında yatay ıraksama meydana gelir ve alt seviyelerden yukarıya doğru düşey yükselme hareketi tetiklenir.","Sinoptik harita analizinde yüzey alçak basınç merkezlerinin ve cephesel siklonların gelişimi için en elverişli alanlardan biridir."],"tanim_en":"The quadrant situated to the left of the jet streak exit where upper-level divergence promotes upward vertical motion.","bag":{"kavram":["jet-streak","yakinsama"],"soru":[],"hesap":[]}},{"id":"right-entrance-region","tr":"Sağ giriş bölgesi","en":"right-entrance region","kisa":"","tur":"kavram","es":["sağ giriş","jet streak sağ girişi","Sağ giriş bölgesi (jet streak)","sağ giriş kadranı"],"tanim":["Jet çekirdeğinin akış yönüne göre giriş bölgesinin sağında (ekvator tarafında) kalan kadrandır.","Hızlanan hava akımı nedeniyle oluşan ageostrofik rüzgâr sola yönelir; bu durum sağ kadranda üst seviye ıraksaması meydana getirir.","Üst seviyedeki bu kütle boşalması alttan yükselme hareketini ve yüzeyde basınç düşüşünü tetikler."],"tanim_en":"The quadrant located to the right of a jet streak entrance where upper-level divergence and upward motion develop.","bag":{"kavram":["jet-streak","yakinsama"],"soru":[],"hesap":[]}},{"id":"ageostrophic-wind","tr":"Ageostrofik rüzgâr","en":"ageostrophic wind","kisa":"V_ag","tur":"olcu","es":["ageostrofik rüzgâr vektörü","jeostrofik olmayan rüzgâr","ageostrophic wind component"],"tanim":["Gerçek rüzgâr vektörü ile jeostrofik rüzgâr vektörü arasındaki vektörel farktır.","Birimi m/s olup sinoptik ölçekte tipik büyüklüğü birkaç m/s mertebesinde kalır.","Akışın izobar ve konturları kesen kısmı bu bileşenden gelir; yatay yakınsama ve ıraksamayı, dolayısıyla düşey hareketi doğurur."],"tanim_en":"Vector difference between the actual wind and the geostrophic wind.","bag":{"kavram":["jet-streak","jeostrofik"],"soru":[],"hesap":[]}},{"id":"four-quadrant-jet-model","tr":"Dört kadran modeli","en":"four-quadrant jet model","kisa":"","tur":"yontem","es":["jet streak dört kadranı","jet quadrant model","dört kadran teorisi","jet streak modeli","four-quadrant model","Four-quadrant jet streak model"],"tanim":["Düz bir jet çekirdeği çevresindeki akışı giriş ve çıkış eksenleri boyunca dört ayrı bölgeye ayıran kavramsal modeldir.","Modelde sağ giriş ve sol çıkış kadranları üst seviye ıraksaması, sol giriş ve sağ çıkış kadranları ise üst seviye yakınsaması sergiler.","Üst seviye haritalarında düşey sirkülasyon hücrelerini, bulutluluk alanlarını ve yer siklonlarının gelişim bölgelerini belirlemede kullanılır."],"tanim_en":"A conceptual model dividing a straight jet streak into four quadrants to explain patterns of divergence and vertical circulation.","bag":{"kavram":["jet-streak","yakinsama"],"soru":[],"hesap":[]}},{"id":"unit-kelvin","tr":"Kelvin","en":"Kelvin","kisa":"K","tur":"birim","es":["mutlak sıcaklık birimi","K","kelvin derecesi","termodinamik sıcaklık birimi"],"tanim":["Suyun üçlü noktasının termodinamik sıcaklığının 1/273,16 kadarına eşit olan SI mutlak sıcaklık birimidir.","Sembolü K olup derece işareti olmadan yazılır ve mutlak sıfır noktası 0 K (−273,15 °C) kabul edilir.","Hipsometrik denklemde ve ideal gaz yasasında tabaka kalınlığı ve hava yoğunluğu hesaplamalarında mutlak sıcaklık olarak kullanılır."],"tanim_en":"Unit of absolute temperature equal to 1/273.16 of the absolute temperature of the triple point of water.","bag":{"kavram":["kalinlik","termal-ruzgar"],"soru":["S5"],"hesap":[]}},{"id":"thickness-chart","tr":"Kalınlık haritası","en":"Thickness chart","kisa":"","tur":"cihaz","es":["Kalınlık kartı","kalınlık kartı","göreli topoğrafya haritası","thickness map"],"tanim":["Belirli iki izobarik yüzey arasındaki jeopotansiyel kalınlık dağılımını eş kalınlık çizgileriyle gösteren haritadır.","Hipsometrik denklem gereği kalınlık çizgileri iki seviye arasındaki tabakanın ortalama izotermlerine karşılık gelir.","Sinoptik analizde sıcak ve soğuk hava kütlelerini, termal adveksiyonu ve 540 dam çizgisiyle yağmur kar sınırını saptamak için kullanılır."],"tanim_en":"A chart showing the thickness distribution between two constant-pressure levels drawn at equal intervals.","bag":{"kavram":["kalinlik"],"soru":[],"hesap":[]}},{"id":"relative-topography","tr":"Rölatif topografya","en":"relative topography","kisa":"RT","tur":"kavram","es":["kalınlık topografyası","relative geopotential","göreli topoğrafya","kalınlık alanı","thickness pattern"],"tanim":["İki standart izobarik yüzey arasındaki jeopotansiyel yükseklik farkını ve bu farkın yatay dağılımını temsil eden topoğrafyadır.","Haritalarda eş kalınlık çizgileri veya renk skalası ile gösterilir; değeri doğrudan tabakanın ortalama sanal sıcaklığına bağlıdır.","Sinoptik modellerde troposferik sıcak ve soğuk hava adveksiyonunu, baroklinik bölgeleri ve termal rüzgâr akışını analiz etmede temel teşkil eder."],"tanim_en":"The distribution of geopotential thickness between two isobaric levels representing layer mean temperature.","bag":{"kavram":["kalinlik"],"soru":[],"hesap":[]}},{"id":"scale-height","tr":"Ölçek yüksekliği","en":"Scale height","kisa":"H","tur":"kavram","es":["atmosferik ölçek yüksekliği","scale height H"],"tanim":["Atmosfer basıncının veya yoğunluğunun e kat (yaklaşık 2,718 kat) azalması için gereken karakteristik düşey mesafedir.","Sembolü H olup birimi metredir; kuru hava için H = R_d T / g formülüyle verilir ve Kelvin başına yaklaşık 29,3 m/K değerini alır.","İzotermal atmosfer yaklaşımında ve hipsometrik bağıntılarda düşey basınç profilini ve kalınlık değişimini ölçeklendirmede kullanılır."],"tanim_en":"The vertical distance over which atmospheric pressure or density drops by a factor of e.","bag":{"kavram":["kalinlik"],"soru":[],"hesap":[]}},{"id":"layer-mean-temperature","tr":"Tabakanın ortalama sıcaklığı","en":"Layer mean temperature","kisa":"T̄","tur":"olcu","es":["ortalama tabaka sıcaklığı","mean layer temperature","Ortalama tabaka sıcaklığı","ortalama sıcaklık"],"tanim":["İki izobarik yüzey arasında yer alan hava sütununun doğal logaritmik basınç ağırlıklı ortalama sıcaklığıdır.","Sembolü T̄ olup birimi Kelvin cinsinden tanımlanır ve sinoptik hesaplamalarda tipik 240 K ile 290 K aralığında kalır.","Hipsometrik denklemde iki seviye arasındaki jeopotansiyel kalınlığı doğrudan belirleyen temel termodinamik değişkendir."],"tanim_en":"The log-pressure-weighted average temperature of an atmospheric layer between two isobaric levels.","bag":{"kavram":["kalinlik"],"soru":["S5","S10"],"hesap":["kalinlik"]}},{"id":"sym-rd","tr":"Kuru hava gaz sabiti","en":"Gas constant for dry air","kisa":"R_d","tur":"olcu","es":["dry air gas constant symbol","Rd","kuru hava sabiti"],"tanim":["Kuru havanın termodinamik ve hidrostatik denklemlerinde kullanılan özgül gaz sabiti.","Standart atmosfer hesaplarında 287 J kg⁻¹ K⁻¹ olarak alınır; Rd/g oranı yaklaşık 29,3 m/K değerine karşılık gelir.","Hipsometrik denklemde iki basınç seviyesi arasındaki tabaka kalınlığını tabakanın ortalama sıcaklığına bağlar."],"tanim_en":"Specific gas constant for dry atmospheric air, equal to 287 J kg⁻¹ K⁻¹ in meteorological thermodynamic equations.","bag":{"kavram":["kalinlik","jeopotansiyel"],"soru":["S5"],"hesap":["kalinlik"]}},{"id":"thickness-gradient","tr":"Kalınlık gradyanı","en":"Thickness gradient","kisa":"∇(ΔZ)","tur":"olcu","es":["Tabaka kalınlık gradyanı","kalınlık eğimi","gradient of thickness"],"tanim":["İki sabit basınç yüzeyi arasındaki jeopotansiyel kalınlığın yatay yöndeki değişim hızı ve yönelimi.","Kalınlık haritalarında kalınlık çizgilerinin sıklaştığı hatlarda büyüklüğü artar ve ortalama sıcaklık gradyanına karşılık gelir.","Termal rüzgârın şiddetini belirler; jeostrofik termal rüzgâr kalınlık gradyanına dik ve kalınlık çizgilerine paralel biçimde eser."],"tanim_en":"Horizontal rate of change of geopotential thickness between two isobaric levels, proportional to the thermal wind.","bag":{"kavram":["kalinlik","termal-ruzgar"],"soru":[],"hesap":["kalinlik"]}},{"id":"thickness-line-540-dam","tr":"540 dam kalınlık çizgisi","en":"540 dam thickness line","kisa":"540 dam","tur":"yontem","es":["yağmur/kar sınırı","540 line","rain-snow line","540 barajı","rain-snow limit","540 thickness line"],"tanim":["1000–500 hPa tabakası arasında jeopotansiyel kalınlığın 540 dekametreye karşılık geldiği izoplet.","Hipsometrik denkleme göre tabakanın ortalama sıcaklığı ≈ 266 K (≈ −7 °C) eder; bu durumda yer yakınındaki sıcaklık çoğu zaman 0 °C dolayındadır.","Sinoptik harita analizinde ve hava tahmininde yağmur ile kar yağışı türünü kabaca ayıran pratik sınır çizgisi kabul edilir."],"tanim_en":"The 540 dam isopleth of 1000–500 hPa thickness used as a practical threshold between rain and snow.","bag":{"kavram":["kalinlik"],"soru":[],"hesap":["kalinlik"]}},{"id":"unit-per-second","tr":"Bölü saniye","en":"Per second","kisa":"s⁻¹","tur":"birim","es":["1/s","s⁻¹","vortisite birimi","reciprocal second"],"tanim":["Sinoptik meteorolojide açısal hız, frekans, vortisite, diverjans ve rüzgâr kesmesi türevlerinin SI birimi.","Sembolü s⁻¹ olarak yazılır; Dünya'nın açısal hızı Ω ve Coriolis parametresi f bu birimle ifade edilir.","Sinoptik ölçekli sistemlerde göreli vortisite ve yatay diverjans büyüklükleri tipik olarak 10⁻⁵ s⁻¹ mertebesinde yer alır."],"tanim_en":"SI unit of frequency, angular velocity, vorticity, divergence, and wind shear, symbolized as s⁻¹.","bag":{"kavram":["merkez","coriolis","yakinsama"],"soru":["S6"],"hesap":["adveksiyon"]}},{"id":"forecast-chart","tr":"Tahmin haritası","en":"forecast chart","kisa":"Fx","tur":"cihaz","es":["tahmin kartı","prognostic chart","prognostik kart","model tahmin kartı"],"tanim":["Gelecekteki belirli bir geçerlilik anı için atmosferik parametrelerin beklenen dağılımını gösteren meteorolojik kart.","Sayısal hava tahmin modelleri çıktılarından üretilir; yer seviyesi ve standart izobarik yüzeyler için izobar, kontur ve cephe öngörülerini içerir.","Operasyonel hava tahmininde hava sistemlerinin gelişimini ve hareket yönünü önceden belirlemek amacıyla kullanılır."],"tanim_en":"A meteorological chart showing the expected distribution of atmospheric parameters for a specified future valid time.","bag":{"kavram":["merkez"],"soru":[],"hesap":[]}},{"id":"anticyclone","tr":"Antisiklon","en":"Anticyclone","kisa":"H","tur":"kavram","es":["yüksek basınç alanı","high pressure system","Yüksek basınç sistemi","Yüksek","Türkçe yüksek sembolü","Y harfi"],"tanim":["Çevresine göre merkezinde basıncın en yüksek olduğu, kapalı izobarlarla çevrili büyük ölçekli atmosferik sistem.","Kuzey Yarımküre'de rüzgâr merkez çevresinde saat yönünde döner; haritada H veya Türkçe kartlarda Y harfiyle gösterilir.","Merkez bölgesinde alçalıcı hava hareketleri hâkim olduğundan açık, bulutsuz ve kararlı hava koşulları oluşturur."],"tanim_en":"An atmospheric system characterized by high central pressure enclosed by isobars, with clockwise circulation in the Northern Hemisphere and widespread subsidence.","bag":{"kavram":["merkez"],"soru":["S1","S2","S3","S5","S6","S7"],"hesap":[]}},{"id":"arctic-air-mass","tr":"Arktik hava kütlesi","en":"Arctic air mass","kisa":"A","tur":"kavram","es":["Arktik hava","arctic air"],"tanim":["Kutup çevresindeki kar ve buzla kaplı bölge üzerinde uzun süre kalarak çok soğuk ve kuru özellik kazanan hava kütlesi.","Hava kütlesi sınıflandırmasında A kısaltmasıyla gösterilir; çok düşük sıcaklık ve düşük mutlak nem taşır.","Orta enlemlere doğru indiğinde polar cephenin kuzeyinde dondurucu soğuk dalgalarına ortam hazırlar."],"tanim_en":"A very cold, dry air mass that forms over the snow- and ice-covered Arctic; designated A.","bag":{"kavram":["merkez"],"soru":["S2","S3","S5","S7","S9","S10"],"hesap":[]}},{"id":"closed-low","tr":"Kapalı alçak","en":"Closed low","kisa":"","tur":"kavram","es":["kapalı siklon","closed cyclonic circulation","kapalı konturlu alçak","closed contour low"],"tanim":["Üst seviye veya yer haritasında en az bir kapalı izobar ya da kontur çizgisiyle tamamen çevrelenmiş alçak basınç alanı.","500 hPa seviyesinde merkeze doğru azalan kapalı izohipslerle belirginleşir ve çevresinde siklonik dolaşım barındırır.","Açık bir troftan farklı olarak bağımsız bir dolaşım merkezi kurar; trof ekseni bu kapalı merkeze bağlı uzanabilir."],"tanim_en":"A low-pressure area enclosed by one or more closed height contours or isobars with an independent cyclonic circulation center.","bag":{"kavram":["merkez","barotropik","trof-sirt"],"soru":["S3","S9"],"hesap":[]}},{"id":"cut-off-low","tr":"Kesik alçak","en":"Cut-off low","kisa":"COL","tur":"kavram","es":["kopmuş alçak","kopuk alçak","cut-off cyclone","cut-off alçak","kopan alçak"],"tanim":["Ana batı rüzgârları akımından kopup ekvatora doğru yer değiştiren soğuk çekirdekli üst seviye alçağı.","Eşdeğer barotropik yapıya yaklaştığında izotermler konturlara paralel duruma gelir; sıcaklık adveksiyonu sıfırlanır ve sistem düşey eksenli hale döner.","Ana akıştan tecrit edildiği için çok yavaş ilerler ya da günlerce yerinde sayarak bulunduğu bölgede uzun süreli kararsızlık ve yağış üretir."],"tanim_en":"Cold low which has been displaced equatorward out of the basic westerly current in which it was located.","bag":{"kavram":["merkez","barotropik","cekirdek"],"soru":["S9"],"hesap":[]}},{"id":"cyclone","tr":"Siklon","en":"Cyclone","kisa":"L","tur":"kavram","es":["alçak basınç sistemi","depression","Alçak basınç sistemi","Depresyon","Depression"],"tanim":["Çevresine göre merkezinde basıncın daha düşük kaldığı, kapalı izobarlarla sınırlanmış atmosferik alçak basınç sistemi.","Kuzey Yarımküre'de rüzgâr merkez çevresinde saat yönünün tersine döner; haritada L veya Türkçe kartlarda A harfiyle gösterilir.","Yer seviyesinde merkeze doğru yakınsama ve buna bağlı yükselici düşey hareketlerle bulut ve yağış üretir."],"tanim_en":"An atmospheric area of low pressure enclosed by isobars, with counterclockwise circulation in the Northern Hemisphere and organized ascending motion.","bag":{"kavram":["merkez"],"soru":["S2","S3"],"hesap":[]}},{"id":"frontal-low","tr":"Cepheli alçak","en":"frontal low","kisa":"","tur":"kavram","es":["cepheli siklon","frontal depression","frontal cyclone","dalga siklonu"],"tanim":["Farklı hava kütlelerini ayıran cephe kuşağı üzerinde dalga şeklinde gelişen alçak basınç sistemi.","Yer haritalarında kapalı izobarlar ile merkezden çevreye uzanan cephe sembolleriyle gösterilir.","Gelişimi sırasında sıcak sektör, soğuk ve sıcak cephe yapısıyla geniş yağış alanları üretir."],"tanim_en":"A low-pressure system that develops as a wave on a frontal zone separating contrasting air masses.","bag":{"kavram":["merkez","cephe-olcutleri"],"soru":[],"hesap":[]}},{"id":"icelandic-low","tr":"İzlanda alçağı","en":"Icelandic Low","kisa":"","tur":"kavram","es":["İzlanda yarı-daimi alçağı","İzlanda depresyonu"],"tanim":["Kuzey Atlantik üzerinde İzlanda civarında kışın belirginleşen yarı-daimi alçak basınç merkezi.","Soğuk çekirdekli bir sistem olup merkezdeki kalınlık çevreye göre daha azdır; yukarı seviyede daha da derinleşir.","Gezici siklonların ve cephe sistemlerinin geçiş yolu olarak Avrupa ile Akdeniz hava düzenini etkiler."],"tanim_en":"A semi-permanent subpolar low-pressure centre over the North Atlantic characterized by a cold core and deep upper-level trough.","bag":{"kavram":["merkez"],"soru":["S5"],"hesap":[]}},{"id":"siberian-anticyclone","tr":"Sibirya antisiklonu","en":"Siberian Anticyclone","kisa":"","tur":"kavram","es":["Sibirya yükseği","Sibirya yüksek basıncı","Siberian High"],"tanim":["Kış mevsiminde Avrasya karası üzerinde şiddetli ışınımsal soğuma sonucu gelişen yarı-daimi antisiklon.","Yerde soğuk çekirdekli yüksek basınç üretir; tabaka kalınlığı ince kaldığı için üst seviyede yerini trof veya alçağa bırakır.","Batı kolu Karadeniz ve Balkanlar üzerinden Türkiye tarafına sokularak dondurucu soğuklar ve deniz etkisi kar yağışı getirir."],"tanim_en":"An intense, shallow semi-permanent high-pressure system that forms over northern Asia during winter due to intense radiative cooling.","bag":{"kavram":["merkez"],"soru":["S5"],"hesap":[]}},{"id":"surface-low","tr":"Yer alçağı","en":"Surface low","kisa":"","tur":"kavram","es":["yüzey alçağı","surface cyclone","yerde alçak","surface low-pressure area"],"tanim":["Deniz seviyesine indirgenmiş yer haritasında çevresine göre en düşük basınç değerini taşıyan kapalı merkez.","Analiz haritalarında kapalı izobarların göbeğine L harfi ile merkezi basınç değeri konularak belirtilir.","Üst seviyedeki trof önü ıraksaması tam üzerine denk geldiğinde düşey yükselme kuvvetlenir ve merkez derinleşir."],"tanim_en":"A low-pressure centre analyzed on a surface synoptic chart enclosed by one or more isobars.","bag":{"kavram":["merkez","eksen-egim"],"soru":["S2","S3","S5","S10"],"hesap":[]}},{"id":"central-pressure","tr":"Merkezi basınç","en":"Central pressure","kisa":"p₀","tur":"olcu","es":["merkez basıncı","central surface pressure","merkezi yüzey basıncı"],"tanim":["Bir yüksek veya alçak basınç merkezinin en uç noktasında ölçülen ya da analiz edilen basınç değeri.","Hektopaskal (hPa) birimiyle verilir ve haritada merkez harfinin (L veya H) hemen yanına yazılır.","Siklonun gelişiminde merkezi basıncın zamanla düşmesi derinleşmeye, yükselmesi ise dolmaya işaret eder."],"tanim_en":"The atmospheric pressure measured or analyzed at the exact centre of a high or low pressure system.","bag":{"kavram":["merkez"],"soru":["S5"],"hesap":["cekirdek"]}},{"id":"geostrophic-vorticity","tr":"Jeostrofik girdap","en":"Geostrophic vorticity","kisa":"ζ_g","tur":"olcu","es":["jeostrofik göreli girdap","geostrophic relative vorticity","göreli jeostrofik girdap"],"tanim":["Jeostrofik rüzgâr alanının düşey eksen çevresindeki dönme miktarı.","Birim s⁻¹ olup tipik değeri ±10⁻⁵ ile 10⁻⁴ s⁻¹ aralığında değişir; Kuzey Yarımküre'de alçak için pozitif, yüksek için negatif işaret alır.","Yer haritasında basıncın Laplasyeni ile doğrudan orantılı hesaplanır ve sinoptik merkezlerin dönme şiddetini verir."],"tanim_en":"Vorticity of the geostrophic wind.","bag":{"kavram":["merkez","jeostrofik"],"soru":[],"hesap":["cekirdek"]}},{"id":"laplacian-of-pressure","tr":"Basıncın Laplasyeni","en":"Laplacian of pressure","kisa":"∇²p","tur":"olcu","es":["basınç Laplasyeni","del squared p","del kare p sembolü","del kare p","∇²p"],"tanim":["Yatay düzlemde basınç alanının ikinci uzaysal türevlerinin toplamı olan matematiksel büyüklük.","Birimi Pa m⁻²; ızgarada merkez basıncı komşuların ortalamasından çıkarılarak sonlu farkla bulunur (komşuların toplamı − 4 × merkez, bölü aralığın karesi).","Komşuların ortalaması merkezden büyükse pozitif değer alarak alçak basıncı, küçükse negatif değer alarak yüksek basıncı gösterir."],"tanim_en":"The horizontal scalar Laplacian of atmospheric pressure proportional to the geostrophic relative vorticity.","bag":{"kavram":["merkez"],"soru":[],"hesap":["cekirdek"]}},{"id":"relative-vorticity","tr":"Göreli girdap","en":"Relative vorticity","kisa":"ζ","tur":"olcu","es":["göreli vortisite","düşey girdap","siklonik girdap","cyclonic relative vorticity","siklonik vortisite","cyclonic vorticity"],"tanim":["Yeryüzüne göre tanımlı koordinat sisteminde akışın düşey eksen etrafındaki dönme hızı.","Birim s⁻¹ olup Kuzey Yarımküre'de saat yönünün tersi dönmeler pozitif, saat yönündeki dönüşler negatif kabul edilir.","Trof ekseninde en yüksek siklonik değere ulaşır; akış aşağı taşınmasıyla trof önünde PVA oluşturup yükselme hareketini ve yağışı besler."],"tanim_en":"Vorticity (usually the vertical component) measured in a system of coordinates fixed on the Earth's surface.","bag":{"kavram":["merkez","trof-sirt","trof-onu"],"soru":["S3"],"hesap":["cekirdek"]}},{"id":"cyclonic-circulation","tr":"Siklonik dolaşım","en":"Cyclonic circulation","kisa":"↺","tur":"surec","es":["siklonik akış","cyclonic flow","anticlockwise rotation","saat yönünün tersi akış","counterclockwise circulation","siklonik dönüş"],"tanim":["Bir alçak basınç alanına eşlik eden, Kuzey Yarımküre'de saat ibresinin tersine, Güney Yarımküre'de saat ibresi yönünde gelişen atmosferik dolaşım.","Buys-Ballot kuralına göre rüzgârı arkasına alan bir gözlemcinin Kuzey Yarımküre'de sol tarafında alçak basınç kalır.","Yeryüzünde sürtünme nedeniyle izobarları keserek merkeze doğru yakınsar ve bulut oluşumunu destekler."],"tanim_en":"Atmospheric circulation associated with a low-pressure area that rotates counterclockwise in the Northern Hemisphere and clockwise in the Southern Hemisphere.","bag":{"kavram":["merkez","buys-ballot"],"soru":[],"hesap":[]}},{"id":"deepening","tr":"Derinleşme","en":"Deepening","kisa":"","tur":"surec","es":["siklon derinleşmesi","alçağın derinleşmesi","deepening of a cyclone"],"tanim":["Bir alçak basınç merkezinde merkezi basıncın zamanla düşmesi ve siklonik dolaşımın kuvvetlenmesi süreci.","Sinoptik haritada izobarların sıklaşması ve istasyon modelinde basınç eğiliminin belirgin düşüş göstermesiyle kendini belli eder.","Üst seviye ıraksaması yer seviyesindeki yakınsamayı aştığında kütle boşalması yaşanır ve yer alçağı hızla derinleşir."],"tanim_en":"A drop in the central pressure of a low-pressure system that intensifies its cyclonic circulation.","bag":{"kavram":["merkez","yakinsama","trof-onu"],"soru":["S10"],"hesap":[]}},{"id":"chart-850-hpa","tr":"850 hPa kartı","en":"850 hPa chart","kisa":"850 hPa","tur":"cihaz","es":["850 hPa haritası","850 hPa synoptic chart","850 hPa seviyesi","850 mb haritası","850 hPa analiz kartı","850 hPa analysis chart"],"tanim":["Serbest atmosferin alt sınırına yakın, standart 850 hPa izobarik yüzeyindeki jeopotansiyel yükseklik konturlarını ve sıcaklık dağılımını gösteren sinoptik harita.","Standart atmosferde yaklaşık 150 dam (1,5 km) yüksekliğe karşılık gelir; konturlar ile izotermler birlikte çizilir.","Sınır tabaka sürtünmesinden arınmış alt troposfer rüzgârını, sıcaklık adveksiyonunu ve cephe uzantılarını belirlemede kullanılır."],"tanim_en":"A constant-pressure chart for the 850 hPa isobaric surface used to analyze lower-tropospheric geopotential height, temperature advection, and frontal structure.","bag":{"kavram":["okluzyon","cephe-olcutleri","jeopotansiyel"],"soru":["S6","S10"],"hesap":["kalinlik"]}},{"id":"point-of-occlusion","tr":"Oklüzyon başlangıç noktası","en":"Point of occlusion","kisa":"","tur":"kavram","es":["Üçlü nokta","Triple point","oklüzyon noktası"],"tanim":["Bir orta enlem siklonunda soğuk cephe, sıcak cephe ve oklüzyon cephesinin bir araya geldiği sinoptik kesişim noktası.","Üçlü nokta (triple point) olarak da adlandırılır; sıcak sektörün tepe noktasını oluşturur.","Yer analizinde cephe çiziminin çıpasıdır; oklüzyonlu sistemde jet ekseni bu noktanın üzerinden geçer."],"tanim_en":"The point of intersection of the warm front, cold front, and occluded front in a synoptic cyclone system.","bag":{"kavram":["okluzyon"],"soru":[],"hesap":[]}},{"id":"upper-front","tr":"Yukarı cephe","en":"Upper front","kisa":"","tur":"kavram","es":["üst seviye cephesi","yukarı sıcak cephe","yukarı soğuk cephe","upper cold front","upper warm front"],"tanim":["Yalnızca üst seviyelerde bulunan ve yer yüzeyine kadar ulaşmayan hava kütlesi sınırı.","Oklüzyon süreçlerinde sıcak veya soğuk tip oklüzyona bağlı olarak yukarıda asılı kalan sıcak veya soğuk cephe parçasıdır.","Yer haritalarında içi boş (dolu olmayan) cephe simgeleriyle, düşey kesitlerde ise sıcaklık gradyanının sıklaştığı eğik zon olarak analiz edilir."],"tanim_en":"A front that exists at higher levels in the atmosphere but does not reach the ground surface.","bag":{"kavram":["okluzyon"],"soru":[],"hesap":[]}},{"id":"unit-knot","tr":"Knot","en":"Knot","kisa":"kt","tur":"birim","es":["deniz mili bölü saat","kn","knots","deniz mili/saat","kt","nautical mile per hour"],"tanim":["Meteorolojide ve seyrüseferde rüzgâr hızını belirtmek için kullanılan, saatte bir deniz miline eşit hız birimi.","1 knot tam olarak 1,852 km/sa, yaklaşık 0,5144 m/s eder.","SYNOP iletilerinde rüzgâr göstergesi iw 3 veya 4 olduğunda kullanılır; istasyon modelinde flama 50 kt, uzun tüy 10 kt ve kısa tüy 5 kt olarak çizilir."],"tanim_en":"A unit of speed equal to one nautical mile per hour, widely adopted in synoptic meteorology for wind reporting.","bag":{"kavram":["ruzgar-yonu","izotak","jeostrofik"],"soru":["S6"],"hesap":["ruzgar","ruzgar-tuyu"]}},{"id":"lodos","tr":"Lodos","en":"south-westerly wind","kisa":"SW","tur":"kavram","es":["güneybatı rüzgârı","lodos rüzgârı","güneybatılı rüzgâr","lodos fırtınası","South-westerly gale"],"tanim":["Türkiye'de özellikle Marmara, Ege ve Akdeniz bölgelerinde güneybatı yönünden esen sıcak ve nemli rüzgâr.","Sinoptik ölçekte batıdan yaklaşan bir alçak basınç merkezinin ya da trofun ön tarafında kuvvetlenir.","Sıcak sektör içinde kuvvetli pozitif sıcaklık adveksiyonu oluşturarak kış aylarında ani sıcaklık artışına yol açar."],"tanim_en":"A warm and moist south-westerly wind blowing over Turkey and nearby waters ahead of an approaching cyclone or trough.","bag":{"kavram":["ruzgar-yonu"],"soru":["S3","S8"],"hesap":[]}},{"id":"upstream","tr":"Akışın geldiği taraf","en":"Upstream","kisa":"","tur":"kavram","es":["okun kuyruğu","upwind","akış yukarı","rüzgâr gerisi"],"tanim":["Akışkanın veya rüzgârın hareket ederek geldiği yön ve kaynak bölgesi.","Rüzgâr vektöründe okun ucunun tersine, okun kuyruk tarafına doğru gidilerek ulaşılan doğrultudur.","Sıcaklık adveksiyonu ve yarı-Lagrange izoterm taşıma analizinde hedef noktaya ulaşacak hava parselinin geriye doğru konumunu (S noktası) belirlemek için kullanılır."],"tanim_en":"The direction or region from which an air current or fluid is moving.","bag":{"kavram":["ruzgar-yonu","adveksiyon"],"soru":["S6","S7","S8"],"hesap":["izoterm-tasima"]}},{"id":"westerlies","tr":"Batı rüzgârları","en":"Westerlies","kisa":"","tur":"kavram","es":["batılı akış","westerly flow","Batı akımı","Westerly flow"],"tanim":["Her iki yarımkürede yaklaşık 35° ile 65° enlemleri arasında batıdan doğuya doğru esen hâkim rüzgâr kuşağı.","Kutup ile ekvator arasındaki meridyonal sıcaklık gradyanının ürettiği termal rüzgâr dengesiyle sürdürülür.","500 hPa haritalarında orta enlem trof ve sırt sistemlerinin genel doğuya ötelenmesini yöneten ana akımdır."],"tanim_en":"A prevailing belt of wind blowing from west to east in the middle latitudes of both hemispheres.","bag":{"kavram":["ruzgar-yonu","jeostrofik","trof-sirt"],"soru":["S3"],"hesap":[]}},{"id":"wind-direction","tr":"Rüzgâr yönü","en":"Wind direction","kisa":"dd","tur":"kod","es":["rüzgâr doğrultusu","wind heading","rüzgâr yönü dd","onlarca derece rüzgâr yönü","wind direction code figure","onluk derece rüzgâr yönü"],"tanim":["Rüzgârın estiği, yani havanın geldiği yön; coğrafi kuzeyden saat yönünde açısal derece olarak ölçülür.","SYNOP FM 12 iletisinde Nddff grubunda iki haneli dd koduyla onlarca derece cinsinden kodlanır (örneğin 20 kodu 200° anlamına gelir; sakin hava 00, değişken rüzgâr 99).","İstasyon modelinde istasyon dairesine bağlanan rüzgâr çubuğunun doğrultusuyla gösterilir; harita analizinde adveksiyon ve cephe konumlandırmasında temel girdidir."],"tanim_en":"The direction from which wind blows, measured in degrees clockwise from true north.","bag":{"kavram":["ruzgar-yonu","synop","istasyon-modeli"],"soru":["S6","S7","S8"],"hesap":["ruzgar"]}},{"id":"wind-speed","tr":"Rüzgâr hızı","en":"Wind speed","kisa":"ff","tur":"kod","es":["rüzgâr şiddeti","wind velocity magnitude","Rüzgâr şiddeti","rüzgâr sürati ff","rüzgâr hızı kod grubu","wind speed code figure"],"tanim":["Havanın birim zamanda aldığı yol; rüzgâr vektörünün büyüklüğü.","SYNOP FM 12 iletisinde Nddff grubunda iki haneli ff kodu olarak metre bölü saniye ya da knot cinsinden raporlanır; istasyon modelinde tüyler ve flamalarla çizilir.","İzobar veya kontur sıklığıyla doğru orantılıdır; sıcaklık adveksiyonunun şiddetini ve rüzgâr kesmesini belirler."],"tanim_en":"The ratio of the distance covered by moving air to the time taken to cover it, representing wind velocity magnitude.","bag":{"kavram":["ruzgar-yonu","istasyon-modeli","synop"],"soru":["S6"],"hesap":["adveksiyon","ruzgar","ruzgar-tuyu"]}},{"id":"calm-wind","tr":"Sakin rüzgâr","en":"Calm wind","kisa":"dd = 00","tur":"olcu","es":["sakin hava","calm","durgun hava"],"tanim":["Hava hareketinin bulunmadığı veya rüzgâr hızının 1 knot'tan küçük olduğu atmosferik durum.","SYNOP FM 12 kodunda dd = 00 ve ff = 00 olarak raporlanır; istasyon modelinde rüzgâr çubuğu çizilmez, istasyon dairesinin etrafına eşmerkezli ikinci bir daire çizilir.","Basınç gradyanının çok zayıf olduğu geniş antisiklon merkezlerinde veya sırt eksenlerinde görülür."],"tanim_en":"An atmospheric state characterized by absence of perceptible air motion or wind speed under one knot.","bag":{"kavram":["ruzgar-yonu"],"soru":[],"hesap":["adveksiyon"]}},{"id":"variable-wind","tr":"Değişken rüzgâr","en":"Variable wind","kisa":"dd = 99","tur":"olcu","es":["değişken yönlü rüzgâr","variable wind direction","değişken rüzgâr yönü"],"tanim":["Rüzgâr yönünün sabit bir doğrultuda kalmayıp kısa süre içinde belirgin biçimde dalgalandığı hava akımı durumu.","SYNOP raporunda Nddff grubunda dd = 99 koduyla belirtilir; rüzgâr hızının genellikle düşük olduğu hallerde ortaya çıkar.","Sinoptik harita analizinde zayıf gradyanlı antisiklon merkezlerini veya eyer noktalarını belirlemede göstergedir."],"tanim_en":"A wind that continually changes direction during the observation period.","bag":{"kavram":["ruzgar-yonu"],"soru":[],"hesap":["adveksiyon"]}},{"id":"beaufort-scale","tr":"Beaufort ölçeği","en":"Beaufort wind scale","kisa":"Beaufort","tur":"yontem","es":["bofor ölçeği","Beaufort scale","bofor skalası","Bofor ölçeği","Bofor rüzgâr cetveli","Beaufort wind force scale"],"tanim":["Rüzgâr kuvvetini deniz yüzeyi ve karadaki nesneler üzerindeki etkilerine göre 0 ile 12 arasında sayılarla belirten derecelendirme sistemi.","0 sakin havayı, 12 ise kasırga kuvvetini temsil eder; aletsiz gözlemlerde hız tahmini için kullanılır.","SYNOP iletisinde anemometre bulunmadığında rüzgâr hızını belirlemek için başvurulur ve iw rüzgâr göstericisi buna göre kodlanır."],"tanim_en":"A wind force scale based on the state of the sea and land effects, expressed in numbers from 0 to 12.","bag":{"kavram":["ruzgar-yonu","synop"],"soru":[],"hesap":["adveksiyon"]}},{"id":"boundary-layer","tr":"Sınır tabaka","en":"Boundary layer","kisa":"PBL","tur":"kavram","es":["atmosferik sınır tabaka","gezegensel sınır tabaka","PBL","sürtünme tabakası"],"tanim":["Yeryüzü sürtünmesi ve yüzey ısı transferinin doğrudan hissedildiği troposferin en alt katmanı.","Kalınlığı gün içi ısınmaya ve kararlılığa bağlı olarak değişmekle birlikte sinoptik ölçekte ortalama yerden ≈ 1 km yüksekliğe kadar uzandığı kabul edilir.","Bu tabakada rüzgâr yüzey sürtünmesi nedeniyle jeostrofik dengeden sapar ve izobarları alçak basınca doğru keser."],"tanim_en":"The lowest layer of the troposphere directly affected by friction and surface heating.","bag":{"kavram":["surtunme"],"soru":["S2"],"hesap":[]}},{"id":"free-atmosphere","tr":"Serbest atmosfer","en":"Free atmosphere","kisa":"","tur":"kavram","es":["sürtünmesiz atmosfer","frictionless atmosphere","Sürtünmesiz atmosfer"],"tanim":["Yeryüzü sürtünmesinin doğrudan etkisinden uzak, sınır tabakanın üzerinde kalan atmosfer tabakası.","Genellikle yer seviyesinden yaklaşık 1 km yükseklikten başlayarak troposferin üst sınırına kadar uzanır.","Sürtünme ihmal edildiğinden sinoptik ölçekli akış jeostrofik veya gradyan rüzgâr dengesine uyar ve izohipslere tam paralel akar."],"tanim_en":"The portion of the atmosphere above the boundary layer where the effect of surface friction is negligible.","bag":{"kavram":["surtunme","jeostrofik"],"soru":[],"hesap":[]}},{"id":"surface-wind","tr":"Yer rüzgârı","en":"Surface wind","kisa":"V","tur":"olcu","es":["yüzey rüzgârı","anemometer wind","sürtünmeli rüzgâr"],"tanim":["Standart olarak yer seviyesinden 10 m yükseklikte ölçülen ya da tahmin edilen yatay hava hareketi.","Yüzey sürtünmesi nedeniyle jeostrofik rüzgârdan daha yavaştır (tipik olarak jeostrofik hızın %60–90'ı) ve izobarları alçak basınca doğru keser.","Sinoptik yer haritalarında istasyon modeline rüzgâr oku ile işlenir; kesme açısı deniz üzerinde 10–20°, kara üzerinde 25–40° civarındadır."],"tanim_en":"The wind blowing at the standard level of 10 metres above the surface, retarded and deflected by friction toward lower pressure.","bag":{"kavram":["surtunme","ruzgar-yonu"],"soru":["S2","S7"],"hesap":["adveksiyon"]}},{"id":"ekman-pumping","tr":"Ekman pompalaması","en":"Ekman pumping","kisa":"","tur":"surec","es":["Ekman emmesi","Ekman suction","sürtünmeli yükselme"],"tanim":["Sınır tabakadaki sürtünmeli akışın alçak basınç merkezine kütle taşımasıyla sınır tabaka tepesinde meydana gelen düşey hareket süreci.","Siklonik dolaşımda taban yakınsaması yukarı doğru yükselmeye (w > 0), antisiklonik dolaşımda ise taban ıraksaması çökmeye yol açar.","Orta enlem siklonlarının zayıflamasında ve sınır tabaka ile serbest atmosfer arasındaki düşey kütle aktarımında önemli rol oynar."],"tanim_en":"Vertical motion at the top of the boundary layer produced by frictionally driven convergence or divergence.","bag":{"kavram":["surtunme","yakinsama"],"soru":[],"hesap":[]}},{"id":"ekman-spiral","tr":"Ekman sarmalı","en":"Ekman spiral","kisa":"","tur":"yontem","es":["Ekman sarmal akışı","Ekman velocity spiral"],"tanim":["Sürtünme tabakasında rüzgâr vektörünün yükseklikle değişimini kutupsal diyagram üzerinde gösteren ve sarmal biçim alan kuramsal model.","Yerden yükseldikçe yüzey sürtünmesinin etkisi zayıflar; rüzgâr hızı artarken yön Kuzey Yarımküre'de sağa dönerek serbest atmosferdeki jeostrofik rüzgârla hizalanır.","Sınır tabakada rüzgâr yönünün ve kesme açısının yükseklik profilini anlamada ve parametreleştirmede temel alınır."],"tanim_en":"A polar diagram representation of the variation of the wind vector with height in the friction layer taking the form of a spiral.","bag":{"kavram":["surtunme"],"soru":[],"hesap":[]}},{"id":"unit-utc","tr":"Eşgüdümlü Evrensel Zaman","en":"Coordinated Universal Time","kisa":"UTC","tur":"birim","es":["UTC","Z","evrensel zaman","Evrensel Zaman","GMT","Zaman standardı"],"tanim":["Dünya genelinde sinoptik meteorolojik gözlemlerin ve harita analizlerinin eş zamanlı yapılmasını sağlayan uluslararası standart zaman referansı.","SYNOP raporunda YYGGiw grubundaki GG hanesi ile tam saat olarak belirtilir.","Ana sinoptik saatler olan 00, 06, 12 ve 18 UTC ile ara sinoptik saatler bu standarda göre belirlenir."],"tanim_en":"The international standard time scale to synchronize global meteorological observations and synoptic weather charts.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"anemometer","tr":"Anemometre","en":"anemometer","kisa":"","tur":"cihaz","es":["rüzgâr ölçer","anemograf","wind gauge","rüzgârölçer","wind sensor","rüzgâr aleti"],"tanim":["Rüzgâr hızını veya rüzgâr hızı ile yönünü ölçen alet.","Meteoroloji istasyonlarında standart olarak yer seviyesinden 10 m yükseklikteki açık alana yerleştirilir.","SYNOP iletisinde rüzgârın aletle ölçüldüğünü belirtmek için iw rüzgâr göstericisi m/s için 1, knot için 4 olarak kodlanır."],"tanim_en":"An instrument designed to measure wind speed or wind speed and direction.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"barograph","tr":"Barograf","en":"Barograph","kisa":"","tur":"cihaz","es":["yazıcı barometre","recording barometer"],"tanim":["Atmosfer basıncını dönen bir tambur üzerindeki çizelgeye zamanın fonksiyonu olarak sürekli çizen barometre.","SYNOP raporundaki 5appp grubunda son 3 saatlik basınç eğilim karakteristiğinin (a kodu) ve değişim miktarının belirlenmesinde kullanılır.","Basınç profilindeki ani kırılmalar soğuk cephe geçişlerinin ve mezoölçekli sistemlerin tespitinde önemli rol oynar."],"tanim_en":"A barometer equipped with a mechanism to plot a continuous trace of atmospheric pressure.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"main-synoptic-hour","tr":"Ana sinoptik saatler","en":"main synoptic hours","kisa":"00, 06, 12, 18 UTC","tur":"kavram","es":["ana sinoptik saat","standard synoptic observation","ana sinoptik zaman","standard synoptic observation time","Ana Sinoptik Saat","Main synoptic hour"],"tanim":["Dünya genelinde yüzey ve yüksek atmosfer rasatlarının eş zamanlı olarak yapıldığı temel sinoptik gözlem vakitleri.","WMO standardına göre 00, 06, 12 ve 18 UTC olmak üzere günde dört ana gözlem vaktinden oluşur.","Sinoptik harita analizleri ve sayısal tahmin modellerinin başlangıç alanı öncelikle bu saatlerde toplanan gözlemlerle kurulur."],"tanim_en":"Main synoptic hours are the standard times of 00, 06, 12, and 18 UTC at which surface and upper-air meteorological observations are taken globally.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"manned-station","tr":"İnsanlı istasyon","en":"manned station","kisa":"","tur":"kavram","es":["insanlı meteoroloji istasyonu","manned weather station","Manuel istasyon","manuel gözlem istasyonu","İnsanlı hava gözlem istasyonu","Manned weather station"],"tanim":["Meteorolojik gözlemlerin insan gözlemci tarafından yapıldığı veya doğrudan denetlendiği kara meteoroloji istasyonu.","SYNOP iletisinde iRixhVV grubundaki ix göstergesiyle belirtilir; ix değeri 1, 2 veya 3 kod rakamını alır.","Bulut türleri, kapalılık miktarı ve geçmiş hava gibi görsel gözlemlerin güvenilir şekilde raporlanmasını sağlar."],"tanim_en":"A manned station is a weather observing facility where meteorological observations are conducted or supervised by a human observer.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"cloud-base-height","tr":"Bulut tabanı yüksekliği","en":"Cloud-base height","kisa":"h","tur":"kod","es":["bulut tabanı","bulut taban mesafesi","en alçak bulut tabanı yüksekliği","lowest cloud base height","cloud base"],"tanim":["Gözlem yerinin zemin seviyesinden en alçak bulut tabanına kadar olan düşey uzaklık.","SYNOP Kısım 1 içindeki iRixhVV grubunda h harfiyle tek haneli kod rakamı olarak WMO Tablo 1600 uyarınca kodlanır (örneğin 0 rakamı 0–50 m, 5 rakamı 600–1000 m aralığını verir).","İstasyon modelinde bulut kapalılığı dairesinin altına yazılır; sıcak cephe yaklaşımında ve havacılık işletiminde kritik bir parametredir."],"tanim_en":"Height of the base of the lowest cloud is the vertical distance between the ground surface and the base of the lowest cloud layer.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["gorus-bulut"]}},{"id":"code-ch-high-cloud-genus","tr":"Yüksek bulut türü","en":"type of high cloud","kisa":"CH","tur":"kod","es":["clouds of genera Ci Cc Cs","CH","yüksek bulut formu","WMO tablo 0509","yüksek bulut","CH bulut türü"],"tanim":["Cirrus, Cirrocumulus ve Cirrostratus cinslerinden oluşan yüksek seviye bulutlarının türünü ve gökyüzündeki gelişimini belirten kod simgesi.","SYNOP Kısım 1 içindeki 8NhCLCMCH grubunun beşinci hanesinde WMO Tablo 0509 uyarınca 0 ile 9 arasında tek rakamla bildirilir.","İstasyon modelinde merkez dairesinin en üstüne sembolle çizilir; yaklaşan sıcak cephenin ilk sinoptik işareti olan sirrusları belirlemede kullanılır."],"tanim_en":"Type of high cloud is a meteorological code indicator specifying the genus and sky evolution of cirrus, cirrocumulus, or cirrostratus clouds.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-cl-low-cloud-genus","tr":"Alçak bulut türü","en":"type of low cloud","kisa":"CL","tur":"kod","es":["clouds of genera Sc St Cu Cb","CL","alçak bulut formu","WMO tablo 0513","alçak bulut","CL bulut türü"],"tanim":["Stratocumulus, Stratus, Cumulus ve Cumulonimbus cinslerindeki alçak seviye bulutlarının tür ve biçimini belirten kod simgesi.","SYNOP Kısım 1 içindeki 8NhCLCMCH grubunun üçüncü hanesinde WMO Tablo 0513 uyarınca 0 ile 9 arasında tek rakamla gösterilir.","İstasyon modelinde merkez dairesinin altına çizilir; soğuk cephe geçişleri ile konvektif kararsızlığın izlenmesinde temel veri sağlar."],"tanim_en":"Type of low cloud is a meteorological code indicator specifying the genus and structure of stratocumulus, stratus, cumulus, or cumulonimbus clouds.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-cm-medium-cloud-genus","tr":"Orta bulut türü","en":"type of medium cloud","kisa":"CM","tur":"kod","es":["orta bulutlar","mid-level clouds","CM bulutları","clouds of genera Ac As Ns","CM","orta bulut formu"],"tanim":["Altocumulus, Altostratus ve Nimbostratus cinslerindeki orta seviye bulutlarının biçim ve dağılımını belirten kod simgesi.","SYNOP Kısım 1 içindeki 8NhCLCMCH grubunun dördüncü hanesinde WMO Tablo 0515 uyarınca 0 ile 9 arasında tek rakamla kodlanır.","İstasyon modelinde merkez dairesinin üst tarafına çizilir; sıcak cephe önündeki tabakalı bulut örtüsünü ve orta seviye kararsızlığını gösterir."],"tanim_en":"Type of medium cloud is a meteorological code indicator defining the genus and physical appearance of altocumulus, altostratus, or nimbostratus clouds.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-1snttt","tr":"Sıcaklık grubu","en":"Air temperature group","kisa":"1snTTT","tur":"kod","es":["hava sıcaklığı grubu","1snTTT group","aktüel sıcaklık grubu","1 grubu","TTT","yüzey sıcaklığı grubu"],"tanim":["SYNOP Kısım 1 içinde kuru termometre hava sıcaklığını bildiren beş haneli standart veri grubu.","1 tanıtıcı rakamıyla başlar; sn işareti (0 pozitif, 1 negatif) ve TTT onda bir santigrat derece cinsinden sıcaklık büyüklüğünü verir.","İstasyon modelinde merkez dairesinin sol üst köşesine yerleştirilir; yer haritasında izoterm analizi ve cephe kuşağı tespitinde temel girdidir."],"tanim_en":"The air temperature group is a five-figure SYNOP code group reporting surface air temperature to the nearest tenth of a degree Celsius.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"code-group-2sntdtdtd","tr":"Çiy noktası sıcaklığı grubu","en":"Dew-point temperature group","kisa":"2snTdTdTd","tur":"kod","es":["çiğ noktası grubu","2snTdTdTd group","çiy noktası grubu","2 grubu","TdTdTd","çiy noktası sıcaklık grubu"],"tanim":["SYNOP Kısım 1 içinde havadaki nem oranını belirleyen çiy noktası sıcaklığını bildiren beş haneli standart veri grubu.","2 tanıtıcı rakamıyla başlar; sn işareti (0 pozitif, 1 negatif) ve TdTdTd onda bir santigrat derece cinsinden çiy noktası değerini verir.","İstasyon modelinde merkez dairesinin sol alt köşesine yazılır; hava sıcaklığı ile farkı alınarak çiy noktası açığı ve yoğuşma potansiyeli bulunur."],"tanim_en":"The dew-point temperature group is a five-figure SYNOP code group reporting surface dew-point temperature to the nearest tenth of a degree Celsius.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"code-group-3popopopo","tr":"İstasyon basıncı grubu","en":"Station actual pressure group","kisa":"3PoPoPoPo","tur":"kod","es":["3PoPoPoPo group","istasyon seviyesi basınç grubu","QFE grubu","aktüel basınç grubu","station pressure group"],"tanim":["SYNOP Kısım 1 içinde yer alan, istasyonun barometre seviyesinde ölçülen aktüel atmosfer basıncını bildiren 5 haneli kod grubudur.","3 gösterge rakamıyla başlar; PoPoPoPo haneleri basıncı onda bir hPa biriminde verir ve 1000 hPa üzerindeki değerlerde baştaki binler basamağı yazılmaz.","Deniz seviyesine indirgenmemiş, barometre seviyesindeki istasyon basıncıdır; yüksek istasyonlarda 4PPPP yerine 4a₃hhh verildiğinde basınç bilgisi bu grupta kalır."],"tanim_en":"A SYNOP code group that reports the actual atmospheric pressure measured at station level in tenths of a hectopascal.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-group-4pppp","tr":"Deniz seviyesi basıncı grubu","en":"4PPPP group","kisa":"4PPPP","tur":"kod","es":["deniz seviyesi basınç grubu","MSLP group","MSLP grubu","QFF grubu","indirgenmiş basınç grubu","4 grubu"],"tanim":["SYNOP Kısım 1 içinde yer alan, istasyon basıncının ortalama deniz seviyesine indirgenmiş değerini onda bir hPa cinsinden bildiren kod grubudur.","4 gösterge rakamıyla başlar; PPPP binler hanesi atılmış basınçtır (onda bir hPa): ilk rakam 9 ise değer 9xx,x hPa (9950 → 995,0), değilse 10xx,x hPa olur (0268 → 1026,8); kitapta bu okuma «9/10 kuralı» diye geçer.","Yer haritası analizinde izobarların çizilmesinde ve yüksek ya da alçak basınç merkezlerinin belirlenmesinde temel alınan ana veridir."],"tanim_en":"A SYNOP code group that reports the atmospheric pressure reduced to mean sea level in tenths of a hectopascal.","bag":{"kavram":["synop","izobar","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-5appp","tr":"Basınç eğilimi grubu","en":"Pressure tendency and characteristic group","kisa":"5appp","tur":"kod","es":["basınç tandans grubu","5appp group","üç saatlik basınç değişimi grubu","5 grubu","barometrik eğilim grubu","pressure tendency and change"],"tanim":["SYNOP Kısım 1 içinde yer alan, son 3 saatteki net basınç değişim miktarını ve barograf eğrisinin biçimini bildiren kod grubudur.","5 gösterge rakamıyla başlar; a simgesi eğilim karakteristiğini (0–8), ppp ise 3 saatlik basınç değişim miktarını onda bir hPa olarak belirtir.","Yer analizinde izallobar çizgilerinin çizilmesini, cephe geçişlerinin tespitini ve basınç sistemlerinin hareket yönünü belirlemeyi sağlar."],"tanim_en":"A SYNOP code group that reports the characteristic and amount of atmospheric pressure change over the preceding three hours.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-6rrrtr","tr":"Yağış grubu","en":"Precipitation amount and duration group","kisa":"6RRRtR","tur":"kod","es":["6RRRtR group","6 grubu","yağış veri grubu","precipitation data group","6RRRtR grubu","precipitation group"],"tanim":["SYNOP Kısım 1 veya Kısım 3 içinde yer alan, ölçülen yağış miktarını ve bu yağışın kapsadığı referans süresini bildiren kod grubudur.","6 gösterge rakamıyla başlar; RRR haneleri milimetre cinsinden yağış miktarını, tR hanesi ise yağışın ölçüldüğü süreyi belirtir.","Kitaptaki ulusal uygulamada ana sinoptik saatlerde yağış olmasa da 60001 biçiminde (RRR = 000, «yağış yok») yazılır; WMO düzeninde yağış yoksa iR = 3 seçilip grup atlanabilir. Yağışlı alanların ve cephesel yağış sınırlarının belirlenmesinde kullanılır."],"tanim_en":"A SYNOP code group that reports the amount of precipitation accumulated during a specified reference period.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-7www1w2","tr":"Hava durumu grubu (şimdiki ve geçmiş hava)","en":"Present and past weather group","kisa":"7wwW1W2","tur":"kod","es":["halihazır ve geçmiş hava grubu","7wwW1W2 group","hava hadiseleri grubu","hava durumu grubu","7 grubu","hava grubu"],"tanim":["SYNOP Kısım 1 içinde yer alan, gözlem anındaki hava hadisesini ve son sinoptik aralıktaki geçmiş hava durumunu bildiren kod grubudur.","7 gösterge rakamıyla başlar; ww haneleri şimdiki hava kodunu, W1 ve W2 haneleri ise sırasıyla geçmiş havanın en belirgin hadiselerini verir.","İstasyon modelinde sembollerle yer alır; cephe geçişlerinin, sis, sağanak, kar ve oraj gibi sinoptik hava olaylarının harita üzerinde teşhisini sağlar."],"tanim_en":"A SYNOP code group that reports present weather phenomena at observation time and past weather conditions during the preceding period.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-8nhclcmch","tr":"Bulut grubu (miktar ve türler)","en":"Cloud genus and cloud cover group","kisa":"8NhCLCMCH","tur":"kod","es":["bulut cinsi grubu","8NhCLCMCH group","bulut formu grubu","bulut türleri grubu","8NhCLCMCH","Kısım 1 bulut grubu"],"tanim":["SYNOP Kısım 1 içinde yer alan, alçak ya da orta bulut miktarını ve troposferin üç katmanındaki baskın bulut cinslerini bildiren kod grubudur.","8 gösterge rakamıyla başlar; Nh alçak bulut kapalılığını (okta), CL alçak, CM orta, CH ise yüksek bulut türünü kodlar.","İstasyon modelinde istasyon dairesinin alt, orta ve üst çevresine sembollerle çizilerek troposferin düşey nem profili ve cephesel bulut örtüsü analiz edilir."],"tanim_en":"A SYNOP code group that reports the amount of low or middle clouds together with the predominant genera of low, middle, and high clouds.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-8nschshs","tr":"Bulut tabakası grubu (Kısım 3)","en":"Individual cloud layer group","kisa":"8NsChshs","tur":"kod","es":["bulut katmanı grubu","8NsChshs group","bulut katmanları grubu","ek bulut katı","bulut tabakası grubu","8NsChshs"],"tanim":["SYNOP Kısım 3 içinde yer alan, münferit bir bulut tabakasının miktarını, cinsini ve taban yüksekliğini bildiren kod grubudur.","8 göstergesiyle başlar; Ns tabakanın okta kapalılığını, C bulut cinsini, hshs ise taban yüksekliğini kodlar.","Birden çok katman varlığında tekrarlanarak rapor edilir; havacılık tahminlerinde ve cephesel tavan yüksekliği değişimlerinin takibinde kullanılır."],"tanim_en":"A supplementary SYNOP code group in Section 3 that reports the cloud amount, genus, and base height of an individual cloud layer.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-group-911ff","tr":"En kuvvetli hamle grubu","en":"911ff maximum gust speed group","kisa":"911ff","tur":"kod","es":["hamle hızı grubu","peak gust group","hamle grubu","en yüksek hamle grubu","911ff"],"tanim":["SYNOP Kısım 3 içinde yer alan, belirlenen referans periyodu boyunca ölçülen en yüksek rüzgâr hamlesi hızını bildiren kod grubudur.","911 göstergesiyle başlar; ff haneleri rüzgâr birimi göstergesine bağlı olarak knot ya da m/s cinsinden en büyük hamle hızını verir.","Öncesinde gelen 907tt periyoduyla birlikte okunur; şiddetli fırtınaların, konvektif hamlelerin ve cephe geçişlerindeki rüzgâr sıçramalarının analizinde kullanılır."],"tanim_en":"A SYNOP Section 3 code group that reports the maximum wind gust speed observed during a specified time period.","bag":{"kavram":["synop","ruzgar-yonu"],"soru":[],"hesap":[]}},{"id":"code-group-iiiii","tr":"İstasyon numarası grubu","en":"Station index number group","kisa":"IIiii","tur":"kod","es":["blok ve istasyon numarası","IIiii group","istasyon indisi","blok ve istasyon numarası grubu","blok ve istasyon grubu","uluslararası istasyon numarası"],"tanim":["SYNOP Kısım 0 içinde yer alan, meteoroloji istasyonunun coğrafi konumunu ve uluslararası tanıtımını belirten 5 haneli kod grubudur.","İlk iki hane (II) WMO blok numarasını, son üç hane (iii) ise o blok içindeki istasyon numarasını gösterir.","Yer haritası çiziminde gözlem verilerinin harita üzerine doğru coğrafi koordinatla yerleştirilmesini ve istasyon modelinin konumlandırılmasını sağlar."],"tanim_en":"A five-digit SYNOP code group that uniquely identifies a meteorological observing station by its WMO block and station numbers.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-irixhvv","tr":"Yağış göstericisi, istasyon tipi, bulut tabanı ve görüş grubu","en":"Precipitation weather cloud base and visibility group","kisa":"iRixhVV","tur":"kod","es":["iRixhVV grubu","iR ix h VV","görüş ve işletim grubu","yağış ve görüş grubu","göstergeler, bulut tabanı ve görüş grubu","görüş ve bulut tabanı grubu"],"tanim":["SYNOP Kısım 1 başında zorunlu olarak yer alan, yağış grubunun durumunu, istasyonun işletim türünü, en alçak bulut taban yüksekliğini ve yatay görüş mesafesini bildiren 5 haneli gruptur.","IR yağış grubunun yerini, ix istasyonun insanlı ya da otomatik yapısını, h bulut taban yüksekliğini, VV ise yatay görüşü kodlar.","Hava durumu ve yağış gruplarının rapordaki varlığını kontrol etmeyi ve yer istasyonu çevresindeki temel görüş ile tavan koşullarını haritada değerlendirmeyi sağlar."],"tanim_en":"A mandatory SYNOP code group that reports precipitation inclusion, station operation type, lowest cloud base height, and horizontal visibility.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-group-nddff","tr":"Bulut kapalılığı ve rüzgâr grubu","en":"Cloud cover wind direction and speed group","kisa":"Nddff","tur":"kod","es":["Nddff grubu","rüzgâr ve bulut grubu","rüzgâr ve kapalılık grubu","toplam bulut ve rüzgâr","bulut ve rüzgâr grubu","wind and cloud group"],"tanim":["SYNOP Kısım 1 içinde yer alan, toplam bulut kapalılığı (N), rüzgâr yönü (dd) ve rüzgâr hızını (ff) bildiren beş haneli zorunlu kod grubudur.","N sekizde bir (okta), dd onlarca derece ve ff knot veya m/s biriminden verilir; ff = 99 durumunda ardışık 00fff grubu eklenir.","İstasyon modelinin merkezindeki bulut kapalılığı simgesi ile rüzgâr çubuğunun yön ve tüy dizilimini doğrudan belirler."],"tanim_en":"A mandatory SYNOP Section 1 code group reporting total cloud cover in oktas along with wind direction and speed.","bag":{"kavram":["synop","ruzgar-yonu","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-group-yyggiw","tr":"Gün, saat ve rüzgâr birimi grubu","en":"YYGGiw group","kisa":"YYGGiw","tur":"kod","es":["gün saat ve rüzgâr göstergesi grubu","time and wind indicator group","zaman ve rüzgâr grubu","sinoptik zaman grubu","zaman ve rüzgâr göstergesi grubu","zaman ve rüzgâr gösterici grubu"],"tanim":["SYNOP raporunun Kısım 0 tanımlama bölümünde yer alan, gözlemin ayın hangi gününde (YY), hangi saatte UTC olarak (GG) yapıldığını ve rüzgâr ölçüm yöntemini (iw) bildiren kod grubudur.","İlk iki hane ayın gününü, sonraki iki hane gözlem saatini (UTC; ana sinoptik saatlerde 00, 06, 12, 18), son hane ise knot veya m/s birimini gösterir.","Sinoptik harita analizinde gözlemin zaman geçerliliğini ve rüzgâr hızının doğru birimle değerlendirilmesini sağlar."],"tanim_en":"A SYNOP Section 0 group specifying the day of the month, observation hour in UTC, and the wind speed measurement indicator.","bag":{"kavram":["synop","ruzgar-yonu"],"soru":[],"hesap":[]}},{"id":"code-ir-precipitation-indicator","tr":"Yağış verisi göstericisi","en":"Precipitation data indicator","kisa":"iR","tur":"kod","es":["yağış bilgisi göstericisi","precipitation indicator","iR","WMO tablo 1819","yağış göstergesi","yağış grubu göstergesi"],"tanim":["SYNOP Kısım 1'in ilk grubu olan iRixhVV içinde yer alan ve yağış grubunun rapordaki durumunu bildiren tek haneli WMO Kod Tablosu 1819 göstericisidir.","0 ile 4 arasında değer alır; 1 değeri yağış grubunun Kısım 1 içinde olduğunu, 3 yağış olmadığını, 4 ise ölçüm yapılmadığını bildirir.","Harita analistine iletide 6RRRtR yağış grubunun yer alıp almadığını bildirerek yağış verisinin varlığını denetler."],"tanim_en":"A single-digit code figure in SYNOP reporting whether the precipitation group is included in the message or omitted according to WMO Code Table 1819.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-ix","tr":"İstasyon tipi göstericisi","en":"Station operation and weather group indicator","kisa":"ix","tur":"kod","es":["otomatik/insanlı istasyon göstergesi","type of station indicator","station mode indicator","otomatik insanlı istasyon göstergesi","İnsanlı otomatik istasyon kodu","WMO Table ix"],"tanim":["SYNOP Kısım 1'deki iRixhVV grubunun ikinci hanesi olan, istasyonun insanlı veya otomatik işletim türünü ve hava hadisesi grubunun durumunu belirten WMO Kod Tablosu 1860 göstericisidir.","1–3 arası değerler insanlı istasyonu, 4–7 arası değerler otomatik hava gözlem istasyonunu gösterir.","Ix = 2 veya 5 olduğunda raporda bildirilecek önemli hava olayı bulunmadığı anlaşılır ve 7wwW1W2 grubu bültende yer almaz."],"tanim_en":"A single-digit indicator in SYNOP specifying whether the station is manned or automatic and whether the present and past weather group is included.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-nh-low-middle-cloud-amount","tr":"Alçak (yoksa orta) bulut miktarı","en":"Amount of low or middle clouds code","kisa":"Nh","tur":"kod","es":["alçak bulut kapalılığı","cloud amount of low clouds","Nh","alçak bulut miktarı","low cloud amount","taban bulut kapalılığı"],"tanim":["SYNOP Kısım 1 içindeki 8NhCLCMCH bulut grubunun ikinci hanesinde yer alan, gözlemlenen tüm alçak bulutların (alçak bulut yoksa orta bulutların) miktarını bildiren kod rakamıdır.","WMO Kod Tablosu 2700 uyarınca 0 ile 8 okta arasında değer alır; gökyüzü kapalı olduğunda 8, sis nedeniyle görülemediğinde 9 yazılır.","İstasyon modelinde alçak bulut cinsinin yanına işlenen kapalılığı belirleyerek tavan yüksekliği analizine zemin oluşturur."],"tanim_en":"A single-digit code in SYNOP reporting the cloud amount of all low clouds present or middle clouds if no low clouds exist.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-plotted-pressure-ppp","tr":"İstasyon modelindeki üç haneli basınç","en":"Three-digit plotted pressure","kisa":"PPP","tur":"kod","es":["modeldeki üç hane","çizilen basınç","istasyon modelinde basınç","basınç açma kuralı","4PPPP çözüm kuralı","9/10 basınç açma kuralı"],"tanim":["Yer sinoptik haritasında istasyon modelinin sağ üst köşesine yazılan, deniz seviyesi basıncının onlar, birler ve onda birler basamağını gösteren üç haneli sayıdır.","Baştaki 9 veya 10 rakamları ile ondalık virgül yazılmaz; 500 ve üzeri değerlerin başına 9, 500 altındaki değerlerin başına 10 getirilerek onda bir hPa duyarlığında okunur.","İzobar analizinde iki istasyon arasındaki doğrusal basınç enterpolasyonunu kurmak için doğrudan bu değerden yararlanılır."],"tanim_en":"A three-digit number plotted at the upper right of a station model representing mean sea-level pressure truncated to tens, units, and tenths of a hectopascal.","bag":{"kavram":["synop","istasyon-modeli","izobar"],"soru":[],"hesap":["basinc-kodu"]}},{"id":"code-section-0","tr":"Kısım 0","en":"Section 0","kisa":"","tur":"kod","es":["istasyon tanıtım kısmı","identification section","tanıtım verileri","rapor tanımlama grubu","header section","Tanımlama bölümü"],"tanim":["SYNOP raporunun en başında yer alan, rapor tanıtıcısı (AAXX), gözlem zamanı (YYGGiw) ve istasyon tanıtım numarasını (IIiii) bildiren kimlik bölümüdür.","Bölüm belirteç rakamı içermez; doğrudan iletinin başındaki ilk üç grup olarak bültende bulunur.","Sinoptik harita çiziminde verinin hangi coğrafi konuma, hangi güne ve hangi sinoptik saate ait olduğunu saptar."],"tanim_en":"The identification section of a SYNOP report containing the report type, observation time, wind indicator, and station index number.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-section-1","tr":"Kısım 1","en":"Section 1 (global exchange data)","kisa":"","tur":"kod","es":["Section 1","temel meteorolojik veriler","global exchange data","Küresel veri bölümü"],"tanim":["SYNOP raporunda küresel paylaşıma açık temel yüzey meteoroloji gözlemlerini aktaran ana veri bölümüdür.","IRixhVV ve Nddff zorunlu grupları ile başlar; ardından sıcaklık, çiy noktası, basınç, basınç eğilimi, yağış, hava hadisesi ve bulut grupları gelebilir.","Sinoptik yer haritası analizinde istasyon modeline işlenen temel parametrelerin tamamını sağlar."],"tanim_en":"The primary section of a SYNOP report containing surface meteorological data for global exchange including wind, temperature, pressure, and clouds.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-section-3","tr":"Kısım 3","en":"Section 3 (supplementary data)","kisa":"333","tur":"kod","es":["Section 3","ulusal veri kısmı","Kısım 3 ek veri grubu","bölgesel ek grup","climatological section","Bölgesel veri bölümü"],"tanim":["SYNOP raporunda 333 gösterge grubuyla başlayan, bölgesel ve ulusal düzeyde paylaşılan ek meteorolojik verileri barındıran bölümdür.","Ekstremler, ayrıntılı bulut katmanları (8NsChshs) ve en kuvvetli rüzgâr hamlesi (911ff) gibi ek grupları içerir.","Sinoptik analizde yerel fırtına hamlelerinin, tavan bulut tabanlarının ve klimatolojik uç değerlerin incelenmesine yarar."],"tanim_en":"A supplementary section of a SYNOP report initiated by code 333 to transmit regional and national meteorological data such as temperature extremes and peak gusts.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-sn-temperature-sign","tr":"Sıcaklık işareti","en":"Sign of temperature indicator","kisa":"sn","tur":"kod","es":["temperature sign code","sn","sıcaklık işaret göstericisi","işaret rakamı","WMO tablo 3845","işaret kodu"],"tanim":["SYNOP raporundaki sıcaklık ve çiy noktası gruplarında (1snTTT, 2snTdTdTd) sıcaklık değerinin cebirsel işaretini belirten tek haneli WMO Kod Tablosu 3845 göstericisidir.","0 değeri sıfır ve pozitif sıcaklıkları (+), 1 değeri ise negatif sıcaklıkları (−) gösterir.","İstasyon modeline sıcaklık ve çiy noktası değerleri yazılırken eksi işaretinin doğru konulmasını ve adveksiyon analizinin hatasız yapılmasını sağlar."],"tanim_en":"A single-digit indicator in SYNOP temperature and dew-point groups designating whether the value is positive or negative according to WMO Code Table 3845.","bag":{"kavram":["synop"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"code-synop-land-report-identifier","tr":"Kara istasyonu rapor tanıtıcısı","en":"SYNOP land station report identifier","kisa":"AAXX","tur":"kod","es":["kara SYNOP başlığı","FM 12 AAXX","kara sinoptik kodu","SYNOP land report","AAXX","FM 12 SYNOP"],"tanim":["WMO-No. 306 FM 12 SYNOP kodunda Kısım 0 başında yer alan ve iletinin sabit bir kara istasyonundan yapıldığını belirten dört harfli sembolik tanıtıcıdır.","İletinin ilk grubunu oluşturur; gemi gözlemleri için kullanılan BBXX tanıtıcısından ayrılır.","Harita analizinde yer verilerini deniz verilerinden ayırt etmede ve veri tabanı ayrıştırmasında kullanılır."],"tanim_en":"A four-letter symbolic code indicating an international SYNOP report from a fixed land station.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-tr-precipitation-duration","tr":"Yağış süresi göstericisi","en":"Duration of precipitation code","kisa":"tR","tur":"kod","es":["yağış süresi kodu","precipitation duration code","tR","WMO tablo 4019","yağış periyodu","yağış süresi"],"tanim":["WMO-No. 306 kod tablosu 4019 uyarınca 6RRRtR grubunun son hanesinde yer alan ve yağış miktarının ölçüldüğü süreyi belirten tek haneli koddur.","Tabloya göre 1 son 6 saat, 2 son 12 saat, 3 son 18 saat, 4 son 24 saat, 5 son 1 saat, 7 son 3 saatlik süreyi gösterir.","Sinoptik harita analizinde bildirilen birikimli yağış miktarının hangi zaman aralığına ait olduğunu saptamak için kullanılır."],"tanim_en":"Single-digit code in the precipitation group indicating the duration of the period for which the precipitation amount is reported.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-tt-time-period","tr":"Hamle süresi göstericisi","en":"Time period indicator","kisa":"tt","tur":"kod","es":["907tt periyodu","time period code","hamle periyodu","hamle zaman grubu","hamle zaman aralığı grubu","907tt"],"tanim":["WMO-No. 306 kod tablosu 4077 uyarınca Kısım 3 içindeki 907tt ek grubunda yer alan ve izleyen aşırı hadiselerin geçerli olduğu süreyi belirten iki haneli koddur.","00 rasat anını, 01–60 arası değerler tt × 6 dk bağıntısıyla süreyi gösterir (örneğin 10 değeri 1 saat, 30 değeri 3 saat, 60 değeri 6 saat).","Tek başına rüzgâr değeri içermez; 911ff grubuyla birlikte son kaç saat içinde en yüksek rüzgâr hamlesinin gerçekleştiğini belirler."],"tanim_en":"Two-digit code in supplementary groups specifying the time period over which an extreme wind speed or meteorological event occurred.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"code-w1w2-past-weather","tr":"Geçmiş hava","en":"past weather","kisa":"W1W2","tur":"kod","es":["geçmiş hava göstericisi","past weather code","W1W2","WMO tablo 4561","geçmiş hava kodu","past weather indicator"],"tanim":["WMO-No. 306 kod tablosu 4561 uyarınca 7wwW1W2 grubunun son iki hanesini oluşturan ve rasat saatinin öncesindeki dönemde gözlenen baskın hava olaylarını bildiren iki rakamlı koddur.","Kural olarak W1 ≥ W2 biçiminde büyük kod önce yazılır; ana sinoptik saatlerde son 6 saati, ara sinoptik saatlerde son 3 saati kapsar.","İstasyon modelinde istasyon çemberinin sağ altına sembolle çizilir; cephe geçişlerini ve hava kütlesi değişimini izlemede kullanılır."],"tanim_en":"Predominant characteristic of the weather that occurred at an observing station during a specified period prior to the observation time.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"code-wind-indicator","tr":"Rüzgâr birimi göstericisi","en":"Wind indicator code","kisa":"iw","tur":"kod","es":["rüzgâr birimi göstergesi","wind unit indicator","iw","rüzgâr birimi","WMO tablo 1855","rüzgâr göstergesi"],"tanim":["WMO-No. 306 kod tablosu 1855 uyarınca YYGGiw grubunun beşinci hanesinde yer alan, rüzgâr hızı birimini ve ölçümün aletsel mi yoksa tahmini mi olduğunu bildiren tek haneli koddur.","Tablo değerleri olarak 0 m/s cinsinden tahmini, 1 m/s cinsinden anemometreyle ölçülmüş, 3 knot cinsinden tahmini ve 4 knot cinsinden anemometreyle ölçülmüş rüzgârı gösterir.","Sinoptik harita analizinde rüzgâr verisinin doğru birimle okunmasını ve jeostrofik rüzgâr hesaplamalarında doğru hız değerinin kullanılmasını sağlar."],"tanim_en":"Single-digit code specifying whether the wind speed is estimated or anemometer-measured and whether the unit is metres per second or knots.","bag":{"kavram":["synop","ruzgar-yonu"],"soru":[],"hesap":["ruzgar"]}},{"id":"code-ww-present-weather","tr":"Şimdiki hava","en":"present weather","kisa":"ww","tur":"kod","es":["present weather code","şimdiki hava olayı","hadise","ww","WMO tablo 4677"],"tanim":["WMO-No. 306 kod tablosu 4677 uyarınca 7wwW1W2 grubunda yer alan ve rasat anında veya son bir saat içinde gözlenen hava hadisesini bildiren iki haneli koddur (00–99).","İstasyon modelinde istasyon çemberinin sol tarafına uluslararası standart meteorolojik sembolüyle yerleştirilir.","Sinoptik analizde soğuk cepheye bağlı sağanak ve orajları (80–99) veya sıcak cepheye bağlı sürekli yağmuru (61, 63, 65) ayırt etmede temel ölçüttür."],"tanim_en":"Two-digit code indicating the meteorological phenomena observed at the station at the time of observation or during the preceding hour.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"precipitation","tr":"Yağış miktarı","en":"amount of precipitation","kisa":"RRR","tur":"kod","es":["atmosferik yağış","hydrometeoric fall","düşen yağış miktarı","precipitation amount code","RRR","WMO tablo 3590"],"tanim":["Sızma, akış veya buharlaşma olmaksızın ve katı yağışların eridiği varsayılarak yatay bir yüzeyde biriken sıvı suyun milimetre cinsinden derinliğidir.","SYNOP'ta 6RRRtR grubunda üç haneyle verilir: 001–988 tam milimetre, 990 iz miktar, 991–999 ise 0,1–0,9 mm; 1 mm derinlik metrekareye 1 litre suya karşılık gelir.","Harita analizinde cephe sistemlerinin ve konvektif hatların bıraktığı toplam yağış miktarını izlemede kullanılır; Türkiye uygulamasında yağış olmasa da ana saatlerde 000 olarak verilir."],"tanim_en":"Depth to which liquid precipitation would cover a horizontal plane of the Earth surface in the absence of evaporation or runoff.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"visibility","tr":"Yatay görüş","en":"horizontal visibility","kisa":"VV","tur":"kod","es":["görüş mesafesi","meteorolojik görüş","meteorological visibility","visibility distance","Yatay görüş uzaklığı","Görüş uzaklığı"],"tanim":["Gözlemcinin bulunduğu yatay düzlem üzerindeki bir nesneyi gündüz açıkça görebildiği veya gece ışığını tanıdığı en büyük mesafedir.","SYNOP Kısım 1'deki iRixhVV grubunda iki haneli VV koduyla bildirilir; 00–50 arası VV/10 km, 56–80 arası VV − 50 km bağıntısıyla okunur.","İstasyon modelinde şimdiki hava simgesinin soluna yazılır; sis, pus veya yoğun yağış alanlarını belirlemede kullanılır."],"tanim_en":"Maximum distance at which an observer can identify an object situated near the horizontal plane.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["gorus-bulut"]}},{"id":"wmo","tr":"Dünya Meteoroloji Örgütü","en":"World Meteorological Organization","kisa":"WMO","tur":"kod","es":["Dünya Meteoroloji Teşkilatı","WMO-No. 306"],"tanim":["Hava, iklim ve su alanında uluslararası iş birliğini koordine eden, sinoptik kodlama standartlarını ve meteorolojik sözlüğü belirleyen Birleşmiş Milletler uzmanlık kuruluşudur.","Küresel Gözlem Sistemini yönetir; üye ülkelere iki haneli blok numaraları (Türkiye için 17) ve bu blok altında üç haneli istasyon numaraları tahsis eder (ikisi birlikte beş haneli istasyon indeksi).","Hava haritalarının dünya genelinde standart semboller ve standart izobarik yüzeyler kullanılarak çizilmesini sağlar."],"tanim_en":"United Nations specialized agency that coordinates international standards for meteorological observations, codes, and weather reporting.","bag":{"kavram":["synop"],"soru":[],"hesap":[]}},{"id":"air-temperature","tr":"Hava sıcaklığı","en":"Air temperature","kisa":"TTT","tur":"olcu","es":["Kuru termometre sıcaklığı","kuru termometre sıcaklığı","ambient temperature","hava sıcaklığı değeri","air temperature code","TTT"],"tanim":["Doğrudan güneş ışınımından korunan havalandırmalı bir siperlik içindeki termometreyle ölçülen hava sıcaklığıdır.","SYNOP iletisinde 1snTTT grubunda onda bir Santigrat derece cinsinden üç hane (TTT) olarak bildirilir; işaret sn (0 pozitif, 1 negatif) hanesiyle verilir.","İstasyon modelinde istasyon çemberinin sol üst köşesine yazılır; yatay sıcaklık gradyanı ve sıcaklık adveksiyonu analizinin temel girdisidir."],"tanim_en":"Temperature of the air measured by a thermometer sheltered from direct solar radiation.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"code-hshs-cloud-height","tr":"Bulut taban yüksekliği veya dikine görüş","en":"Height of cloud base or vertical visibility","kisa":"hshs","tur":"olcu","es":["dikine rüyet","hshs","bulut katmanı yüksekliği","vertical visibility code","taban kodu hshs"],"tanim":["SYNOP Kısım 3 içinde yer alan 8NsChshs grubundaki iki haneli bulut taban yüksekliği ya da dikey görüş kodudur (WMO Kod 1677).","01–50 arası değerler 30 m adımlarla, 56–80 arası 300 m adımlarla verilir; 00 değeri 30 m altını belirtir.","Kısım 1 içindeki tek haneli h koduna göre bulut tabanını çok daha duyarlı ve tabaka tabaka bildirmeyi sağlar."],"tanim_en":"Two-digit code in the SYNOP 8NsChshs group representing the height of the cloud base above surface or the vertical visibility according to WMO Code Table 1677.","bag":{"kavram":["synop"],"soru":[],"hesap":["gorus-bulut"]}},{"id":"dew-point-depression","tr":"Çiy noktası açığı","en":"dew-point depression","kisa":"T − Td","tur":"olcu","es":["çiy açığı","sıcaklık-çiy noktası farkı","sıcaklık çiy noktası farkı","çiğ noktası depresyonu (kuruluk)","çiy noktası depresyonu","T - Td"],"tanim":["Hava sıcaklığı (T) ile çiy noktası sıcaklığı (Td) arasındaki farktır (T − Td).","Birimi santigrat derecedir (°C); fark sıfıra yaklaştıkça hava doygunluğa erişir, fark büyüdükçe havanın kuruluğu artar.","İstasyon modelinde ve aerolojik diyagramlarda havanın nem durumunu ve kuruluk derecesini değerlendirmede kullanılır."],"tanim_en":"Difference between the air temperature and the dew-point temperature indicating the degree of saturation of the air.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"dew-point-temperature","tr":"Çiy noktası sıcaklığı","en":"Dew-point temperature","kisa":"Td","tur":"olcu","es":["çiy noktası","Td","dew point","işba sıcaklığı","Çiy noktası","çiy sıcaklığı"],"tanim":["Sabit basınç ve sabit su buharı miktarında havanın doygunluğa ulaşması için soğutulması gereken sıcaklıktır.","SYNOP iletisinde 2snTdTdTd grubuyla onda bir °C biriminde bildirilir; istasyon modelinde istasyon dairesinin sol altına yazılır.","Yer analizinde hava kütlesinin nem içeriğini gösterir; cephe geçişlerinde ve kuru hat sınırlarında belirgin süreksizlik sergiler."],"tanim_en":"Temperature to which moist air must cool at constant pressure and moisture content to reach saturation.","bag":{"kavram":["synop","cephe-olcutleri","istasyon-modeli"],"soru":[],"hesap":["sicaklik-kodu"]}},{"id":"pressure-tendency","tr":"Basınç eğilimi","en":"pressure tendency","kisa":"appp","tur":"olcu","es":["barometrik eğilim","tendans eğrisi sembolü","basınç eğilim sembolü","pressure tendency symbol","3 saatlik basınç eğilimi","barometric tendency"],"tanim":["İstasyon basıncının gözlem anından önceki 3 saatlik dönemde gösterdiği net değişim miktarı ve değişim karakteristiğidir.","SYNOP 5appp grubunda bildirilir; modelde istasyon dairesinin sağında karakteristik eğri simgesi ve onda bir hPa cinsinden miktar ile gösterilir.","Yer haritasında siklonların hareket yönünü, derinleşme hızını ve cephe geçişlerini saptamada temel göstergedir."],"tanim_en":"Net change and characteristic curve of station pressure during the three hours preceding the observation.","bag":{"kavram":["synop","istasyon-modeli","cephe-olcutleri"],"soru":[],"hesap":["basinc-kodu"]}},{"id":"valid-time","tr":"Geçerlilik zamanı","en":"valid time","kisa":"valid","tur":"olcu","es":["öngörü zamanı","tahmin geçerlilik zamanı","tahmin geçerlilik anı","validity time","VT","tahmin anı"],"tanim":["Sayısal hava tahmin modelinin veya analiz haritasının temsil ettiği, öngörünün geçerli olduğu hedef an ve tarihtir.","Harita künyelerinde UTC birimiyle belirtilir; model başlangıç anına öngörü adım süresi eklenerek bulunur.","Sinoptik harita analizinde incelenen atmosfer durumunun hangi zaman dilimine ait olduğunu belirler."],"tanim_en":"Specific time and date for which a meteorological forecast chart applies.","bag":{"kavram":["synop"],"soru":[],"hesap":["basinc-kodu"]}},{"id":"wind-gust","tr":"Rüzgâr hamlesi","en":"wind gust","kisa":"G","tur":"olcu","es":["hamleli rüzgâr","ani rüzgâr artışı","gust","hamle hızı"],"tanim":["Ortalama rüzgâr hızında anlık olarak meydana gelen, kısa süreli ani ve belirgin hız artışıdır.","Knot (kt) veya m/s ile verilir; SYNOP Kısım 3'te 910ff (son 10 dk'nın en büyük hamlesi) ve 907tt ile birlikte 911ff (belirtilen sürenin en büyük hamlesi) gruplarıyla bildirilir; METAR'da hamle ortalamayı en az 10 kt aşınca G ile yazılır.","Sinoptik ölçekte soğuk cephe geçişleri, sağanak hatları ve konvektif fırtınalarda yer seviyesindeki tepe rüzgâr kuvvetini gösterir."],"tanim_en":"Sudden brief increase in wind speed above the mean value lasting for a few seconds.","bag":{"kavram":["synop","ruzgar-yonu","istasyon-modeli"],"soru":[],"hesap":["adveksiyon"]}},{"id":"drizzle","tr":"Çisenti","en":"drizzle","kisa":"DZ","tur":"surec","es":["çiseleme","hafif çisenti","sürekli çisenti","DZ"],"tanim":["Çapı 0,5 mm'den küçük, birbirine çok yakın ve havada asılı gibi duran çok ince su damlacıklarından oluşan tekdüze sıvı yağıştır.","SYNOP iletisinde 7wwW1W2 grubunda ww = 50–59 kod aralığıyla bildirilir; istasyon modelinde virgül sembolüyle gösterilir.","Genellikle Stratus veya Stratocumulus bulutlarından düşer; sinoptik analizde sıcak cephenin arkasındaki sıcak sektörün tipik yağış türüdür."],"tanim_en":"Fairly uniform precipitation of fine water droplets of diameter less than 0.5 mm.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"fog","tr":"Sis","en":"fog","kisa":"FG","tur":"surec","es":["yer bulutu","surface cloud","sığ sis","yoğun sis","buz sisi","surface cloud layer"],"tanim":["Atmosferin alt katmanında asılı mikroskobik su damlacıklarının yatay görüşü 1 km altına düşürdüğü hidrometeordur.","SYNOP 7wwW1W2 grubunda ww = 40–49 kod aralığıyla ve N = 9 ya da N = 8 kapalılıkla bildirilir; modelde üç yatay paralel çizgiyle gösterilir.","Yer seviyesinde havanın çiy noktasına kadar soğuması sonucu oluşur; kararlı hava kütlesi veya antisiklon koşullarına işaret eder."],"tanim_en":"Suspension of microscopic water droplets in the air reducing surface horizontal visibility below 1 km.","bag":{"kavram":["synop","istasyon-modeli"],"soru":["S1","S2","S3","S5","S7","S9"],"hesap":[]}},{"id":"freezing-rain","tr":"Donan yağmur","en":"freezing rain","kisa":"FZRA","tur":"surec","es":["aşırı soğumuş yağmur","glaze-producing rain","glaze","donucu yağmur","FZRA"],"tanim":["Sıcaklığı 0 °C altında bulunan aşırı soğumuş yağmur damlalarının yere veya soğuk nesnelere çarptığı anda donmasıyla oluşan yağıştır.","SYNOP 7wwW1W2 grubunda ww = 66 ve ww = 67 kodlarıyla iletilir; zeminde cam gibi pürüzsüz şeffaf bir buz tabakası (glaze) bırakır.","Genellikle sıcak cephe önünde soğuk yer tabakası üzerine tırmanan sıcak havanın oluşturduğu sıcaklık terselmesi kuşağında görülür."],"tanim_en":"Supercooled raindrops that freeze on impact with the ground or cold objects to form a smooth coating of clear ice.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"hail","tr":"Dolu","en":"hail","kisa":"GR","tur":"surec","es":["dolu tanesi","hailstone","dolu yağışı","dolulu oraj","dolu sağanağı","küçük dolu"],"tanim":["Cumulonimbus bulutundaki güçlü yukarı hava akımlarında donan ve çapı 5 mm veya daha büyük olan katı buz parçacıklarından oluşan yağıştır.","SYNOP 7wwW1W2 grubunda orajla birlikte ww = 96 ve ww = 99 kodlarıyla verilir; istasyon modelinde içi dolu üçgen sembolüyle yer alır.","Sinoptik haritada soğuk cephe boyunca veya cephe önündeki sağanak hatlarında (squall line) şiddetli konvektif kararsızlığın göstergesidir."],"tanim_en":"Precipitation of balls or pieces of ice with a diameter of 5 mm or more falling from a cumulonimbus cloud.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"mist","tr":"Pus","en":"mist","kisa":"BR","tur":"surec","es":["hafif sis","puslu hava","nemli pus","hafif sis pus","Pus (hafif sis)","Light fog"],"tanim":["Atmosferde asılı duran mikroskopik su damlacıkları veya ıslak higroskopik parçacıkların yer seviyesinde yatay görüşü düşürmesi olayıdır.","SYNOP şimdiki hava kodunda ww = 10 ile belirtilir; bağıl nem yüksektir ve yatay görüş 1 km ya da daha fazladır (METAR’da BR için 1–5 km).","Sinoptik analizde sıcak cephenin arkasında ve sıcak sektör içinde kararlı sınır tabakayı gösterir."],"tanim_en":"A suspension of microscopic water droplets or wet hygroscopic particles in the atmosphere reducing horizontal surface visibility.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"rain","tr":"Yağmur","en":"rain","kisa":"RA","tur":"surec","es":["sıvı yağış","rainfall","sürekli yağmur","continuous rain","aralıklı yağmur","liquid precipitation"],"tanim":["Çapı 0,5 mm'den büyük damlalardan ya da daha küçük ama seyrek dağılmış damlalardan oluşan sıvı yağıştır.","SYNOP şimdiki hava grubunda sürekli yağmur ww = 61, 63, 65 kodlarıyla bildirilir; istasyon modelinde nokta sembolleriyle gösterilir.","Sinoptik haritada sıcak cephenin önündeki geniş Ns ve As bulut örtüsü altında sürekli karakterde gözlenir."],"tanim_en":"Precipitation of liquid water droplets with diameter exceeding 0.5 mm or smaller widely scattered droplets falling to the ground.","bag":{"kavram":["synop","istasyon-modeli"],"soru":["S2","S3"],"hesap":[]}},{"id":"shower","tr":"Sağanak","en":"shower","kisa":"SH","tur":"surec","es":["sağanak yağış","sağanak yağmur","kar sağanağı","yağmur sağanağı","convective shower"],"tanim":["Konvektif bulutlardan düşen, ani başlayıp kesilen, şiddeti hızla değişen kısa süreli yağıştır.","SYNOP raporunda şimdiki hava ww = 80–90 kod aralığında verilir (91–99 orajla birlikte olanlar); istasyon modelinde ters üçgen tabanlı sembollerle gösterilir.","Sinoptik analizde soğuk cephe hattında veya cephe gerisindeki kararsız soğuk hava kütlesi içinde görülür."],"tanim_en":"Precipitation characterized by sudden start and abrupt end with rapid fluctuations in intensity, falling from convective clouds.","bag":{"kavram":["synop","istasyon-modeli"],"soru":["S2","S3"],"hesap":[]}},{"id":"snow","tr":"Kar","en":"snow","kisa":"SN","tur":"surec","es":["kar yağışı","solid precipitation","sürekli kar","kuşbaşı kar"],"tanim":["Atmosferden tek tek ya da birbirine yapışmış buz kristalleri biçiminde düşen katı yağıştır.","SYNOP şimdiki hava grubunda sürekli kar ww = 71, 73, 75 kodlarıyla verilir; istasyon modelinde yıldız sembolüyle gösterilir.","Yer yakınına kadar sıcaklığın 0 °C dolayında ya da altında kaldığı durumlarda ve kışın sıcak cephelerin geniş ön kuşağında gözlenir."],"tanim_en":"Solid precipitation in the form of branched hexagonal ice crystals or flakes falling to the ground.","bag":{"kavram":["synop","istasyon-modeli"],"soru":["S1","S2","S3","S5","S6","S7"],"hesap":[]}},{"id":"squall-phenomenon","tr":"Bora (ani rüzgâr fırtınası)","en":"squall","kisa":"SQ","tur":"surec","es":["boran","ani fırtına","bora","squalls","ani rüzgâr fırtınası","SQ"],"tanim":["Rüzgâr hızının aniden en az bir dk sürecek biçimde şiddetle artması ve ardından hızla yatışması olayıdır.","SYNOP şimdiki hava kodunda ww = 18 koduyla bildirilir; yer haritasında rüzgâr çubuğunda ani hız artışı ve yön sapmasıyla belirlenir.","Genellikle hızlı ilerleyen soğuk cephelerin önündeki sağanak hatları veya Cb bulutlarının aşağı hava akımlarıyla birlikte oluşur."],"tanim_en":"A sudden and sharp wind speed increase that lasts for at least one minute before diminishing rapidly.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"thunderstorm","tr":"Oraj","en":"thunderstorm","kisa":"TS","tur":"surec","es":["gök gürültülü fırtına","yağışsız oraj","şimşekli fırtına","şimşekli gök gürültülü fırtına","TS"],"tanim":["Cumulonimbus (Cb) bulutunun ürettiği, şimşek çakması ve gök gürültüsüyle tanınan yerel fırtınadır.","SYNOP raporunda şimdiki hava ww = 17 veya 29 veya 91–99 arasında, geçmiş hava grubunda W1W2 = 9 koduyla gösterilir.","Sinoptik analizde soğuk cephe sınırında, kuru hat boyunca veya kararsız sıcak hava kütlelerinde kuvvetli yukarı hareket alanlarında oluşur."],"tanim_en":"A local storm produced by a cumulonimbus cloud and accompanied by lightning and thunder.","bag":{"kavram":["synop","istasyon-modeli"],"soru":[],"hesap":[]}},{"id":"vertical-wind-shear","tr":"Düşey rüzgâr kesmesi","en":"Vertical wind shear","kisa":"","tur":"kavram","es":["rüzgâr kesmesi","Düşey kesme","Rüzgâr kesmesi","düşey kesme"],"tanim":["Yükseklikle birlikte rüzgârın hızında veya yönünde meydana gelen vektörel değişimdir.","Birimi m s⁻¹ km⁻¹ veya knot/1000 ft cinsindendir; sinoptik ölçekte iki izobarik seviye arasındaki termal rüzgâr vektörüne karşılık gelir.","Harita analizinde baroklinik bölgeleri belirler; yatay sıcaklık gradyanının kuvvetli olduğu cephe zonlarında ve jet akımı altında en yüksek değerine ulaşır."],"tanim_en":"The change in horizontal wind velocity vector with height in the atmosphere.","bag":{"kavram":["termal-ruzgar"],"soru":[],"hesap":[]}},{"id":"behind-trough","tr":"Trofun arkası","en":"Behind the trough","kisa":"CONV ↓","tur":"kavram","es":["trof arkası","trofun batısı","upstream of trough","Trofun arkası (batısı)"],"tanim":["Üst seviye jeopotansiyel haritasında trof ekseninin batısında veya akışın geldiği tarafında kalan alandır.","Bu bölgede kuzeybatılı akış hâkimdir; negatif vortisite adveksiyonu ve üst seviye yakınsaması görülür.","Düşey düzlemde havanın çökmesine, ısınmasına ve kurumasına yol açarak yer seviyesinde basınç artışı ve açık hava koşulları üretir."],"tanim_en":"The region to the west or upstream of an upper-level trough axis where subsidence and clearing prevail.","bag":{"kavram":["trof-onu","yakinsama","trof-sirt"],"soru":["S3","S7","S10"],"hesap":[]}},{"id":"absolute-vorticity-advection","tr":"Mutlak vortisite adveksiyonu","en":"absolute vorticity advection","kisa":"AVA","tur":"surec","es":["vortisite adveksiyonu","vorticity advection","mutlak girdap adveksiyonu"],"tanim":["Mutlak vortisitenin yani göreli girdap ile Coriolis parametresi toplamının yatay rüzgâr alanı tarafından taşınması sürecidir.","500 hPa analiz haritalarında pozitif ve negatif adveksiyon alanları olarak renkli konturlarla sergilenir.","Yarı-jeostrofik kuramda yükseklikle artan pozitif mutlak vortisite adveksiyonu sinoptik ölçekte hava yükselmesini ve siklon gelişimini zorlar."],"tanim_en":"The horizontal transport of absolute vorticity by the wind field.","bag":{"kavram":["trof-onu"],"soru":["S3"],"hesap":[]}},{"id":"diffluence","tr":"Yön ıraksaması (dağılma)","en":"Diffluence","kisa":"V ∂ψ/∂n","tur":"surec","es":["difluens","dağılma","yön ıraksaması"],"tanim":["Akış çizgilerinin rüzgâr doğrultusunda ilerledikçe yelpaze gibi birbirinden uzaklaşması ve yana doğru açılması durumudur.","Doğal koordinatlarda V ∂ψ/∂n terimiyle temsil edilir; akış açılmasını rüzgâr hızıyla çarparak yatay ıraksamaya katkı verir.","Sinoptik üst seviye haritalarında trof önü ve sırt arkası bölgelerinde görülerek net kütle ıraksamasına ve alt seviyeden yükselme hareketine katkı sağlar."],"tanim_en":"The progressive drawing apart of streamlines in the direction of flow.","bag":{"kavram":["trof-onu","yakinsama"],"soru":[],"hesap":[]}},{"id":"negative-vorticity-advection","tr":"Negatif vortisite adveksiyonu","en":"Negative vorticity advection","kisa":"NVA","tur":"surec","es":["negatif girdap adveksiyonu","anticyclonic vorticity advection","NVA","negatif girdap taşınımı","antisiklonik vortisite adveksiyonu","NVA kısaltması"],"tanim":["Üst seviye akışının daha düşük veya antisiklonik vortisiteye sahip hava parsellerini akış aşağı yönünde taşıması sürecidir.","500 hPa haritalarında genellikle soğuk tonlarla gösterilir ve trof ekseninin batısında yoğunlaşır.","Troposferin orta seviyelerinde kütle yığılmasına ve buna bağlı geniş ölçekli çökmeye yol açarak açık havayı destekler."],"tanim_en":"Horizontal transport of lower or anticyclonic vorticity by the wind field, typically inducing downward motion and clear sky conditions.","bag":{"kavram":["trof-onu","yakinsama","adveksiyon"],"soru":["S3"],"hesap":[]}},{"id":"positive-vorticity-advection","tr":"Pozitif vortisite adveksiyonu","en":"Positive vorticity advection","kisa":"PVA","tur":"surec","es":["pozitif girdap adveksiyonu","cyclonic vorticity advection","PVA","Pozitif girdap adveksiyonu","pozitif girdap taşınımı","CVA"],"tanim":["Üst seviye rüzgârının daha yüksek siklonik vortisiteye sahip hava parsellerini akış aşağı yönünde taşıması sürecidir.","500 hPa haritalarında sarı, turuncu ve kırmızı tonlarla gösterilir ve trof ekseninin doğusunda yer alır.","Yarı-jeostrofik kurama göre orta troposferde ıraksama ve buna bağlı geniş ölçekli yükselme hareketi üreterek bulut ve yağışı destekler."],"tanim_en":"Horizontal transport of higher cyclonic vorticity by the flow, which forces large-scale ascent and cloud development.","bag":{"kavram":["trof-onu","yakinsama","adveksiyon"],"soru":["S3"],"hesap":[]}},{"id":"upper-level-convergence","tr":"Üst seviye yakınsaması","en":"Upper-level convergence","kisa":"CONV","tur":"surec","es":["üst seviye konverjansı","upper convergence","yukarı seviye konverjansı"],"tanim":["Üst troposferde birim alana giren yatay hava akısının çıkan akıdan daha büyük olması durumudur.","Tipik sinoptik değeri 10⁻⁵ s⁻¹ mertebesinde bulunur; 500 hPa veya 300 hPa haritalarında akışın daraldığı bölgelerde saptanır.","Dines dengelenmesi uyarınca üst seviyedeki kütle birikimi havayı aşağı doğru iter, troposferde çökmeye ve yerde yüksek basınca yol açar."],"tanim_en":"Net horizontal mass inflow in the upper troposphere that forces large-scale downward motion through mass conservation.","bag":{"kavram":["trof-onu","yakinsama"],"soru":["S2","S3"],"hesap":[]}},{"id":"upper-level-divergence","tr":"Üst seviye ıraksaması","en":"Upper-level divergence","kisa":"DIV","tur":"surec","es":["üst seviye diverjansı","upper divergence","upper tropospheric divergence","yukarı seviye diverjansı","Üst seviye diverjansı"],"tanim":["Üst troposferde yatay hız alanının net dışa yayılma göstermesi durumudur.","Tipik sinoptik değeri 10⁻⁵ s⁻¹ mertebesinde bulunur; 300 hPa ve 200 hPa kartlarında akışın yelpaze gibi açıldığı bölgelerde belirgindir.","Dines dengelenmesi uyarınca üstteki kütle boşalmasını telafi etmek için alttan hava çekilir; bu durum yükselmeyi ve yer alçağının derinleşmesini sağlar."],"tanim_en":"Net horizontal mass outflow in the upper troposphere that draws air upward from below to maintain mass continuity.","bag":{"kavram":["trof-onu","yakinsama","jet-streak"],"soru":["S2","S3","S10"],"hesap":[]}},{"id":"quasi-geostrophic-theory","tr":"Yarı-jeostrofik kuram","en":"Quasi-geostrophic theory","kisa":"QG","tur":"yontem","es":["QG kuramı","yarı jeostrofik teori","yarı-jeostrofik yaklaşım","quasi-geostrophic approximation","QG theory"],"tanim":["Hareket denklemlerinde jeostrofik denge kabulünün belirli terimlerde kullanılıp küçük ölçekli dalgaların elendiği standart sinoptik yaklaşımdır.","Rossby sayısının birden çok küçük olduğu sinoptik ölçekli sistemlerde adveksiyonun jeostrofik rüzgârla hesaplanmasına dayanır.","Üst seviye vortisite adveksiyonu ve sıcaklık adveksiyonunu omega denklemiyle birleştirerek düşey hareketi belirler."],"tanim_en":"A theoretical framework approximating synoptic-scale atmospheric motion by employing geostrophic balance to evaluate horizontal advection and vertical velocity.","bag":{"kavram":["trof-onu","jeostrofik"],"soru":[],"hesap":[]}},{"id":"ridge","tr":"Sırt","en":"Ridge","kisa":"","tur":"kavram","es":["yüksek basınç sırtı","sırt ekseni","sırt tepe noktası","crest of ridge","Sırt tepesi","Ridge crest"],"tanim":["Bir yüksek basınç alanından dışa doğru uzanan ve nispeten yüksek jeopotansiyel yükseklik veya basınç içeren dilsi yapıdır.","Haritalarda kontur veya izobarların antisiklonik dışbükey büküldüğü eksen çizgisiyle gösterilir.","Sırt ekseni boyunca kararlı hava koşulları, çökme inversiyonu ve açık gökyüzü egemendir."],"tanim_en":"An elongated area of relatively high atmospheric pressure or geopotential height characterized by anticyclonic contour curvature.","bag":{"kavram":["trof-sirt"],"soru":["S2","S3","S7"],"hesap":[]}},{"id":"short-wave-trough","tr":"Kısa dalga trof","en":"short-wave trough","kisa":"","tur":"kavram","es":["kısa dalga oluk","short wave","shortwave","kısa dalga"],"tanim":["Üst seviye Rossby dalgaları üzerine bindirilmiş, dalga boyu daha kısa ve ilerleme hızı daha yüksek olan siklonik basınç oluğudur.","500 hPa haritalarında jeopotansiyel konturlarda dar bükülmeler ve önündeki belirgin pozitif vortisite adveksiyonu ile teşhis edilir.","Hızlı hareket ederek yer cephelerinin ve siklonlarının tetiklenmesinde, ani hava değişimlerinde ana rolü oynar."],"tanim_en":"A small-scale atmospheric wave embedded within the major long-wave pattern that moves rapidly and triggers localized ascent.","bag":{"kavram":["trof-sirt","trof-onu"],"soru":[],"hesap":[]}},{"id":"trough","tr":"Trof","en":"Trough","kisa":"","tur":"kavram","es":["oluk","alçak basınç oluğu","trof ekseni","basınç oluğu","Trof (oluk)"],"tanim":["Atmosferde alçak basıncın veya alçak jeopotansiyel yüksekliğin dışa doğru uzandığı dilsi alandır.","Haritalarda kontur veya izobarların siklonik yönde büküldüğü eksen çizgisi boyunca tanımlanır.","Trof ekseninin ön tarafında akış yükselme ve yağış üretirken, arkasında çökme ve açık hava görülür."],"tanim_en":"An elongated area of relatively low atmospheric pressure or geopotential height typically associated with cyclonic curvature.","bag":{"kavram":["trof-sirt"],"soru":["S3","S7","S10"],"hesap":[]}},{"id":"u-shaped-trough","tr":"U biçimli trof","en":"U-shaped trough","kisa":"","tur":"kavram","es":["yayvan trof","broad trough","geniş trof","U trof"],"tanim":["Kontur çizgilerinin taban kısmında keskin bir kırılma yerine geniş ve yayvan bir kavis çizdiği trof türüdür.","Eksen civarındaki siklonik eğrilik yarıçapı büyüktür; haritalarda geniş alana yayılan gevşek kontur bükülmeleriyle izlenir.","Girdap gradyanı düşük olduğundan zayıf ama geniş bir alana yayılan, uzun süreli yağış düzeni üretir."],"tanim_en":"A broad trough configuration with a large radius of curvature yielding weak yet widespread and persistent precipitation.","bag":{"kavram":["trof-sirt"],"soru":["S3"],"hesap":[]}},{"id":"v-shaped-trough","tr":"V biçimli trof","en":"V-shaped trough","kisa":"","tur":"kavram","es":["keskin trof","sharp trough","V trof","dar trof"],"tanim":["Kontur çizgilerinin eksen boyunca dar bir açıyla dönerek keskin V profili oluşturduğu trof türüdür.","Eksen çevresinde siklonik eğrilik yarıçapı çok küçüktür ve izohipslere dik yönde belirgin rüzgâr yön değişimi eşlik eder.","Kuvvetli eğrilik vortisitesi ve belirgin PVA üreterek trof önünde dar bir alanda şiddetli konvektif sağanaklara yol açar."],"tanim_en":"A sharp trough pattern characterized by a small radius of curvature triggering strong localized ascent and heavy convective showers.","bag":{"kavram":["trof-sirt"],"soru":["S3"],"hesap":[]}},{"id":"vertical-cross-section","tr":"Düşey kesit","en":"Vertical cross-section","kisa":"","tur":"cihaz","es":["dikey kesit","atmospheric cross-section","cross section"],"tanim":["Atmosferik bir değişkenin veya sistem yapısının yükseklikle değişimini iki boyutlu düzlemde gösteren grafik veya harita kesitidir.","Yatay eksende coğrafi konum veya istasyonlar, düşey eksende basınç seviyeleri (hPa) ya da geometrik yükseklik (km) yer alır.","Sinoptik analizde alçak ve yüksek basınçların düşey eksen eğimini, cephe eğimini ve düşey dolaşımı incelemek için kullanılır."],"tanim_en":"A two-dimensional diagram that displays the vertical distribution and variation of meteorological parameters along a horizontal track.","bag":{"kavram":["yakinsama","merkez","cekirdek"],"soru":["S5"],"hesap":[]}},{"id":"level-of-non-divergence","tr":"Iraksamasız seviye","en":"Level of non-divergence","kisa":"LND","tur":"kavram","es":["diverjanssız seviye","zero divergence level","LND"],"tanim":["Atmosferde yatay ıraksamanın sıfır olduğu ve işaret değiştirdiği seviyedir.","Troposferde genellikle 600 hPa (yaklaşık 500–600 hPa) civarında bulunur; alt ve üst troposferdeki ıraksama zıt işaretlidir.","Süreklilik denklemine göre bu seviyede düşey hız mutlak değerce en büyük değerine ulaşır."],"tanim_en":"An atmospheric level where horizontal divergence is zero, typically located around 600 hPa between opposing divergence regimes.","bag":{"kavram":["yakinsama"],"soru":[],"hesap":[]}},{"id":"subsidence-inversion","tr":"Çökme inversiyonu","en":"subsidence inversion","kisa":"","tur":"kavram","es":["alçalma enversiyonu","çökme terselmesi","antisiklonal enversiyon","subsidence temperature inversion","çökme enversiyonu","sübsidans inversiyonu"],"tanim":["Geniş ölçekli hava kütlesinin alçalması ve adyabatik sıkışmayla ısınması sonucu serbest atmosferde oluşan sıcaklık terselmesidir.","Yüksek basınç merkezlerinde ve sırtlarda görülür; tabanın üstünde sıcaklık artarken çiy noktası hızla düşer ve hava kurur.","Atmosferde kararlı bir tabaka oluşturarak düşey karışımı ve konvektif bulut gelişimini sınırlar."],"tanim_en":"A temperature inversion formed aloft by the adiabatic warming of sinking air within a subsiding air column.","bag":{"kavram":["yakinsama"],"soru":[],"hesap":[]}},{"id":"tropopause","tr":"Tropopoz","en":"Tropopause","kisa":"","tur":"kavram","es":["tropopoz tabakası","tropopause level","troposfer tavanı"],"tanim":["Troposfer ile stratosfer arasındaki sınır olup sıcaklık düşme oranının belirgin biçimde azaldığı geçiş yüzeyidir.","Sıcaklık düşme oranının 2 °C/km veya altına indiği en alt seviyedir; kutuplarda yaklaşık 8–9 km, ekvatorda 16–17 km yüksekliktedir.","Düşey konvektif hareket için kapak görevi görür; hemen altında polar ve subtropikal jet akımları ile açık hava türbülansı yer alır."],"tanim_en":"The boundary separating the troposphere from the stratosphere where the environmental lapse rate falls to 2 °C/km or less.","bag":{"kavram":["yakinsama","jet-akimi"],"soru":[],"hesap":[]}},{"id":"ascent","tr":"Yükselme","en":"Ascent","kisa":"↑","tur":"surec","es":["düşey yükselme","vertical ascent","upward motion","yükselici hareket","rising motion","Düşey yükselme hareketi"],"tanim":["Havanın yerçekimine zıt yönde yukarı doğru yaptığı düşey hareket sürecidir.","Sinoptik ölçekte düşey hız w genelde cm/s mertebesinde kalır; basınç koordinatında omega negatif değer alır.","Yerdeki siklonik yakınsama ve üst seviyedeki trof önü ıraksamasıyla tetiklenir; havanın adyabatik soğumasına, bulut ve yağış oluşumuna yol açar."],"tanim_en":"The upward vertical motion of air that leads to adiabatic cooling and cloud formation in the atmosphere.","bag":{"kavram":["yakinsama","trof-onu"],"soru":["S2","S3"],"hesap":[]}},{"id":"subsidence","tr":"Çökme","en":"Subsidence","kisa":"↓","tur":"surec","es":["alçalma","sinking motion","downward motion","alçalıcı hareket","çökücü hareket","çökme hareketi"],"tanim":["Atmosferde geniş bir hava kütlesinin aşağı doğru yavaş ve kararlı alçalma hareketidir.","Sinoptik ölçekte düşey hız w negatif işaretlidir; basınç koordinatında omega pozitif değer alır.","Hava alçalırken adyabatik olarak sıkışıp ısınır, bağıl nemi düşer, bulutları eritir ve yüksek basınç alanlarında açık havaya yol açar."],"tanim_en":"A widespread downward motion of air in the atmosphere typically accompanied by adiabatic warming and drying.","bag":{"kavram":["yakinsama","trof-onu"],"soru":["S2","S3"],"hesap":[]}},{"id":"continuity-equation","tr":"Süreklilik denklemi","en":"Continuity equation","kisa":"","tur":"yontem","es":["kütle sürekliliği denklemi","kütle korunumu denklemi","kütlenin korunumu","mass continuity","kütle dengesi","continuity"],"tanim":["Akışkanlar mekaniğinde ve dinamik meteorolojide kütlenin korunumunu ifade eden temel korunum denklemidir.","Birim hacimdeki kütle değişiminin o hacme giren ve çıkan kütle akılarının net farkına eşit olduğunu belirtir.","Sinoptik analizde yatay yakınsama veya ıraksama ile düşey hız profili arasındaki bağı kurmak için kullanılır."],"tanim_en":"A fundamental hydrodynamic equation expressing the conservation of fluid mass within an atmospheric volume.","bag":{"kavram":["yakinsama","trof-onu"],"soru":[],"hesap":[]}},{"id":"dines-compensation","tr":"Dines dengelenmesi","en":"Dines compensation","kisa":"","tur":"yontem","es":["Dines compensation principle","Dines kuralı","Dines ilkesi"],"tanim":["Troposfer boyunca yatay ıraksama işaretinin en az bir kez tersine dönerek alt ve üst seviye kütle akılarının birbirini dengelemesi ilkesidir.","Yeryüzünden atmosfer tepesine kadar olan net ıraksama integrali ve dolayısıyla yer basıncı değişimi, alt ve üstteki büyük akıların küçük bir kalıntısıdır.","Altta yakınsama olan siklonların üzerinde ıraksama, altta ıraksama olan antisiklonların üzerinde yakınsama bulunmasını açıklar."],"tanim_en":"An atmospheric principle where horizontal divergence inverts sign with height to maintain column mass balance.","bag":{"kavram":["yakinsama"],"soru":[],"hesap":[]}},{"id":"omega-equation","tr":"Omega denklemi","en":"omega equation","kisa":"ω","tur":"yontem","es":["yarı-jeostrofik omega denklemi","QG omega equation","düşey hız denklemi","quasi-geostrophic omega equation"],"tanim":["Yarı-jeostrofik kuramda düşey hızı (basınç koordinatındaki omega değerini) sinoptik zorlamalara bağlayan tanısal diferansiyel denklemdir.","Basınç koordinatında omega negatif olduğunda yükselme, pozitif olduğunda çökme hareketi gösterilir.","Düşey hareketi diferansiyel girdap adveksiyonu ile sıcaklık adveksiyonunun Laplasyenine bağlayarak hava tahmininde düşey hareketi açıklamaya yarar."],"tanim_en":"A diagnostic equation in quasi-geostrophic theory relating vertical motion to differential vorticity advection and thermal advection.","bag":{"kavram":["yakinsama","trof-onu","adveksiyon"],"soru":[],"hesap":["adveksiyon"]}},{"id":"ecmwf","tr":"Avrupa Orta Vadeli Hava Tahminleri Merkezi","en":"European Centre for Medium-Range Weather Forecasts","kisa":"ECMWF","tur":"cihaz","es":["Avrupa Orta Vadeli Tahmin Merkezi","IFS","Avrupa modeli","ECMWF Open Charts","IFS modeli","ECMWF"],"tanim":["Avrupa ülkelerinin ortaklığıyla kurulan, küresel sayısal hava tahmini ve iklim yeniden analizi üreten uluslararası meteoroloji merkezidir.","IFS küresel modelini işletir; orta vadeli deterministik ve topluluk tahmin ürünleri ile ERA5 yeniden analiz veri setini sunar.","Sinoptik harita brifinglerinde ve tahmin analizlerinde yer basıncı, 850 hPa rüzgârı ve 500 hPa jeopotansiyel yükseklik öngörüleri temel referanstır."],"tanim_en":"An international meteorological organisation producing global numerical weather predictions and medium-range forecast guidance.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"gfs","tr":"GFS küresel tahmin modeli","en":"Global Forecast System","kisa":"GFS","tur":"cihaz","es":["NCEP GFS","küresel tahmin sistemi","GFS","GFS modeli","Global Forecast System model","Küresel Tahmin Sistemi"],"tanim":["ABD Ulusal Çevre Tahmin Merkezleri (NCEP / NOAA) tarafından işletilen küresel sayısal hava tahmin modelidir.","Günde dört ana koşuda (00, 06, 12, 18 UTC) dünya geneli için orta vadeli sayısal tahmin verileri üretir.","Sinoptik harita analizinde 500 hPa jeopotansiyel yükseklik, yer basıncı ve kalınlık desenleriyle atmosfer dinamiğini incelemede temel model olarak kullanılır."],"tanim_en":"A global numerical weather prediction system operated by the National Centers for Environmental Prediction that provides medium-range forecasts worldwide.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"infrared-satellite-imagery","tr":"Kızılötesi uydu görüntüsü","en":"infrared satellite imagery","kisa":"IR","tur":"cihaz","es":["IR kanal görüntüsü","termal kızılötesi","renkli IR","enhanced IR","renkliliği artırılmış kızılötesi","enhanced infrared imagery"],"tanim":["Yerden ve bulutlardan yayılan termal kızılötesi ışınımı algılayarak yüzey ve bulut tepe sıcaklıklarını haritalandıran uydu ürünüdür.","Işınım sıcaklığına bağlı olarak soğuk ve yüksek bulut tepeleri parlak beyaz ya da yapay renklerle, sıcak yüzeyler koyu tonlarla temsil edilir.","Gece ve gündüz kesintisiz gözlem sağlayarak derin konveksiyon alanlarının ve cephe bulut bantlarının dikey gelişimini izlemede kullanılır."],"tanim_en":"Satellite imagery that measures thermal radiation emitted by clouds and the Earth surface to determine cloud-top temperature both day and night.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"meteogram","tr":"Meteogram","en":"meteogram","kisa":"","tur":"cihaz","es":["zaman serisi diyagramı","meteogram chart","noktasal tahmin grafiği","noktasal zaman serisi"],"tanim":["Belirli tek bir coğrafi istasyon veya koordinat noktası için atmosferik değişkenlerin zamana bağlı seyrini gösteren grafiksel zaman serisidir.","Grafikte sıcaklık, basınç, bağıl nem, rüzgâr hızı, rüzgâr yönü ve yağış miktarı gibi meteorolojik parametreler ortak bir zaman ekseninde dikey paneller halinde sunulur.","Sinoptik analiz ve tahmin brifinglerinde, sayısal model koşusundan tek bir nokta için saatlik yerel hava değişimlerini çıkarmada kullanılır."],"tanim_en":"A graphical presentation of the variation of several meteorological variables with time at a single geographic location.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"meteosat-second-generation","tr":"Meteosat İkinci Nesil","en":"Meteosat Second Generation","kisa":"MSG","tur":"cihaz","es":["Meteosat","MSG uydusu","MSG","MSG IR 10.8","İkinci Nesil Meteosat Uydusu"],"tanim":["EUMETSAT tarafından işletilen, Avrupa ve Afrika üzerinde sabit yörüngede görev yapan meteoroloji uydusu sistemidir.","Görünür, su buharı ve kızılötesi dalga boylarında 12 tayfsal kanalda 15 dk aralıkla tam disk görüntüleme yapar.","Sinoptik harita analizi ve şimdi-tahmin çalışmalarında cephe sistemleri, jet akımları ve fırtınaların gelişimini izlemede birincil uydu verisi sağlar."],"tanim_en":"A series of geostationary meteorological satellites operated by EUMETSAT that provides high-resolution multispectral imagery of Europe and Africa every 15 min.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"plan-position-indicator","tr":"PPI görüntüsü","en":"Plan Position Indicator","kisa":"PPI","tur":"cihaz","es":["PPI taraması","plan position display","PPI","PPI ekranı","radar PPI taraması","Plan Pozisyon Göstergesi"],"tanim":["Radar anteninin sabit bir yükseliş açısında ufuk düzleminde 360° dönerek elde ettiği yağış ekolarını harita üzerinde yatay düzlemde gösteren radar ekran formatıdır.","Merkezde radar sahası yer alır; menzil halkaları boyunca eko şiddeti logaritmik yansıtırlık birimi olan dBZ cinsinden renk skalasıyla sunulur.","Sinoptik haritalarla birlikte okunarak cephesel yağış hatlarının ve konvektif hücrelerin konumu ile şiddetini tespit etmede kullanılır."],"tanim_en":"A radar display that presents echoes from a 360-degree azimuthal sweep at a fixed elevation angle on a horizontal plane relative to the antenna.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"skew-t-log-p-diagram","tr":"Skew-T log-P diyagramı","en":"Skew-T log-P diagram","kisa":"Skew-T","tur":"cihaz","es":["Skew-T diyagramı","aerolojik diyagram","thermodynamic diagram","Skew-T log-P","termodinamik diyagram","Skew-T"],"tanim":["Atmosferin termodinamik durumunu basınç, sıcaklık ve nem değişkenleriyle temsil etmekte kullanılan ve eşit alanların eşit enerjiye karşılık geldiği termodinamik diyagramdır.","Yatay eksen sağa eğik izotermleri, düşey eksen logaritmik basınç seviyelerini gösterir; kuru adyabat, doymuş adyabat ve doyma karışma oranı çizgilerini içerir.","Radyosonde verilerini işleyerek inversiyon tabakalarını, kararlılık durumunu ve konvektif potansiyeli belirlemede temel analiz aracıdır."],"tanim_en":"A thermodynamic diagram with skewed temperature lines and a logarithmic pressure axis used to evaluate the vertical thermodynamic state and stability of the atmosphere.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"weather-radar","tr":"Hava radarı","en":"weather radar","kisa":"","tur":"cihaz","es":["meteoroloji radarı","doppler radarı","Meteoroloji radar ürünü","Radar görüntüsü","Radar imagery"],"tanim":["Hidrometeorolojik olayları tespit etmek, konumlandırmak ve miktarını belirlemek amacıyla yönlendirilmiş elektromanyetik dalgalar yayan aktif uzaktan algılama sistemidir.","Yağış parçacıklarından geri saçılan mikrodalga enerjisini ölçerek yansıtırlık (dBZ), radyal hız ve polarimetrik parametreler üretir.","Sinoptik ve yerel analizlerde cephe hatları, fırtına hücreleri ve ani yağış alanlarının anlık takibinde birincil yer gözlem aracıdır."],"tanim_en":"An observational system designed to detect, locate, and quantify hydrometeorological phenomena by emitting beamed electromagnetic radiation.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"wrf-model","tr":"WRF modeli","en":"Weather Research and Forecasting model","kisa":"WRF","tur":"cihaz","es":["WRF sayısal hava modeli","WRF-ARW","WRF","WRF meteogram","mesoölçek sayısal model","Hava Araştırma ve Tahmin Modeli"],"tanim":["Atmosferik araştırmalar ve operasyonel hava tahmini için geliştirilmiş, hidrostatik olmayan, yüksek çözünürlüklü bölgesel sayısal hava tahmin modelidir.","Küresel modellerden sınır ve başlangıç koşullarını alarak iç içe yuvalanmış ızgaralar üzerinde yerel topoğrafyayı ve konveksiyonu çözer.","Sinoptik analizlerde ve brifinglerde belirli bir havza ya da istasyon için detaylı yağış miktarı ve meteogram öngörüleri üretmede kullanılır."],"tanim_en":"A next-generation mesoscale numerical weather prediction system designed for both atmospheric research and operational forecasting.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"atmospheric-instability","tr":"Kararsızlık","en":"Instability","kisa":"","tur":"kavram","es":["Atmosferik kararsızlık","statik kararsızlık","instability","atmospheric instability","termal kararsızlık"],"tanim":["Düşey doğrultuda yer değiştiren bir hava parselinin, çevresindeki havadan daha sıcak kalarak yukarı yönlü ivmelenmeye devam ettiği atmosferik durumdur.","Doymamış hava için çevre sıcaklık azalma oranı kuru adyabatikten, doymuş hava için doymuş adyabatikten büyükse kararsızlık vardır; Skew-T diyagramında parsel eğrisinin çevre eğrisinin sağında kaldığı pozitif alanla görülür.","Sinoptik analizlerde konvektif bulutların, sağanak yağışların ve orajların temel itici koşulu olarak değerlendirilir."],"tanim_en":"A state of the atmosphere in which a vertically displaced air parcel accelerates upward away from its original level.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"atmospheric-stability","tr":"Kararlılık","en":"Stability","kisa":"","tur":"kavram","es":["Atmosferik kararlılık","statik kararlılık","kararlı atmosfer","static stability","atmospheric stability"],"tanim":["Dikey olarak yer değiştiren bir hava parselinin, çevresine göre daha soğuk kalarak başladığı denge seviyesine geri dönme eğilimidir.","Çevre sıcaklık azalma oranı doymamış hava için kuru adyabatikten, doymuş hava için doymuş adyabatikten küçükse kararlılık vardır; inversiyon ve izotermal tabakalar çok kararlıdır.","Sinoptik analizlerde dikey hava hareketlerini bastıran, sis ve tabakalı bulut oluşumunu destekleyen, konvektif fırtınaları engelleyen bir faktör olarak izlenir."],"tanim_en":"A state of the atmosphere in which vertical motion is suppressed and a displaced air parcel tends to return to its original level.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"convective-cell","tr":"Konvektif hücre","en":"convective cell","kisa":"","tur":"kavram","es":["yağış hücresi","fırtına hücresi","storm cell","convection cell"],"tanim":["Organize konveksiyon hareketi sergileyen, komşu hava ile karışımı sınırlı düşey hava akımı birimidir.","Tek bir yükselici ve alçalıcı akım çiftinden oluşur; çok hücreli fırtınalar bu hücrelerin birleşimidir ve radar ekolarında bağımsız çekirdekler olarak izlenir.","Konvektif fırtınaların ve sağanakların temel yapı taşını oluşturur."],"tanim_en":"An organized convective air volume with a systematic internal motion pattern and minimal mixing with adjacent environmental air.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"model-run","tr":"Model koşusu","en":"model run","kisa":"","tur":"kavram","es":["koşu saati","base time","model cycle","model başlangıç zamanı","sayısal model koşusu","model döngüsü"],"tanim":["Sayısal hava tahmin modelinin belirli bir başlangıç analiz verisine dayanarak geleceğe yönelik simülasyon üretmek üzere çalıştırılması.","Ürün başlığında başlangıç saati (base time), öngörü saati (ör. +24) ve geçerlilik zamanıyla (valid time) tanımlanır; +24 koşudan 24 saat sonrasını gösterir.","Sinoptik tahmin sürecinde farklı model koşularının tutarlılığı incelenerek sistemlerin konumu ve derinleşme eğilimi takip edilir."],"tanim_en":"A model run is a single execution of a numerical weather prediction model initialized from an atmospheric analysis to produce forecast fields.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"radar-echo","tr":"Radar ekosu","en":"radar echo","kisa":"","tur":"kavram","es":["yağış ekosu","precipitation echo","radar yansıması"],"tanim":["Radardan gönderilen elektromanyetik pals enerjisinin atmosferdeki hidrometeorlara çarparak alıcıya geri dönen kısmıdır.","Yansıma şiddeti dBZ birimiyle ifade edilir; haritada yağışın konumu ve şiddeti renk ölçeğiyle gösterilir.","Uydu bulut tepesini görürken radar doğrudan havadaki yağış parçacıklarını tespit eder; menzil içinde eko yoksa yağış büyük olasılıkla yoktur (uzakta ışın yerden yükseldiği için sığ yağışı aşabilir)."],"tanim_en":"The portion of pulsed radar beam energy reflected back to the receiver after intercepting precipitation particles in the atmosphere.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"radiation-inversion","tr":"Işınım inversiyonu","en":"radiation inversion","kisa":"","tur":"kavram","es":["radyasyon inversiyonu","radyasyonel enversiyon","yer inversiyonu","surface-based inversion","yerden inversiyon","gece ışınım inversiyonu"],"tanim":["Gece yer yüzeyinin uzun dalga ışınım kaybıyla soğuması sonucu yüzeye yakın hava katmanında sıcaklığın yükseklikle artması durumudur.","Yere temas eden tabakada oluşur; Skew-T log-P diyagramında tabanı yer seviyesinde olan sıcaklık artışıyla tanınır.","Durgun ve açık gecelerde alt atmosferi kararlı hale getirerek dikey karışımı engeller, sis veya pus oluşumuna elverişli zemin hazırlar."],"tanim_en":"A surface-based temperature inversion produced by nocturnal radiational cooling of the Earth's surface.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"range-rings","tr":"Menzil halkaları","en":"Range rings","kisa":"","tur":"kavram","es":["mesafe halkaları","uzaklık halkaları","radar range rings"],"tanim":["Radar ekranında radar merkezinden itibaren sabit aralıklarla çizilen eşmerkezli referans daireleridir.","Kilometre veya deniz mili cinsinden ölçeklenir; ekoların istasyona olan uzaklığını doğrudan okutur.","Yağış kütlesinin hedefe mesafesini tayin etmede ve radarın kapsama sınırını değerlendirmede kullanılır."],"tanim_en":"Concentric circles displayed on a radar display at fixed radial intervals to facilitate direct evaluation of target distance from the antenna.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"troposphere","tr":"Troposfer","en":"Troposphere","kisa":"","tur":"kavram","es":["alt atmosfer","troposfer tabakası"],"tanim":["Yeryüzünden başlayıp kutuplarda yaklaşık 9 km, ekvatorda yaklaşık 17 km yüksekliğe kadar uzanan atmosferin en alt katmanıdır.","Standart atmosferde sıcaklık bu tabaka boyunca ortalama 6,5 K/km oranıyla yükseklikle düzenli olarak azalır.","Atmosferik kütlenin ve su buharının büyük kısmını barındırır; bulut, yağış ve sinoptik hava sistemleri bu katmanda meydana gelir."],"tanim_en":"The lowest layer of the atmosphere, extending from the surface to the tropopause, characterized by a general decrease in temperature with height.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"weather-briefing","tr":"Hava brifingi","en":"weather briefing","kisa":"","tur":"kavram","es":["hava analizi brifingi","meteorological briefing","meteoroloji brifingi"],"tanim":["Mevcut ve beklenen atmosferik koşulları özetlemek üzere gözlem verileri, analiz haritaları, uydu-radar ürünleri ve sayısal model çıktılarını bir araya getiren teknik sunumdur.","Analiz kartları, Skew-T diyagramları ve tahmin haritaları kullanılarak sinoptikten yerel ölçeğe doğru yapılandırılır.","Operasyonel karar alma süreçlerinde hava risklerini ve kritik gelişmeleri ilgili birimlere aktarmada temel iletişim yöntemidir."],"tanim_en":"A structured oral and visual presentation synthesizing current meteorological observations and numerical model guidance to summarize existing and forecast weather conditions.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"brightness-temperature","tr":"Işınım sıcaklığı","en":"brightness temperature","kisa":"TB","tur":"olcu","es":["parlaklık sıcaklığı","equivalent blackbody temperature","radyasyon sıcaklığı","radiance temperature","bulut tepesi sıcaklığı","cloud-top temp"],"tanim":["Bir cismin yaydığı ışıma şiddetine eşit miktarda ışıma yapan bir kara cismin belirli bir dalga boyundaki eşdeğer sıcaklığıdır.","Meteorolojide Kelvin (K) veya Santigrat derece (°C) cinsinden ifade edilir; uyduların kızılötesi kanallarında ölçülür.","Troposferde yükseklikle sıcaklık düştüğünden bulut tepesi yüksek olan konvektif bulutlar uydu görüntüsünde daha soğuk ışınım sıcaklığı sergiler."],"tanim_en":"The temperature of a blackbody emitting the same radiance at a given spectral band as the observed target.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"convective-available-potential-energy","tr":"Konvektif kullanılabilir potansiyel enerji","en":"Convective available potential energy","kisa":"CAPE","tur":"olcu","es":["CAPE","konvektif yararlı potansiyel enerji","konvektif kararsızlık enerjisi","Konvektif yararlı potansiyel enerji"],"tanim":["Serbest konveksiyon seviyesinden denge seviyesine kadar yükselen bir hava parseline etki eden net pozitif kaldırma kuvvetinin yaptığı işi temsil eden enerjidir.","Birimi J kg⁻¹ olup Skew-T log-P diyagramında parsel yörüngesi ile çevre sıcaklık eğrisi arasında kalan pozitif alan ile belirlenir.","Konvektif fırtınaların, dolu ve şiddetli hamlelerin potansiyel gücünü değerlendirmede temel termodinamik kararsızlık parametresidir."],"tanim_en":"The vertically integrated positive buoyant energy available to a rising air parcel from the level of free convection to the equilibrium level.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"forecast-hour","tr":"Öngörü saati","en":"Forecast lead time","kisa":"+0 / +24","tur":"olcu","es":["tahmin saati","tahmin adımı","forecast hour","+24 sa öngörü","24-h prognosis","24 saatlik tahmin"],"tanim":["Sayısal hava tahmin modelinin başlangıç anı ile model çıktısının geçerli olduğu hedef an arasındaki zaman farkıdır.","Saat cinsinden «+0», «+24» veya «+48» şeklinde gösterilir; «+0» analiz zamanını ifade eder.","Model harita künyesinde yer alarak sunulan verinin hangi tahmin ufkuna ait olduğunu belirtir."],"tanim_en":"The time interval between the initialization of a numerical model run and the valid verification time of the forecast field.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"k-index","tr":"K indeksi","en":"K Index","kisa":"KI","tur":"olcu","es":["George K indeksi","K kararlılık indeksi","George K index","K kararsızlık indisi","K index","KI"],"tanim":["850 hPa ile 500 hPa arasındaki sıcaklık farkı, 850 hPa çiy noktası ve 700 hPa çiy noktası açığı birleştirilerek hesaplanan kararsızlık indeksidir.","Sayısal bir indeks değeri üretir; yüksek pozitif değerler konvektif fırtına ve oraj olasılığını gösterir.","Negatif veya düşük değerler orta seviyenin kuru ve kararlı olduğunu belirterek oraj gelişiminin beklenmediğine işaret eder."],"tanim_en":"An index of thunderstorm potential computed from temperature and moisture parameters at the 850, 700, and 500 hPa levels.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"precipitable-water","tr":"Yağışa dönüşebilir su","en":"precipitable water","kisa":"PW","tur":"olcu","es":["toplam su buharı","precipitable water vapor","yoğuşabilir su miktarı","PW"],"tanim":["Atmosfer sütunundaki tüm su buharının yoğuşup yere inmesi durumunda oluşacak toplam su derinliği olarak tanımlanır.","Birimi milimetre (mm) veya kilogram bölü metrekare (kg m⁻²); radyosonde ölçümleri ile uydu su buharı kanallarından hesaplanır.","Sinoptik ve mezoolçek analizlerde hava kütlesinin nem içeriğini ve aşırı yağış potansiyelini belirlemede kullanılır."],"tanim_en":"The amount of water that would be obtained if all the water vapour in an atmospheric column were condensed and precipitated.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"quantitative-precipitation-forecast","tr":"Yağış miktarı tahmini","en":"Quantitative precipitation forecast","kisa":"QPF","tur":"olcu","es":["birikimli yağış tahmini","QPF","yağış tutarı tahmini","yağış tahmini haritası","precipitation forecast"],"tanim":["Belirli bir coğrafi alanda ve tanımlı bir zaman diliminde yere düşmesi beklenen yağış miktarının sayısal tahminidir.","Birimi milimetre (mm) veya kilogram bölü metrekare (kg m⁻²); sayısal hava tahmin modelleri çıktılarında birikimli renk aralıklarıyla sunulur.","Hava tahmin analizlerinde sel tehlikesi, havza yönetimi ve yerel kar örtüsü birikimini öngörmede temel ürün olarak kullanılır."],"tanim_en":"A forecast of the expected amount of liquid or melted precipitation accumulated over a specified area during a defined time interval.","bag":{"kavram":[],"soru":[],"hesap":[]}},{"id":"total-totals-index","tr":"Total Totals indeksi","en":"Total Totals Index","kisa":"TTI","tur":"olcu","es":["TT indeksi","Total Totals","TT indisi","Total Totals kararsızlık indisi","Total Totals index"],"tanim":["Şiddetli konvektif fırtınaları tahmin etmek amacıyla 850 hPa ve 500 hPa seviyelerindeki sıcaklık ve nem verileriyle hesaplanan kararsızlık indisidir.","Düşey toplam (VT = T₈₅₀ − T₅₀₀) ile çapraz toplamın (CT = Td₈₅₀ − T₅₀₀) toplamıdır: TT = T₈₅₀ + Td₈₅₀ − 2·T₅₀₀; sıcaklıklar °C girilir, sonuç birimsiz bir indeks olarak okunur.","ABD uygulamasındaki eşiklere göre ≈ 44–46 üstü oraj, 55 üstü şiddetli fırtına ve hortum olasılığına işaret eder; eşikler bölgeye göre değişir."],"tanim_en":"A convective instability index computed from 850 hPa and 500 hPa temperature and dew-point data to evaluate severe thunderstorm potential.","bag":{"kavram":[],"soru":[],"hesap":[]}}]};
